//! Потоковая индексация: документ → слова → сегмент.

use std::collections::HashMap;
use std::fs::{create_dir_all, File};
use std::io::Write;

use crate::analyze::{Analyzer, Simple};
use crate::bits::BLOCK;
use crate::index::Kind;
use crate::norms::{dl_part, level};

/// Списки в памяти: слово → номера документов сегмента, уже по возрастанию.
/// Список одного слова в одном поле: номера документов и частоты.
///
/// Частота байтом, а редкая большая — отдельным списком.
///
/// Отсюда развилка: платить словом за все постинги или байтом за все и списком
/// за редкие. На настоящем тексте частота переваливает за 255 у долей процента
/// постингов, поэтому второе — 255 в байте значит «смотри `big`».
/// Частота, не поместившаяся в байт: признак «смотри `Postings::big`».
const BIG_TF: u8 = 255;

#[derive(Default)]
struct Postings {
    /// Последняя эпоха, в которой ключ попал в список delta publication.
    touched_epoch: u64,
    docs: Vec<u32>,
    /// Частота или 255 — признак «частота лежит в [`Buffer::big`]».
    tfs: Vec<u8>,
    /// Позиции всех вхождений подряд: у документа их столько, сколько его `tf`.
    ///
    /// Плоским вектором, а не вектором векторов: вхождений на порядок больше,
    /// чем документов, и заголовок вектора на каждый документ стоил бы больше
    /// самих позиций.
    poss: Vec<u32>,
}

#[derive(Default)]
struct DeltaTrace {
    /// Ноль — библиотечный режим без delta publication.
    epoch: u64,
    keys: Vec<Box<[u8]>>,
    key_bytes: usize,
    published_docs: u32,
    published_units: Vec<usize>,
}

impl DeltaTrace {
    fn touch(&mut self, key: &[u8], postings: &mut Postings) {
        if self.epoch != 0 && postings.touched_epoch != self.epoch {
            postings.touched_epoch = self.epoch;
            self.keys.push(key.into());
            self.key_bytes = self.key_bytes.saturating_add(key.len());
        }
    }

    fn clear(&mut self) {
        let enabled = self.epoch != 0;
        *self = Self { epoch: u64::from(enabled), ..Self::default() };
    }

    fn bytes(&self) -> usize {
        self.key_bytes
            .saturating_add(self.keys.capacity().saturating_mul(std::mem::size_of::<Box<[u8]>>()))
            .saturating_add(
                self.published_units.capacity().saturating_mul(std::mem::size_of::<usize>()),
            )
    }
}

/// Отображение «идентификатор → номера документов в буфере приёма».
///
/// Зачем она вообще нужна. Гашение ищет документ по обратным отображениям
/// сегментов, но принятый документ до полутора секунд лежит **только в буфере**,
/// и ни в одном сегменте его нет. Без этой таблицы замена не видит того, что
/// сама же положила секунду назад, и кладёт вторую живую версию рядом.
///
/// Ячейки не освобождаются даже у погашенных документов: цепочка проб
/// обрывается первой пустой ячейкой, и дыра посреди неё спрятала бы всё, что
/// лежит за ней.
#[derive(Default)]
struct Slots {
    /// Номер документа плюс один. Ноль — ячейка пуста.
    cells: Vec<u32>,
    filled: usize,
    /// Пустые ID допустимы у библиотечного приёма. Одинаковый хеш сотен
    /// тысяч таких документов превращал линейное пробирование в O(n²).
    /// Их номера храним отдельно, сохраняя поиск и гашение всех копий.
    empty: Vec<u32>,
}

impl Slots {
    fn clear(&mut self) {
        self.cells.clear();
        self.filled = 0;
        self.empty.clear();
    }

    /// Кладёт номер документа. `ids` нужны для пересборки при росте.
    fn insert(&mut self, h: u64, doc: u32, ids: &[String]) {
        if ids[doc as usize].is_empty() {
            self.empty.push(doc);
            return;
        }
        if (self.filled + 1) * 4 >= self.cells.len() * 3 {
            self.grow(ids);
        }
        self.put(h, doc);
        self.filled += 1;
    }

    fn put(&mut self, h: u64, doc: u32) {
        let mask = self.cells.len() - 1;
        let mut at = (h as usize) & mask;
        while self.cells[at] != 0 {
            at = (at + 1) & mask;
        }
        self.cells[at] = doc + 1;
    }

    fn grow(&mut self, ids: &[String]) {
        let want = (self.cells.len() * 2).max(64);
        let old = std::mem::replace(&mut self.cells, vec![0u32; want]);
        for slot in old {
            if slot == 0 {
                continue;
            }
            let doc = slot - 1;
            self.put(crate::bloom::hash(&ids[doc as usize]), doc);
        }
    }

    /// Номера всех документов буфера с этим идентификатором — в конец `out`.
    ///
    /// Совпадение хеша ещё не совпадение: строка сверяется целиком, иначе
    /// столкновение гасило бы чужой документ.
    fn find(&self, h: u64, id: &str, ids: &[String], out: &mut Vec<u32>) {
        if id.is_empty() {
            out.extend_from_slice(&self.empty);
            return;
        }
        if self.cells.is_empty() {
            return;
        }
        let mask = self.cells.len() - 1;
        let mut at = (h as usize) & mask;
        while self.cells[at] != 0 {
            let doc = self.cells[at] - 1;
            if ids.get(doc as usize).map(String::as_str) == Some(id) {
                out.push(doc);
            }
            at = (at + 1) & mask;
        }
    }
}

struct Buffer {
    delta: DeltaTrace,
    /// Содержимое полей как оно пришло — для хранилища документов.
    ///
    /// Приходит **явно**, а не выводится как наибольший встреченный слот:
    /// последние элементы массива могут не иметь ни одного индексируемого
    /// поля, и вывод дал бы им исчезнуть.
    arity: Vec<Vec<u32>>,
    vals: Vec<Vec<String>>,
    /// Значения числовых полей и признак их наличия. Пусто у текстовых.
    cols: Vec<Vec<i64>>,
    has: Vec<Vec<bool>>,
    multi: Vec<crate::multivalue::Builder>,
    /// Плотные векторы по документам. Пусто у всех полей, кроме векторных.
    vecs: Vec<Vec<Vec<f32>>>,
    /// Ключ — **байты**: номер поля, а следом слово.
    ///
    /// Не `(u8, String)`, и это не мелочь оформления. У составного ключа со
    /// строкой поиск требует владеющего ключа, то есть копии слова на **каждое**
    /// вхождение в каждом документе. У байтового ключа `Box<[u8]>` заимствуется
    /// как `[u8]`, поэтому копия делается один раз — когда слово встречено
    /// впервые. Порядок при сортировке тот же: сначала поле, потом слово.
    lists: HashMap<Box<[u8]>, Postings>,
    /// Частоты, не поместившиеся в байт: список → (номер постинга, частота).
    ///
    /// Постинги списка кладутся по возрастанию номера, поэтому и здесь порядок
    /// возрастающий, и сброс проходит его одним курсором.
    big: HashMap<Box<[u8]>, Vec<(u32, u32)>>,
    norms: Vec<Vec<u8>>,
    docs: u32,
    /// Сколько байт памяти буфер уже занял — оценка, но своя у каждого куска.
    ///
    /// ## Почему не длина текста
    ///
    /// Прежде здесь стояла сумма длин принятых значений, и комментарий на этом
    /// месте объяснял, почему этого достаточно. Достаточно не было: текст —
    /// далеко **не** главный жилец буфера. У документа в полтораста токенов
    /// постинги занимают порядка полутора килобайт — больше самого текста, —
    /// плюс заголовок `String` на каждое поле, плюс байт нормы, плюс колонка.
    ///
    /// Из-за этого порог в 256 МБ срабатывал, когда буфер занимал два-три
    /// гигабайта, а на широкой схеме со сбросом по счётчику документов — все
    /// тринадцать. То есть порог, заведённый **против** роста памяти, роста
    /// памяти не видел.
    ///
    /// ## Почему оценка, а не измерение
    ///
    /// Точная мера потребовала бы обходить хеш-карту постингов на каждом
    /// документе — то есть тратить на учёт больше, чем на работу. Здесь же
    /// каждый `push` в буфер прибавляет свою известную цену: несколько
    /// сложений на документ.
    ///
    /// Считаются **запрошенные** байты — то, о чём попросили распределитель.
    /// Настоящий след больше: вектор растёт удвоением и в среднем держит
    /// четверть ёмкости впустую, у хеш-карты свои служебные ячейки. Поправку на
    /// это даёт [`SLACK`], и она не спрятана здесь нарочно: «сколько данных» и
    /// «сколько памяти под них» — разные величины, и путать их не стоит.
    bytes: usize,
    /// Будущие временные массивы doc values при build, не resident bytes буфера.
    build_reserve: usize,
    ids: Vec<String>,
    /// Погашенные до сброса: замена или удаление пришли, пока документ ещё
    /// лежит в буфере. Уходят в карту живых нового сегмента уже мёртвыми.
    dead: Vec<bool>,
    /// Где какой идентификатор лежит в буфере.
    slots: Slots,
}

/// Границы, за которые доля не выходит.
///
/// Снизу — чтобы на маленькой машине сегменты не выродились в россыпь по
/// мегабайту: укрупнение потом обойдётся дороже, чем сэкономленная память.
/// Сверху — потому что толку от буфера больше четырёх гигабайт нет: сегмент
/// такого размера всё равно придётся резать по числу документов, а страницы,
/// пролежавшие в буфере минуты, успевают вытеснить кеш чтения.
const BUFFER_MIN: u64 = 256 << 20;
const BUFFER_MAX: u64 = 4 << 30;

/// Ниже этого буфер не опускается ни при какой доле.
///
/// Не защита памяти, а защита состава: на буфере в единицы мегабайт сегменты
/// пошли бы десятками тысяч, и запрос заплатил бы за их обход больше, чем
/// приём выгадал бы на памяти. Восемь мегабайт — примерно двадцать тысяч
/// документов среднего размера, то есть сегмент, который ещё имеет смысл.
const BUFFER_FLOOR: u64 = 8 << 20;

/// Потолок буфера приёма по умолчанию — доля доступной памяти.
///
/// Зашитое число здесь неверно дважды: на машине в четыре гигабайта оно
/// отправило бы узел в своп, на машине в сто двадцать восемь — заставило бы
/// резать сегменты вчетверо мельче, чем стоило бы, и платить укрупнениями.
/// Память не узналась — берётся нижняя граница: осторожность дешевле догадки.
fn default_flush_bytes() -> usize {
    match Some(crate::govern::share(crate::govern::Class::Ingest)).filter(|v| *v > 0) {
        Some(ram) => {
            // Доля приёма делится надвое: буферов в обороте два — набираемый и
            // отданный писателю, — и обещать каждому всю долю значило бы обещать
            // вдвое больше, чем отведено.
            let share = ram / 2;
            // Пол не вправе быть выше доли.
            //
            // Прежде здесь стоял `clamp(BUFFER_MIN, BUFFER_MAX)`, и на малой
            // машине пол перебивал долю: в контейнере на гигабайт доля даёт сто
            // мегабайт, а пол поднимал порог до двухсот пятидесяти шести. Живых
            // буферов два, значит полгигабайта из гигабайта уходило на один
            // приём — плюс доля слияния, плюс кеш страниц, и ядро снимало
            // процесс. Пол задумывался как защита от вырожденно мелкого
            // буфера, а работал как обещание памяти, которой нет.
            //
            // У бюджета слияния этот же соблазн описан и отвергнут прямо в
            // комментарии к `merge_budget`: «доля, а не доля с полом». Здесь
            // было наоборот.
            //
            // Совсем без пола нельзя: на очень малой памяти сброс пошёл бы чуть
            // ли не на каждом документе, и сегментов стало бы столько, что
            // запрос захлебнулся бы на их обходе. Поэтому пол остаётся, но
            // опускается до доли, когда доля меньше.
            share.min(BUFFER_MAX).max(BUFFER_FLOOR.min(share.max(BUFFER_FLOOR))) as usize
        }
        None => BUFFER_MIN as usize,
    }
}

/// Во сколько раз настоящий след памяти больше запрошенных байт, в сотых.
///
/// Ошибиться здесь можно в обе стороны, но **не одинаково**: недооценка
/// означает, что буфер перерастёт отведённое ему и узел уйдёт в своп, а
/// переоценка — всего лишь лишний сегмент, который потом укрупнят. Поэтому
/// поправка берётся с запасом вверх.
///
/// Замерено собственным счётчиком выделений на две тысячи документов по
/// полтораста разных слов: запрошено 46.8 МБ, занято 66.8 МБ — 1.43. Берётся
/// 1.5, и это число закреплено проверкой `the_flush_estimate_tracks_real_growth`.
const SLACK: usize = 150;

/// Заголовок `String`/`Vec` — указатель, длина, ёмкость.
const HEAD: usize = std::mem::size_of::<String>();

/// Во что обходится буферу новое слово словаря.
///
/// Ключ (`Box<[u8]>`: заголовок плюс четыре байта номера поля плюс само слово,
/// оно считается отдельно), `Postings` с тремя векторами и epoch, ячейка хеш-карты.
/// Последняя у `hashbrown` — сам ключ со значением плюс байт управления, при
/// заполнении семь восьмых; полтора заголовка её и покрывают.
const NEW_WORD: usize = HEAD + 4 + std::mem::size_of::<Postings>() + HEAD;

impl Buffer {
    fn copy_delta(&self, groups: &[u32], ngroups: usize) -> std::io::Result<(Buffer, Vec<usize>)> {
        let bad = || std::io::Error::other("несогласованный raw buffer при delta publication");
        let from = self.delta.published_docs as usize;
        let docs = self.docs as usize;
        if from > docs {
            return Err(bad());
        }
        fn suffix<T: Clone>(values: &[T], from: usize, expected: usize) -> std::io::Result<Vec<T>> {
            if values.is_empty() {
                return Ok(Vec::new());
            }
            if values.len() != expected || from > expected {
                return Err(std::io::Error::other(format!(
                    "неполная колонка raw delta: len={} expected={} from={from}",
                    values.len(),
                    expected
                )));
            }
            Ok(values[from..].to_vec())
        }
        let mut first_units = Vec::with_capacity(ngroups);
        let mut end_units = Vec::with_capacity(ngroups);
        for group in 0..ngroups {
            let (first, end) = if let Some(arity) = self.arity.get(group) {
                if arity.len() != docs {
                    return Err(std::io::Error::other(format!(
                        "несогласованный raw buffer при delta publication: arity[{group}] len={} docs={} published_docs={from}",
                        arity.len(), docs
                    )));
                }
                let first = self.delta.published_units.get(group).copied().unwrap_or(0);
                let added = arity[from..]
                    .iter()
                    .try_fold(0usize, |sum, &n| sum.checked_add(n as usize))
                    .ok_or_else(bad)?;
                (first, first.checked_add(added).ok_or_else(bad)?)
            } else {
                (from, docs)
            };
            first_units.push(first);
            end_units.push(end);
        }
        let mut out = Buffer::new(self.norms.len());
        out.docs = self.docs - self.delta.published_docs;
        out.ids = self.ids.get(from..).ok_or_else(bad)?.to_vec();
        out.dead = self.dead.get(from..).ok_or_else(bad)?.to_vec();
        out.arity = self
            .arity
            .iter()
            .map(|arity| suffix(arity, from, docs))
            .collect::<std::io::Result<_>>()?;
        for field in 0..self.norms.len() {
            let group = groups.get(field).copied().unwrap_or(0) as usize;
            let first = *first_units.get(group).ok_or_else(bad)?;
            let end = *end_units.get(group).ok_or_else(bad)?;
            out.vals[field] = suffix(&self.vals[field], from, docs)?;
            out.norms[field] = suffix(&self.norms[field], from, docs)?;
            out.vecs[field] = suffix(&self.vecs[field], from, docs)?;
            out.cols[field] = suffix(&self.cols[field], first, end)?;
            out.has[field] = suffix(&self.has[field], first, end)?;
            out.multi[field] = self.multi[field].suffix(first);
        }
        // Только touched keys текущей эпохи, не весь растущий словарь.
        for key in &self.delta.keys {
            let source = self.lists.get(key).ok_or_else(bad)?;
            let at = source.docs.partition_point(|&doc| doc < self.delta.published_docs);
            if source.tfs.len() != source.docs.len() {
                return Err(bad());
            }
            let mut positions = 0usize;
            if !source.poss.is_empty() {
                for (local, &tf) in source.tfs[at..].iter().enumerate() {
                    let amount = if tf == BIG_TF {
                        let big = self.big.get(key).ok_or_else(bad)?;
                        let slot = big
                            .binary_search_by_key(&((at + local) as u32), |pair| pair.0)
                            .map_err(|_| bad())?;
                        big[slot].1 as usize
                    } else {
                        tf as usize
                    };
                    positions = positions.checked_add(amount).ok_or_else(bad)?;
                }
            }
            let p = Postings {
                touched_epoch: 0,
                docs: source.docs[at..].iter().map(|doc| doc - self.delta.published_docs).collect(),
                tfs: source.tfs[at..].to_vec(),
                poss: source
                    .poss
                    .get(source.poss.len().checked_sub(positions).ok_or_else(bad)?..)
                    .ok_or_else(bad)?
                    .to_vec(),
            };
            if p.docs.is_empty() {
                continue;
            }
            if let Some(big) = self.big.get(key) {
                let first = big.partition_point(|pair| pair.0 < at as u32);
                if first < big.len() {
                    out.big.insert(
                        key.clone(),
                        big[first..].iter().map(|&(slot, tf)| (slot - at as u32, tf)).collect(),
                    );
                }
            }
            out.lists.insert(key.clone(), p);
        }
        Ok((out, end_units))
    }

    fn reserve_keyword_build(&mut self, units: usize, values: usize, present: usize) {
        // Scalar columns не платят цену raw pairs массивов. Верхняя граница
        // дополнительных значений сохраняет повторы до dictionary dedup.
        self.build_reserve = self
            .build_reserve
            .saturating_add(units.saturating_mul(24))
            .saturating_add(values.saturating_sub(present).saturating_mul(96));
    }
    /// Прибавляет к оценке занятого. Одно место, чтобы цены не разошлись.
    #[inline(always)]
    fn took(&mut self, n: usize) {
        self.bytes += n;
    }

    fn new(nfields: usize) -> Buffer {
        Buffer {
            delta: DeltaTrace::default(),
            vals: vec![Vec::new(); nfields],
            cols: vec![Vec::new(); nfields],
            has: vec![Vec::new(); nfields],
            multi: (0..nfields).map(|_| crate::multivalue::Builder::default()).collect(),
            vecs: vec![Vec::new(); nfields],
            lists: HashMap::new(),
            big: HashMap::new(),
            norms: vec![Vec::new(); nfields],
            arity: Vec::new(),
            docs: 0,
            bytes: 0,
            build_reserve: 0,
            ids: Vec::new(),
            dead: Vec::new(),
            slots: Slots::default(),
        }
    }

    /// Опустошает буфер, **возвращая ядру то, что явно лишнее**.
    ///
    /// ## Почему просто `clear` было мало
    ///
    /// `Vec::clear` держит ёмкость, и это верно для обычного хода: следующий
    /// сегмент наберёт примерно столько же, а перевыделение на каждом сбросе —
    /// работа впустую.
    ///
    /// Но ёмкость от этого становится **высокой водой, которая не спадает
    /// никогда**. Одна пачка вдвое крупнее обычной — или один документ на
    /// мегабайт — поднимает `RSS` процесса до конца его жизни, и вернуть эту
    /// память ядру нечем: это куча, а не кеш страниц. На узле, который живёт
    /// месяцами, высокая вода набирается по худшему случаю за всё время.
    ///
    /// Поэтому лишнее отдаётся, но не всякое: до `KEEP` раз от занятого ёмкость
    /// оставляется как есть — это и есть та экономия, ради которой `clear`
    /// держит память. Отдаётся только то, что выше, и тогда сразу до занятого.
    fn clear(&mut self) {
        /// Во сколько раз ёмкость может превышать занятое, не считаясь лишней.
        ///
        /// Два, а не полтора и не четыре: рост `Vec` идёт удвоением, поэтому
        /// обычный разброс между сегментами укладывается в двойку, и порог ниже
        /// начал бы перевыделять на ровном ходу. Выше — перестал бы срабатывать
        /// на том самом случае, ради которого стоит.
        const KEEP: usize = 2;

        fn shrink<T>(v: &mut Vec<T>) {
            let used = v.len();
            v.clear();
            if v.capacity() > (used * KEEP).max(64) {
                v.shrink_to(used.max(64));
            }
        }

        for v in self.vals.iter_mut() {
            // Сами строки ужимать незачем: `clear` их уничтожает, и вся их
            // память уходит вместе с ними. Отдавать надо ёмкость **вектора**.
            shrink(v);
        }
        for c in self.cols.iter_mut() {
            shrink(c);
        }
        for h in self.has.iter_mut() {
            shrink(h);
        }
        for multi in &mut self.multi {
            multi.clear();
        }
        for v in self.vecs.iter_mut() {
            shrink(v);
        }
        // Отображение списков — самое крупное в буфере: у него и ключи слов, и
        // их вхождения. `HashMap::clear` тоже держит ёмкость.
        self.lists.clear();
        if self.lists.capacity() > 1024 {
            self.lists.shrink_to_fit();
        }
        self.big.clear();
        for n in self.norms.iter_mut() {
            shrink(n);
        }
        for a in self.arity.iter_mut() {
            shrink(a);
        }
        shrink(&mut self.ids);
        shrink(&mut self.dead);
        self.slots.clear();
        self.docs = 0;
        self.bytes = 0;
        self.build_reserve = 0;
        self.delta.clear();
    }
}

/// Складывает вхождения одного поля одного документа в буфер списков.
///
/// Свободной функцией, а не методом: тело держит заимствование `toks` и правит
/// `buf` с `key` одновременно, и через границу метода такие заимствования не
/// проходят.
///
/// `toks_at` — позиция каждого токена. У обычного текста это его номер по
/// порядку; у поля внутри массива — **номер элемента**, и тогда позиции идут с
/// пропусками. Пропуск законен: дельта-кодирование при записи сегмента требует
/// неубывания, а не смежности.
#[allow(clippy::too_many_arguments)]
fn write_postings(
    buf: &mut Buffer,
    key: &mut Vec<u8>,
    seen: &[(u64, u32)],
    toks: &crate::analyze::Tokens,
    toks_at: &[u32],
    f: usize,
    doc: u32,
    keep: bool,
) {
    let mut at = 0usize;
    let mut took = 0usize;
    while at < seen.len() {
        let word = toks.get(seen[at].1 as usize);
        let mut to = at + 1;
        while to < seen.len() && seen[to].0 == seen[at].0 && toks.get(seen[to].1 as usize) == word {
            to += 1;
        }
        let tf = (to - at) as u32;
        // Номер поля старшим байтом вперёд и ровно четырьмя байтами: ключи
        // сортируются как байтовые строки, и порядок обязан совпасть с порядком
        // «поле, слово». Один байт держал потолок в 256 полей.
        key.clear();
        key.extend_from_slice(&(f as u32).to_be_bytes());
        key.extend_from_slice(word);
        // Поиск заимствованным ключом, вставка — владеющим. Слово, встреченное
        // не впервые, копии не стоит вовсе, а таких подавляющее большинство.
        let e = match buf.lists.get_mut(key.as_slice()) {
            Some(e) => e,
            None => {
                took += NEW_WORD + word.len();
                buf.lists.entry(key.as_slice().into()).or_default()
            }
        };
        buf.delta.touch(key, e);
        e.docs.push(doc);
        // Копия ключа — только на редкой ветке. Заводить её на каждый постинг
        // ради долей процента переполнений значило бы удвоить самую горячую
        // строку приёма.
        let at_posting = e.tfs.len() as u32;
        let over = tf >= BIG_TF as u32;
        e.tfs.push(if over { BIG_TF } else { tf as u8 });
        if over {
            buf.big.entry(key.as_slice().into()).or_default().push((at_posting, tf));
        }
        if keep {
            // Все вхождения: частота честно их считает, и равенство «позиций
            // столько, сколько обещает частота», на котором стоит чтение,
            // держится само.
            e.poss.extend(seen[at..to].iter().map(|(_, p)| toks_at[*p as usize]));
            took += 4 * tf as usize;
        }
        // Постинг: номер документа и байт частоты.
        took += 5;
        at = to;
    }
    // Один раз на поле, а не на слово: заимствование `buf` внутри цикла уже
    // отдано записи, и лишний доступ к нему стоил бы больше сложения.
    buf.took(took);
}

/// Одно значение одного поля в одном элементе массива.
#[derive(Clone, Copy, Debug)]
pub struct Cell<'a> {
    /// Номер поля среди объявленных.
    pub field: usize,
    /// Номер элемента внутри группы поля. У корневого поля всегда ноль.
    pub slot: u32,
    pub text: &'a str,
}

/// Разделитель элементов в хранимой копии многоместного поля.
///
/// Управляющий символ, которого не бывает в тексте: если он всё же придёт,
/// приём его отвергнет — иначе два элемента склеились бы в один молча.
pub const US: char = '\u{1f}';

/// Префикс внутренней безколлизионной записи массива скаляров.
///
/// Это не stored source: source лежит отдельным JSON. Запись нужна только
/// горячему индексатору, чей прежний интерфейс принимает одну строку на поле.
pub const MULTI_PREFIX: &str = "\u{1e}svindb-mv1:";
/// Маркер словаря keyword. Он отличает присутствующую пустую строку от
/// отсутствующего значения; всякое настоящее значение получает тот же префикс,
/// поэтому пользовательская строка не может с ним столкнуться.
pub const KEYWORD_TAG: &str = "\u{1d}k:";
pub const PRESENCE_TERM: &str = "\u{1d}svindb-present";

pub fn keyword_term(text: &str, fold_case: bool) -> String {
    let mut out = String::from(KEYWORD_TAG);
    if fold_case {
        for ch in text.chars() {
            out.extend(ch.to_lowercase());
        }
    } else {
        out.push_str(text);
    }
    out
}

pub fn presence_term(kind: Kind) -> String {
    if kind.keyword() {
        format!("\u{1d}kp:{}", u8::from(kind.folds_case()))
    } else {
        PRESENCE_TERM.to_string()
    }
}

/// Кодирует значения длинами в байтах. Разделителя внутри данных нет, поэтому
/// любой Unicode и любой управляющий символ остаются однозначными.
pub fn encode_multi(values: &[String]) -> String {
    let mut out = String::from(MULTI_PREFIX);
    for value in values {
        out.push_str(&value.len().to_string());
        out.push(':');
        out.push_str(value);
    }
    out
}

/// Разбирает внутреннюю запись. `None` — обычное скалярное значение.
pub fn multi_parts(text: &str) -> Option<Vec<&str>> {
    let mut rest = text.strip_prefix(MULTI_PREFIX)?;
    let mut out = Vec::new();
    while !rest.is_empty() {
        let colon = rest.find(':')?;
        let len = rest[..colon].parse::<usize>().ok()?;
        rest = &rest[colon + 1..];
        if len > rest.len() || !rest.is_char_boundary(len) {
            return None;
        }
        let (value, tail) = rest.split_at(len);
        out.push(value);
        rest = tail;
    }
    Some(out)
}

/// Кладёт кусок списка: номера, а следом частоты — если они нужны.
///
/// У одиночного слова куска нет вовсе: его единственный номер лежит в записи
/// слова, и звать это незачем.
///
/// ## Почему полоса частот пропускается только у короткого списка
///
/// Пропуск даёт байт ширины на блок. У короткого списка блок один, то есть байт
/// на слово, и таких слов большинство — это заметно. У длинного это байт на сто
/// двадцать восемь постингов, то есть 0.3 Б/док на настоящем корпусе.
///
/// А стоит он дорого: признак относится ко всему списку, значит писателю надо
/// знать все частоты **до** первого блока. Индексатор их знает, слияние — нет:
/// оно идёт потоком по нескольким источникам сразу. Ради 0.3 Б/док пришлось бы
/// либо проходить каждый длинный список дважды, либо держать его целиком в
/// памяти, а на боевом сегменте это гигабайты. Правило одно на обоих писателей,
/// иначе сегмент отличался бы тем, кто его сделал.
pub(crate) fn write_run(
    bytes: &mut Vec<u8>,
    bp: &mut u64,
    docs: &[u32],
    tfs: &[u32],
    with_tfs: bool,
) {
    crate::bits::pack(bytes, docs, bp);
    if with_tfs {
        crate::bits::pack_values(bytes, tfs, bp);
    }
}

/// Кладёт позиции блока в общий поток.
///
/// Указатель на него хранится только у длинного списка: у короткого блок один,
/// и смещение куска лежит в записи слова; у одиночного слова с единственным
/// вхождением позиция лежит там же, и в `pos.bin` от него не остаётся ничего.
pub(crate) fn write_positions(
    bytes: &mut Vec<u8>,
    vals: &[u32],
    keep: bool,
    df: u32,
    tf_all_one: bool,
) {
    // Потолок проверяет **зовущий**, до записи: и приём, и слияние делают это
    // одним сравнением рядом с потолком списков (`merge::fits_offset`).
    //
    // Страховка ниже — только для приёма, и только в отладке. Приём копит
    // `pos.bin` в памяти целиком, и его `bytes` это весь поток; слияние с тех
    // пор пишет позиции потоком и передаёт сюда черновик **одного** слова, где
    // до четырёх гигабайт не дорасти. Сторожем ему служит `fits_offset` по
    // длине уже записанного, и другого здесь быть не может: настоящей длины
    // потока эта функция больше не видит.
    debug_assert!(bytes.len() <= u32::MAX as usize, "позиции за четырьмя гигабайтами");
    if !keep || vals.is_empty() || (df == 1 && tf_all_one) {
        return;
    }
    let mut bp = 0u64;
    let step = crate::index::POSBLOCK;
    for chunk in vals.chunks(step) {
        crate::bits::pack_values(bytes, chunk, &mut bp);
    }
}

/// Immutable delta и хранитель замен: runtime публикует все поколения
/// одним ReadView и применяет supersede от старших поколений к младшим.
#[derive(Clone)]
pub struct FrozenGeneration {
    pub index: std::sync::Arc<crate::index::Index>,
    pub superseded: std::sync::Arc<[String]>,
}

struct FrozenMemtables {
    active: Vec<FrozenGeneration>,
    inflight: Vec<FrozenGeneration>,
    /// Граница supersede до передачи старой партии flusher. При отказе
    /// восстанавливается вместе с inflight; после успеха новая raw-эпоха
    /// начинается с нуля.
    inflight_recorded_superseded: usize,
    recorded_superseded: usize,
    max_generations: usize,
}

// Имена memory sources не являются путями. Разные Indexer и старые PIT
// не должны получить одинаковую identity даже после смены raw buffer.
static NEXT_FROZEN: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

pub struct Indexer<A: Analyzer = Simple> {
    /// Идентификаторы, чьи прежние версии обязаны погаснуть, когда нынешний
    /// буфер станет видимым.
    ///
    /// ## Почему список едет с буфером, а не гасится сразу
    ///
    /// Замена — это два события с разной задержкой видимости: старая версия
    /// перестаёт быть нужной сразу, новая становится видимой только с
    /// публикацией. Гаси старую при записи — и между этими событиями у
    /// документа не остаётся ни одной живой версии. Поиск отвечает пустотой на
    /// документ, который никуда не девался, и тем дольше, чем реже публикация.
    ///
    /// Поэтому гашение откладывается до публикации и применяется тем, кто вносит
    /// сегмент в состав, — см. [`crate::maintain::supersede_in`].
    superseded: Vec<String>,
    /// То же для буфера, отданного на запись: он ещё не опубликован.
    inflight_superseded: Vec<String>,
    /// Sorted hashes of every ID in the flying raw buffer. Hash collisions
    /// only cause an unnecessary wait; a negative lookup is definitive.
    inflight_id_hashes: Vec<u64>,
    /// Живой сегмент буфера, отданного писателю.
    ///
    /// ## Зачем он отдельно от живого сегмента текущего буфера
    ///
    /// Живых буферов бывает два: тот, что набирается, и тот, что пишется. Первый
    /// показывает поиску живой сегмент, собранный по таймеру. Второй не
    /// показывает никто: из текущего буфера его уже забрали, а сегмента на диске
    /// ещё нет. Всё время записи его документы невидимы — и это не отвлечённая
    /// дыра: гашение прежних версий к тому моменту уже прошло, так что документ
    /// пропадает **совсем**, а не показывает старую версию. Поймано стендом под
    /// нагрузкой; на спокойном узле запись успевает лечь между двумя запросами.
    ///
    /// Поэтому он собирается здесь же, в момент передачи, из того самого буфера,
    /// и живёт в составе до посадки.
    inflight_live: Option<std::sync::Arc<crate::index::Index>>,
    frozen: Option<FrozenMemtables>,
    manifest_ready: bool,
    /// То же для сегментов, которые уже легли: каталог сегмента и его список.
    ///
    /// Каталог здесь не для сообщений: он и есть хранитель новой версии, без
    /// которого гасить прежние нельзя — см. [`crate::maintain::supersede_in`].
    /// Пар может накопиться несколько: посадок между двумя публикациями бывает
    /// больше одной.
    landed_superseded: Vec<(String, Vec<String>)>,
    dir: String,
    fields: Vec<String>,
    /// Устойчивые номера полей из реестра.
    fids: Vec<u32>,
    /// Номер группы каждого поля. Пусто — все поля корневые, то есть одно
    /// значение на документ.
    groups: Vec<u32>,
    /// Путь каждой группы по её номеру. Корневая — пустая строка.
    group_paths: Vec<String>,
    boosts: Vec<f64>,
    kinds: Vec<Kind>,
    /// Хранить ли содержимое поля. Объявляется `имя:тип:nostore`.
    stored: Vec<bool>,
    /// Искать ли по полю. Объявляется `имя:тип:noindex` — обратное `nostore`.
    ///
    /// Такому полю не достаётся ни списка в словаре, ни колонки: содержимое
    /// лежит и отдаётся в выдаче, но найти по нему нельзя. Нужно там, где поле
    /// возвращают целиком и никогда не спрашивают, — сырой HTML, вложение,
    /// разметка. У Elasticsearch то же самое зовётся `index: false`.
    searched: Vec<bool>,
    /// Потолок объёма буфера в байтах. `0` — только по числу документов.
    ///
    /// Второй порог рядом со счётчиком документов, и он не дублирует его, а
    /// закрывает случай, которого счётчик не видит: документы бывают разного
    /// размера. Миллион сообщений по семьдесят байт — это семьдесят мегабайт,
    /// а миллион статей по мегабайту — терабайт, и одно и то же число «на
    /// сегмент» означает для них несравнимые вещи.
    ///
    /// Так же устроен и Lucene: у `IndexWriter` порог задан памятью
    /// (`ramBufferSizeMB`), а не числом документов.
    flush_bytes: usize,
    /// Печатается ли значение числового поля обратно **тем же** текстом.
    ///
    /// Ложь хоть у одного документа означает, что копию текста снимать нельзя:
    /// `007`, `1.50`, `+5` и `n/a` из колонки не восстановимы. Проверка идёт на
    /// приёме, по значению, а не по типу поля: тип не знает, что в него положат.
    exact: Vec<bool>,
    /// Хранить ли позиции слов. Объявляется `имя:text:nopos`.
    ///
    /// Позиции стоят от трети до половины файла списков, и поле, по которому
    /// фраз не спрашивают, платить за них не обязано. Умолчание — хранить: фраза
    /// по необъявленному полю обязана работать, а не отказывать.
    positioned: Vec<bool>,
    /// Порог частоты, ниже которого слово не хранит позиций.
    ///
    /// Ноль — хранят все, и это умолчание: `full` остаётся тем, что получает
    /// индекс, который ни о чём не просил. Порог включается объявлением, потому
    /// что он меняет не размер, а **договор**: слово без позиций обязано быть
    /// проверяемым по тексту, и без хранимого содержимого фраза по нему
    /// перестала бы отвечать вовсе.
    ///
    /// На диск уходит не он, а наибольшая наблюдённая частота слова без позиций
    /// — см. `posmin` у [`crate::index::Index`]. Порог принадлежит писателю,
    /// граница принадлежит читателю, и это разные числа.
    posmin: u32,
    /// Номер последней записи журнала, **действительно попавшей в сегмент**.
    ///
    /// Отличается от [`Indexer::seq`] тем, что говорит о записанном на диск, а
    /// не о принятом в буфер. Отметку журнала можно двигать только по нему:
    /// `seq` относится к последнему документу пачки, а сброс мог случиться в её
    /// середине — и тогда отметка объявила бы долговечным то, что живёт в
    /// памяти процесса.
    pub flushed_seq: u64,
    /// Номер последней записи журнала, попавшей в буфер.
    ///
    /// Уходит в заголовок сегмента при сбросе. Приём, идущий без журнала,
    /// оставляет ноль — и восстанавливать тогда нечего.
    pub seq: u64,
    per_segment: u32,
    analyzer: A,
    buf: Buffer,
    /// Опустошённый буфер, дожидающийся следующего сброса.
    ///
    /// ## Зачем понадобился
    ///
    /// Писатель возвращает буфер с прижившимися ёмкостями, и приём обязан был
    /// брать его себе. Но взять его можно только вместо пустого — в непустой
    /// ёмкость не перелить, не переложив содержимого, — а под плотной заливкой
    /// текущий буфер пуст почти никогда: результат первым забирает `poll` с
    /// пути свежести, когда в новый буфер уже набрали. Возвращённый выбрасывался,
    /// и следующий цикл отращивал ёмкости с нуля лестницей удвоений.
    ///
    /// Цена этому измерена: на пятнадцати миллионах документов расход падал на
    /// 27%, стоило сроку свежести вырасти настолько, чтобы буфер успевал быть
    /// усыновлённым. То есть четверть всей памяти приёма уходила на повторное
    /// отращивание уже отрощенного.
    ///
    /// ## Почему одного слота довольно
    ///
    /// Буферов в обороте ровно два: набираемый и отданный писателю. Третьему
    /// взяться неоткуда, и запас заменяется целиком при каждом возврате —
    /// прежний уходит вместе с присваиванием. Памяти это не добавляет: тот же
    /// объём прежде удерживался распределителем в свободных списках, откуда его
    /// нельзя было ни вернуть ядру, ни переиспользовать.
    spare: Option<Buffer>,
    /// Сколько документов буфера ещё имеет смысл показывать поиску.
    ///
    /// Тот же предел, по которому состав решает, собирать ли живой сегмент из
    /// **текущего** буфера. Здесь он нужен для двойника **отданного** буфера:
    /// двойник закрывает окно невидимости на время записи сегмента, но если
    /// буфер и без того крупнее предела, окно уже объявлено открытым — платить
    /// за его закрытие бессмысленно.
    ///
    /// А платится дорого: сборка двойника — это `write_segment` по всему
    /// буферу, то есть от одного до четырёх повторных разборов всех его
    /// документов, и всё это под замком приёма. На буфере в миллион документов
    /// при пределе в десять тысяч двойник строился всегда и всегда впустую.
    ///
    /// Умолчание `u32::MAX` — «собирать всегда»: так ведёт себя всякий, кто
    /// заводит приёмник сам, без сервера, и менять это молча нельзя.
    live_max_docs: u32,
    /// Сколько живых двойников собрано и сколько пропущено по пределу.
    ///
    /// Наблюдаемое: само наличие `inflight_live` после сброса ни о чём не
    /// говорит — при синхронной записи забор снимает двойник сразу, и решение
    /// уже не различить. Счётчики различают.
    twins_built: u64,
    twins_skipped: u64,
    /// Сколько буферов заведено заново за жизнь приёма.
    ///
    /// Наблюдаемое для проверки: при исправном обороте их ровно два —
    /// набираемый и отданный, — сколько бы сегментов ни легло. Растёт это
    /// число с числом сегментов — значит ёмкости отращиваются заново каждый
    /// цикл, а прежние остаются у распределителя.
    buffers_made: u64,
    toks: crate::analyze::Tokens,
    /// Позиция каждого токена из `toks`.
    ///
    /// У обычного текста — его номер по порядку. У поля внутри массива —
    /// номер элемента, и тогда позиции идут с пропусками: элемент без этого
    /// поля номер занимает, а токена не даёт.
    ///
    /// Обязана не убывать. Нарушение не даёт отказа: дельта при записи
    /// сегмента уходит в ноль, и все последующие позиции документа съезжают
    /// вниз — соединение по слотам сойдётся на другом элементе.
    toks_at: Vec<u32>,
    /// Рабочий буфер разбора одного элемента массива на слова.
    parts: crate::analyze::Tokens,
    /// Вхождения документа как пара «хеш слова, позиция».
    ///
    /// Хеш, а не сама строка. Сортировка нужна лишь затем, чтобы одинаковые
    /// слова встали рядом, и порядок между **разными** словами не важен вовсе —
    /// словарь всё равно сортируется заново при сбросе. Целочисленная сортировка
    /// не сравнивает строк и не двигает по двадцать четыре байта на элемент;
    /// профиль показывал `memcmp` шестью процентами всего приёма.
    ///
    /// Столкновение хешей разводит одинаковые слова по разным группам, и тогда
    /// слово получило бы два постинга на один документ. Это ловится и
    /// исправляется пересортировкой по строке — см. [`Indexer::group`].
    seen: Vec<(u64, u32)>,
    /// Ключ поиска в `lists`: номер поля и слово подряд. Переиспользуется.
    key: Vec<u8>,
    /// Найденные номера буфера — переиспользуется, чтобы гашение пачкой не
    /// заводило по вектору на идентификатор.
    hits: Vec<u32>,
    /// Фоновый писатель сегментов. `None` — сброс идёт в этом же потоке.
    flusher: Option<Flusher>,
    /// Замок состава сегментов: под ним свежий сегмент вносится в список.
    ///
    /// Свой у одиночного приёма, общий с укрупнением у сервера. Держит его
    /// **индексатор**, а не вызывающий, и это не мелочь: держи его вызывающий,
    /// он бы уже владел им в тот миг, когда приём ждёт фоновый поток, а поток
    /// ждёт этот самый замок. Взаимная блокировка на ровном месте.
    layout: std::sync::Arc<std::sync::Mutex<()>>,
    /// Номер, который получит следующий отданный на запись сегмент.
    ///
    /// Отличается от [`Indexer::landed`]: номер присваивается при **передаче**
    /// буфера, а не при завершении записи. Так порядок в списке сегментов
    /// задаётся порядком наполнения буферов, а не порядком, в каком диск успел.
    next_segment: u64,
    /// Сколько сегментов **дописано**. По нему судят, стал ли виден новый.
    landed: usize,
    /// Отказ фонового писателя. Дальше приёму верить нельзя.
    poisoned: Option<String>,
    /// Внутри атомарной пачки пороги не публикуют её половину.
    ///
    /// Буфер может ненадолго перейти обычный предел, но HTTP-приём уже ограничил
    /// размер тела. Сразу после пачки порог проверяется и весь набор уходит одним
    /// сегментом. Без этого queue item, attempt и checkpoint могли стать видимы
    /// в разных поколениях посреди одного `/_put`.
    defer_flush: bool,
    /// Документы отданного на запись буфера.
    ///
    /// Считаются отдельно, потому что снаружи «сколько принято и ещё не видно»
    /// — это буфер **плюс** то, что пишется. Не учти их, и `/_health` объявил
    /// бы ноль непоказанных в тот самый миг, когда четверть миллиона документов
    /// ещё не легли.
    inflight_docs: u32,
    pub total_docs: u64,
    /// Токенов до схлопывания одинаковых слов внутри документа.
    pub total_tokens: u64,
    pub total_postings: u64,
    /// Секунды по фазам приёма: разбор, списки, колонки, содержимое, прочее.
    ///
    /// Не украшение отчёта. Приём — вторая по длительности работа движка, и без
    /// разбивки чинить в ней нечего: сорок секунд одинаково похожи и на «медленно
    /// режем текст», и на «жмём содержимое». Профиль показал второе, но профиль
    /// снимается руками и раз в полгода, а числа нужны на каждом прогоне.
    pub phases: Vec<(&'static str, f64)>,
    /// Завершённые публикации, ещё не забранные владельцем метрик.
    flush_ms: Vec<f64>,
}

/// Задание фоновому писателю: буфер, схема и куда его класть.
struct Job {
    buf: Buffer,
    sc: Schema,
    root: String,
    segment: u64,
    seq: u64,
    /// От передачи буфера до внесения готового сегмента в manifest.
    began: std::time::Instant,
}

/// Что писатель отдаёт обратно.
struct Back {
    /// Опустошённый буфер — приём его переиспользует.
    ///
    /// Возврат, а не выбрасывание: у буфера прижившиеся ёмкости — таблица на
    /// восемьдесят тысяч слов, векторы на четверть миллиона документов, — и
    /// заводить их заново на каждый сегмент значило бы отдать обратно часть
    /// того, ради чего всё делалось.
    buf: Buffer,
    /// Каталог записанного сегмента: он и есть хранитель новых версий для
    /// отложенного гашения.
    dir: String,
    /// Чем кончилась запись. Отказ возвращает буфер наравне с удачей: ёмкости в
    /// нём те же, и терять их из-за полного диска не за что.
    outcome: Outcome,
}

/// Чем кончилась фоновая запись сегмента.
enum Outcome {
    Done {
        postings: u64,
        phases: Vec<(&'static str, f64)>,
        elapsed_ms: f64,
        /// Номер записи журнала, ставший долговечным. Ноль — сегмент не записан.
        seq: u64,
    },
    /// Сегмент не лёг. Приём обязан остановиться: он уже ответил «принято».
    Failed(String),
}

/// Фоновая запись сегмента.
///
/// ## Почему поток ровно один
///
/// Список сегментов дописывается чтением-правкой-записью
/// ([`crate::manifest::append`]), и два писателя потеряли бы одну запись.
/// Важнее другое: порядок в списке **и есть** порядок документов в общем
/// пространстве номеров, поэтому сегменты обязаны вноситься в том порядке, в
/// каком наполнялись их буферы. Один поток даёт это даром.
///
/// ## Почему в полёте ровно одно задание
///
/// Приём отдаёт буфер и забирает результат предыдущего **перед** тем, как
/// отдать следующий. Значит живых буферов не больше двух, и память приёма
/// удваивается, а не растёт без предела.
struct Flusher {
    hand: std::sync::mpsc::SyncSender<Job>,
    back: std::sync::mpsc::Receiver<Back>,
    thread: Option<std::thread::JoinHandle<()>>,
    /// Отдано и не забрано.
    inflight: bool,
}

impl Flusher {
    fn new(layout: std::sync::Arc<std::sync::Mutex<()>>) -> Flusher {
        let (hand, jobs) = std::sync::mpsc::sync_channel::<Job>(1);
        let (done, back) = std::sync::mpsc::sync_channel::<Back>(1);
        let thread = std::thread::Builder::new()
            .name("svindb-flush".into())
            .spawn(move || {
                for mut job in jobs {
                    // Отказ, а не паника, и это несущее решение. Поток фоновой
                    // записи при `panic = "abort"` не разматывает стек и не
                    // закрывает канал — он убивает **процесс**. Полный диск на
                    // одном сегменте валил бы весь узел вместе со всеми
                    // соединениями, вместо того чтобы остановить приём и
                    // сказать почему.
                    let outcome = write_segment(
                        Target::Disk { root: &job.root, segment: job.segment },
                        job.seq,
                        &job.sc,
                        &job.buf,
                    );
                    // Освобождение большого raw buffer не входит в layout
                    // critical section. До manifest он ещё не виден как disk.
                    job.buf.clear();
                    let _guard = layout.lock().unwrap_or_else(|e| e.into_inner());
                    let outcome = outcome.and_then(|w| {
                        // Внесение в список — под замком состава, тем же,
                        // под которым его переписывает укрупнение. Без
                        // этого слияние, прочитавшее состав до нас и
                        // записавшее после, вычеркнуло бы свежий сегмент:
                        // каталог на диске, а поиску не виден.
                        let name = format!("seg{:04}", job.segment);
                        crate::fail::point_io("manifest.before_publish")?;
                        crate::manifest::append(&job.root, &name).map_err(|e| {
                            std::io::Error::other(format!(
                                "{}/{}: список сегментов не обновился: {e}",
                                job.root,
                                crate::manifest::FILE
                            ))
                        })?;
                        // Отсюда сегмент долговечен и виден любому читателю,
                        // а отметка журнала — ещё нет: её двигает `after_flush`
                        // уже в потоке запроса. Это и есть окно, в котором
                        // подъём переигрывает то, что уже лежит на диске.
                        // Кампания попала в него случайным `kill -9`; здесь
                        // оно называется по имени, чтобы попадать всегда.
                        crate::fail::point("manifest.after_publish");
                        Ok(w)
                    });
                    // Отметка отдаётся **после** внесения в список: сегмент,
                    // которого нет в составе, на подъёме снесёт уборка, а
                    // журнал уже объявил бы его документы долговечными.
                    let out = Back {
                        buf: job.buf,
                        dir: format!("{}/seg{:04}", job.root, job.segment),
                        outcome: match outcome {
                            Ok(w) => Outcome::Done {
                                postings: w.postings,
                                phases: w.phases,
                                elapsed_ms: job.began.elapsed().as_secs_f64() * 1000.0,
                                seq: job.seq,
                            },
                            Err(e) => Outcome::Failed(format!("{e}")),
                        },
                    };
                    // Manifest и уведомление владельца публикуются под одним
                    // layout lock. Иначе reread мог увидеть disk и ещё держать
                    // его inflight memory twin, удваивая логические документы.
                    // На один job приходится один Back, предыдущий принят
                    // до отправки job: очередь ёмкостью 1 обязана быть свободна.
                    // Никакого ожидания канала под layout при нарушении договора.
                    if done.try_send(out).is_err() {
                        break;
                    }
                }
            })
            .expect("поток фоновой записи сегмента");
        Flusher { hand, back, thread: Some(thread), inflight: false }
    }
}

impl Drop for Flusher {
    fn drop(&mut self) {
        // Закрываем приём заданий и дожидаемся потока: недописанный сегмент —
        // это каталог без заголовка, и на подъёме его снесёт уборка, а документы
        // вернутся из журнала. Но бросать поток на произвол значило бы оставить
        // это на волю планировщика, а не на решение.
        let (dead, _) = std::sync::mpsc::sync_channel::<Job>(1);
        let hand = std::mem::replace(&mut self.hand, dead);
        drop(hand);
        if let Some(t) = self.thread.take() {
            let _ = t.join();
        }
    }
}

/// Схема полей: всё, что писателю сегмента нужно знать сверх буфера.
///
/// Отдельно от индексатора намеренно. Писатель обязан уметь работать **без**
/// него: фоновый сброс уносит буфер в свой поток, и дотянуться оттуда до
/// приёмного состояния нельзя — ни до `segment`, который уже сдвинулся, ни до
/// `exact`, который уже считает следующий сегмент.
struct Schema {
    fields: Vec<String>,
    /// Основа имён файлов каждого поля — [`crate::schema::stem_of`].
    ///
    /// Отдельно от `fields`, потому что это разные вещи: путь поля может
    /// содержать точки, имя файла — нет. Прежде в заголовок уходила одна и та
    /// же переменная и как имя поля, и как основа файлов, из-за чего точка в
    /// имени была запрещена вовсе, а вложенный документ — незаявляем.
    stems: Vec<String>,
    /// Устойчивый номер каждого поля — из реестра ([`crate::schema`]).
    fids: Vec<u32>,
    /// Номер группы каждого поля. Пусто — все поля корневые.
    groups: Vec<u32>,
    /// Путь каждой группы по её номеру. Корневая — пустая строка.
    group_paths: Vec<String>,
    boosts: Vec<f64>,
    kinds: Vec<Kind>,
    stored: Vec<bool>,
    /// Искать ли по полю — см. [`Indexer::searched`].
    searched: Vec<bool>,
    positioned: Vec<bool>,
    exact: Vec<bool>,
    posmin: u32,
}

impl Schema {
    /// Действующий порог позиций для поля.
    #[inline]
    fn posmin_of(&self, f: usize) -> u32 {
        if self.verifiable(f) {
            self.posmin
        } else {
            0
        }
    }

    /// Можно ли восстановить порядок слов этого поля из его содержимого.
    #[inline]
    fn verifiable(&self, f: usize) -> bool {
        self.stored.get(f).copied().unwrap_or(true)
            && self.kinds.get(f).copied().unwrap_or(Kind::Text) == Kind::Text
    }
}

/// Буфер и схема обязаны уметь уехать в чужой поток.
///
/// Проверка временем сборки, а не надеждой: фоновый сброс уносит их целиком, и
/// стоит кому-нибудь завести в буфере `Rc` или сырой указатель, ошибка вылезет
/// здесь, а не в виде гонки на боевом приёме.
const _: fn() = || {
    fn send<T: Send>() {}
    send::<Buffer>();
    send::<Schema>();
};

/// Имя живого сегмента, собранного из буфера, отданного писателю.
///
/// Отдельное от имени живого сегмента текущего буфера: в составе они бывают
/// оба разом, и различать их обязано быть чем.
pub const INFLIGHT_SEGMENT: &str = "живой-в-полёте";

/// Что вышло из записи сегмента.
struct Written {
    postings: u64,
    phases: Vec<(&'static str, f64)>,
    /// Куски, если сегмент собирали в память. У легшего на диск — `None`.
    ///
    pack: Option<crate::container::MemoryPack>,
}

/// Куда собирается сегмент.
///
/// Развилка ровно одна и ровно здесь: **куда положить готовый кусок**. Всё
/// остальное — словарь, постинги, колонки, позиции, заголовок — собирается
/// одним и тем же кодом, потому что два кода на один формат однажды разойдутся,
/// и разошедшийся будет собирать сегмент, который читается неправильно.
enum Target<'a> {
    /// Каталог `root/segNNNN` с контейнером внутри.
    Disk { root: &'a str, segment: u64 },
    /// Никуда: куски остаются в памяти, и на диск сегмент может не лечь вовсе.
    ///
    /// Долговечности у такого сегмента нет и не подразумевается — за неё
    /// отвечает журнал. Поэтому здесь нет ни `fsync`, ни сводки сумм: сверять
    /// нечего и не с чем, носителя под сегментом не существует.
    Memory,
}

/// Пишет сегмент на диск. Не трогает ни список сегментов, ни отметку журнала.
///
/// Разделение не косметическое. Запись сегмента — работа с диском, и она может
/// уйти в другой поток. Внесение в список и продвижение отметки — работа с
/// **порядком**, и она обязана остаться там, где порядок известен.
fn write_segment(
    target: Target<'_>,
    seq: u64,
    sc: &Schema,
    buf: &Buffer,
) -> std::io::Result<Written> {
    let mut postings = 0u64;
    let mut phases: Vec<(&'static str, f64)> = Vec::new();
    // Каталог сегмента — отказ, а не «как получится»: без него ни один
    // последующий файл не ляжет, и молчать об этом значит писать в пустоту.
    // У собираемого в память каталога нет вовсе, и заводить его незачем.
    let dir = match target {
        Target::Disk { root, segment } => {
            let dir = format!("{root}/seg{segment:04}");
            create_dir_all(&dir)
                .map_err(|e| std::io::Error::new(e.kind(), format!("{dir}: {e}")))?;
            Some(dir)
        }
        Target::Memory => None,
    };
    // Как звать сегмент в сообщениях об отказе. У легшего на диск это его
    // каталог, у собранного в память — то, чем он является: путей у него
    // нет, и выдумывать их ради сообщения значило бы отправить читателя
    // искать файл, которого не существует.
    let label = dir.clone().unwrap_or_else(|| "сегмент в памяти".to_string());
    let docs = buf.docs as usize;
    let nfields = sc.fields.len();

    // Полоса арности обязана иметь ровно одну запись на документ. Проверка
    // стоит до первого байта сегмента: потерянную арность нельзя восстановить
    // из ячеек — последние или пустые элементы массива законно не содержат ни
    // одного поля. Молчаливое дополнение нулями поэтому было бы не ремонтом, а
    // подменой пользовательских данных.
    //
    // Корневая группа полосы не хранит: у неё арность всегда единица. Для
    // каждой объявленной nested-группы отсутствие или короткая колонка —
    // внутренний отказ приёма, который оставляет WAL на месте и не публикует
    // сегмент.
    let ngroups = sc.groups.iter().copied().max().unwrap_or(0) as usize + 1;
    for g in 1..ngroups {
        let got = buf.arity.get(g).map_or(0, Vec::len);
        if got != docs {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                format!(
                    "{label}: у группы {g} арность описывает {got} документов из {docs}; \
                     публиковать сегмент с неполной полосой нельзя"
                ),
            ));
        }
    }

    // Средняя длина по полю — для множителя BM25.
    //
    // Рядом со средней считаются два числа, которых прежде не было: целая сумма
    // длин и наибольший встреченный уровень. Средняя посегментна и годится
    // только внутри своего сегмента; сложить средние соседей нельзя, а суммы —
    // можно, и из них выходит средняя по всему составу. Наибольший уровень
    // нужен подъёму потолков: он ограничивает, насколько вклад документа может
    // вырасти при переходе на общую среднюю.
    let mut avgdl = vec![0f64; nfields];
    let mut len_fixed = vec![0u64; nfields];
    let mut lmax = vec![0u8; nfields];
    let mut scoring_docs = vec![None; nfields];
    for (f, a) in avgdl.iter_mut().enumerate() {
        if sc.kinds.get(f) == Some(&Kind::Text) && sc.groups.get(f).copied().unwrap_or(0) == 0 {
            scoring_docs[f] = Some(buf.norms[f].iter().filter(|&&q| q > 0).count() as u64);
        }
        len_fixed[f] = buf.norms[f]
            .iter()
            .fold(0u64, |sum, &q| sum.saturating_add(crate::norms::fixed_len(q)));
        // Та же fixed-point сумма, что у межсегментного planner: иначе один
        // сегмент и несколько delta дают разные floating-point средние.
        *a = crate::norms::avgdl_of(len_fixed[f], scoring_docs[f].unwrap_or(docs as u64));
        lmax[f] = buf.norms[f].iter().copied().max().unwrap_or(0);
    }

    // Какие поля считаются скалярным произведением — по номеру поля, чтобы
    // горячая строка потолков не заглядывала в схему на каждый постинг.
    let dot: Vec<bool> =
        (0..nfields).map(|i| sc.kinds.get(i).copied().unwrap_or(Kind::Text).dot()).collect();
    let mut mark = std::time::Instant::now();
    // Куски сегмента идут в один файл, и порядок их не произволен: сперва
    // потоковое и крупное, а метаданные — сплошным прогоном в конце. `warm`
    // греет именно метаданные, и в контейнере это одно упреждающее чтение
    // вместо восьми поисков головки.
    //
    // Прогон копится здесь и укладывается разом ниже. Памяти это не стоит:
    // все эти куски и так живут буферами до конца сборки — раньше их просто
    // писали по мере готовности.
    let mut pack = match dir.as_deref() {
        Some(dir) => crate::container::Sink::disk(dir, crate::index::LAYOUT)?,
        None => crate::container::Sink::memory(),
    };
    let mut meta_run: Vec<(String, Vec<u8>)> = Vec::new();
    pack.begin("postings.bin")?;
    let mut bytes: Vec<u8> = Vec::with_capacity(1 << 22);
    let mut bp: u64 = 0;
    let (mut b_last, mut b_max, mut b_len) = (Vec::new(), Vec::<f32>::new(), Vec::<u16>::new());
    let mut tbin: Vec<u8> = Vec::new();
    let mut tidx: Vec<u8> = Vec::new();
    // Частоты списка, развёрнутые из байта с побегом. Буфер один на все
    // списки: заводить его на каждое из четырёхсот тысяч слов значило бы
    // четыреста тысяч выделений памяти на сброс.
    let mut tfv: Vec<u32> = Vec::new();
    // Позиции лежат отдельным файлом, а указатель на блок — своим.
    let mut pos_bytes: Vec<u8> = Vec::new();
    let mut pos_idx: Vec<u32> = Vec::new();
    let mut ppend: Vec<u32> = Vec::new();
    // Наибольшая частота среди слов, оставшихся без позиций. На диск уходит
    // она, а не порог: см. `posmin` у [`crate::index::Index`].
    let mut posmin_seen = 0u32;

    // Слова по порядку: так словарь ложится отсортированным, а списки —
    // подряд. На отсортированности стоит и двоичный поиск, и маска.
    // Байтовые ключи сортируются как есть: первый байт — номер поля, за ним
    // слово, — то есть тот же порядок, что давала пара «поле, строка».
    // Группы: путь массива и вид полосы арности. У приёма без массивов
    // группа одна — корневая, и полосы у неё нет вовсе.
    let mut slot_kinds = vec![crate::slots::Kind::Identity; ngroups];
    let mut slot_units = vec![docs; ngroups];
    // Полосы арности считаются здесь — от них зависит заголовок, — а в
    // контейнер ложатся вместе с прочим крупным, ниже: порядок кусков задан
    // не порядком вычисления.
    let mut bands: Vec<(String, Vec<u8>)> = Vec::new();
    for g in 1..ngroups {
        let empty: Vec<u32> = Vec::new();
        let arity = buf.arity.get(g).unwrap_or(&empty);
        let built = crate::slots::encode(arity, &format!("{label}/g{g}.arity"))?;
        if built.kind == crate::slots::Kind::Dense {
            bands.push((format!("g{g}.aidx"), built.idx));
            bands.push((format!("g{g}.arity"), built.band));
        }
        slot_kinds[g] = built.kind;
        slot_units[g] = built.units;
    }

    let mut keys: Vec<Box<[u8]>> = buf.lists.keys().cloned().collect();
    keys.sort_unstable();

    // Колонка ординалов словаря для ключевых слов.
    //
    // Верхушка значений («какие эмодзи самые частые») спрашивает обратное
    // тому, что отвечает инвертированный индекс, и без колонки ей пришлось
    // бы обходить все списки поля на каждый запрос. Ординал уже посчитан —
    // это номер списка, — и остаётся положить его туда, где его найдут по
    // документу. В Elasticsearch то же самое зовётся глобальными
    // ординалами, только строить их приходится отдельно и лениво.
    //
    // Номер списка **растёт вместе со словом**: ключи отсортированы, значит
    // порядок ординалов совпадает с алфавитным, и верхушка по ключу выходит
    // упорядоченной сама.
    let keyword: Vec<bool> = (0..nfields)
        .map(|f| {
            sc.kinds.get(f).copied().unwrap_or(Kind::Text).keyword()
                || sc.kinds.get(f).copied().unwrap_or(Kind::Text) == Kind::Binary
        })
        .collect();
    // Начала отрезков групп: ординал первого слота каждого документа.
    let firsts: Vec<Vec<u32>> = (0..ngroups)
        .map(|g| {
            if g == 0 {
                return Vec::new();
            }
            let mut acc = 0u32;
            let mut v = Vec::with_capacity(docs + 1);
            let empty: Vec<u32> = Vec::new();
            for a in buf.arity.get(g).unwrap_or(&empty).iter() {
                v.push(acc);
                acc += a;
            }
            v
        })
        .collect();
    // Буфер только для чтения: колонки ключевых слов собираются рядом.
    let mut kw_cols: Vec<Vec<i64>> = vec![Vec::new(); nfields];
    let mut kw_has: Vec<Vec<bool>> = vec![Vec::new(); nfields];
    let mut kw_values: Vec<crate::multivalue::OrdinalValues> =
        (0..nfields).map(|_| crate::multivalue::OrdinalValues::default()).collect();
    for f in 0..nfields {
        if !keyword[f] {
            continue;
        }
        let g = sc.groups.get(f).copied().unwrap_or(0) as usize;
        let units = if g == 0 { docs } else { slot_units[g] };
        kw_cols[f] = vec![0i64; units];
        kw_has[f] = vec![false; units];
    }
    if keyword.iter().any(|x| *x) {
        let mut poss: Vec<u32> = Vec::new();
        for (li, key) in keys.iter().enumerate() {
            let f = u32::from_be_bytes([key[0], key[1], key[2], key[3]]) as usize;
            if !keyword.get(f).copied().unwrap_or(false) {
                continue;
            }
            let presence = presence_term(sc.kinds.get(f).copied().unwrap_or(Kind::Text));
            if key.get(4..) == Some(presence.as_bytes()) {
                continue;
            }
            let g = sc.groups.get(f).copied().unwrap_or(0) as usize;
            let e = &buf.lists[&key[..]];
            let mut at = 0usize;
            for (i, &doc) in e.docs.iter().enumerate() {
                // Частота в байтовой полосе — только маркер при переполнении.
                // Без разворачивания таблицы следующий документ читает чужие slots.
                let tf = if e.tfs[i] == BIG_TF {
                    buf.big
                        .get(&key[..])
                        .and_then(|big| {
                            big.binary_search_by_key(&(i as u32), |entry| entry.0)
                                .ok()
                                .map(|at| big[at].1 as usize)
                        })
                        .ok_or_else(|| {
                            std::io::Error::new(
                                std::io::ErrorKind::InvalidData,
                                "keyword posting без полной частоты",
                            )
                        })?
                } else {
                    e.tfs[i] as usize
                };
                let ordinals: &[u32] = if g == 0 {
                    &[]
                } else {
                    poss.clear();
                    poss.extend(e.poss.get(at..at + tf).ok_or_else(|| {
                        std::io::Error::new(
                            std::io::ErrorKind::InvalidData,
                            "keyword posting без полного набора slots",
                        )
                    })?);
                    &poss
                };
                at += tf;
                if g == 0 {
                    kw_values[f].record(
                        &mut kw_cols[f],
                        &mut kw_has[f],
                        doc as usize,
                        li as i64,
                    )?;
                } else {
                    let base = firsts[g].get(doc as usize).copied().unwrap_or(0);
                    for slot in ordinals.iter() {
                        let u = (base + slot) as usize;
                        kw_values[f].record(&mut kw_cols[f], &mut kw_has[f], u, li as i64)?;
                    }
                }
            }
        }
    }

    for (li, key) in keys.iter().enumerate() {
        // Потолок проверяется **до** того, как усечённое смещение ляжет в
        // `terms.idx`, — то есть до опоры, а не после неё. Прежде проверка
        // стояла ниже, уже за записью опоры: отказ всё равно случался и
        // сегмент не дописывался, но порядок утверждал обратное тому, что
        // делал код. Обёрнутое смещение не падает — оно пишется, и на
        // следующем открытии сегмент оказывается неоткрываемым, а исходные
        // к тому времени снесены уборкой.
        //
        // Поток слов (`tbin`) проверяется наравне со списками и позициями:
        // его смещение уходит в ту же опору теми же четырьмя байтами. Ловит
        // его заворот только `walk_terms`, и то на следующем открытии.
        //
        // Отказ, а не паника: слияние проверяет тот же потолок тем же
        // сравнением и отказывает (см. `merge::fits_offset`).
        for (what, len) in
            [("список", bp), ("позиции", pos_bytes.len() as u64), ("слова", tbin.len() as u64)]
        {
            if len > u32::MAX as u64 {
                return Err(std::io::Error::other(format!(
                    "{label}: {what} сегмента перевалили за четыре гигабайта \
                         ({len} байт при потолке {}) — уменьшите flush_docs у приёма",
                    u32::MAX
                )));
            }
        }
        // Опора группы: три смещения и номер блока, от которых пойдёт
        // накопление. Всё остальное в группе выводится проходом по записям.
        if li.is_multiple_of(crate::layout::ANCHOR) {
            tidx.extend((tbin.len() as u32).to_le_bytes());
            tidx.extend((bp as u32).to_le_bytes());
            tidx.extend((pos_bytes.len() as u32).to_le_bytes());
            tidx.extend((b_last.len() as u32).to_le_bytes());
        }

        let list = &buf.lists[&key[..]].docs;
        let tfs = &buf.lists[&key[..]].tfs;
        let big = buf.big.get(&key[..]);
        let poss = &buf.lists[&key[..]].poss;
        // Курсор по редким большим частотам: они идут по возрастанию номера
        // постинга, и проход по списку встречает их по порядку.
        let mut bat = 0usize;
        // Номер поля — первые четыре байта ключа, старшим вперёд.
        //
        // Он был одним байтом, и читался как `key[0]`. После расширения тот
        // же `key[0]` стал старшим байтом номера, то есть нулём у **всех**
        // полей сразу. Отказом это не проявляется: слова просто уходят в
        // поле ноль, и поиск по остальным полям возвращает пустоту. Поймано
        // сверкой отсечения с полным перебором.
        let f = u32::from_be_bytes([key[0], key[1], key[2], key[3]]) as usize;
        let df = list.len() as u32;
        // Позиции хранит **слово**, а не поле: у поля есть право их иметь, у
        // слова — частота выше порога. Ниже порога порядок слов берётся из
        // текста, и кандидатов у такой фразы не больше самого порога.
        let field_pos = sc.positioned.get(f).copied().unwrap_or(true);
        let has_pos = field_pos && df > sc.posmin_of(f);
        if !has_pos && sc.verifiable(f) {
            posmin_seen = posmin_seen.max(df);
        }
        let long = df as usize > BLOCK;
        let post_start = bp;
        let pos_start = pos_bytes.len();

        // Частоты разворачиваются заранее: по ним решается, писать ли полосу
        // частот вообще. Список, где каждое слово встретилось по разу, её не
        // пишет — а таких списков подавляющее большинство, и байт ширины на
        // блок платился за пустоту.
        tfv.clear();
        // Индекс адресует не один массив, а несколько параллельных, и
        // сам участвует в вычислении. `zip` здесь потребовал бы
        // одновременных заимствований, которых у этого кода нет.
        #[allow(clippy::needless_range_loop)]
        for i in 0..list.len() {
            tfv.push(if tfs[i] == BIG_TF {
                let b = big.expect("список с большой частотой обязан быть в таблице");
                while bat < b.len() && b[bat].0 < i as u32 {
                    bat += 1;
                }
                b.get(bat).filter(|(at, _)| *at == i as u32).map_or(BIG_TF as u32, |(_, v)| *v)
            } else {
                tfs[i].max(1) as u32
            });
        }
        // Признак ставится только короткому списку — см. `write_run`.
        let tf_all_one = !long && tfv.iter().all(|&t| t == 1);

        // Куда смотреть в плоском векторе позиций: он идёт подряд по
        // документам списка, и шаг равен частоте.
        let mut pat = 0usize;
        let mut prev = 0u32;
        let mut pend: Vec<u32> = Vec::with_capacity(BLOCK);
        // Хранится `tf−1`: у блоков с редкими повторами почти все значения
        // нулевые, и ширина выходит меньше на бит.
        let mut fend: Vec<u32> = Vec::with_capacity(BLOCK);
        // Потолок блока и потолок списка: лучшая пара «длина, частота».
        //
        // У списка хранится не само число, а **довод** — уровень длины и
        // частота, — потому что по ним читатель восстановит его точно той
        // же формулой, какой считает вклад. Число, посчитанное при сборке и
        // округлённое до `f32`, такой гарантии не даёт.
        let mut best = 0f32;
        let (mut qmax, mut tfmax, mut list_best) = (0u8, 1u32, 0f64);
        let mut start = bp;
        let mut first_pos: Option<u32> = None;
        for (i, &doc) in list.iter().enumerate() {
            if pend.is_empty() {
                start = bp;
                ppend.clear();
            }
            pend.push(doc - prev);
            prev = doc;
            let tf = tfv[i];
            fend.push(tf - 1);
            // Позиции документа: первая как есть, дальше приращениями.
            // Приращениями — потому что они возрастают, а ширина берётся
            // одна на блок: одна большая позиция в длинном документе иначе
            // задала бы её всем.
            if !poss.is_empty() {
                let at = pat;
                let mut last = 0u32;
                for k in 0..tf as usize {
                    let v = poss.get(at + k).copied().unwrap_or(last);
                    if i == 0 && k == 0 {
                        first_pos = Some(v);
                    }
                    ppend.push(if k == 0 { v } else { v.saturating_sub(last) });
                    last = v;
                }
                pat += tf as usize;
            }
            let q = buf.norms[f][doc as usize];
            // У разреженного вектора вклад — сам вес, а не насыщение по
            // длине. Хранится он, как и у текста, **доводом**: наибольшей
            // частотой, — и читатель восстановит его той же таблицей.
            // Держится это на монотонности шкалы, которую проверяет
            // `sparse::the_scale_only_goes_up`.
            let v64 = if dot[f] {
                f64::from(crate::sparse::decode(tf.min(255) as u8))
            } else {
                crate::norms::sat(tf, dl_part(q, avgdl[f]))
            };
            // Потолок блока округляется **вверх**: приведение к `f32`
            // округляет к ближайшему, то есть в половине случаев вниз, — и
            // тогда отсечение вправе выбросить документ, чей вклад выше
            // сохранённой границы.
            let v = crate::norms::up_f32(v64);
            if v > best {
                best = v;
            }
            if v64 > list_best {
                list_best = v64;
                qmax = q;
                tfmax = tf;
            }
            if pend.len() == BLOCK {
                write_run(&mut bytes, &mut bp, &pend, &fend, !tf_all_one);
                if long {
                    b_len.push((bp - start) as u16);
                    b_last.push(doc);
                    b_max.push(best);
                    pos_idx.push(pos_bytes.len() as u32);
                }
                write_positions(&mut pos_bytes, &ppend, has_pos, df, tf_all_one);
                pend.clear();
                fend.clear();
                best = 0.0;
            }
            if bytes.len() > (1 << 22) {
                pack.append(&bytes)?;
                bytes.clear();
            }
        }
        if !pend.is_empty() && df > 1 {
            write_run(&mut bytes, &mut bp, &pend, &fend, !tf_all_one);
        }
        if !pend.is_empty() {
            if long {
                b_len.push((bp - start) as u16);
                b_last.push(prev);
                b_max.push(best);
                pos_idx.push(pos_bytes.len() as u32);
            }
            write_positions(&mut pos_bytes, &ppend, has_pos, df, tf_all_one);
        }

        crate::layout::encode(
            &mut tbin,
            &crate::layout::Rec {
                df,
                tf_all_one,
                positioned: has_pos && !poss.is_empty(),
                doc: if df == 1 { list[0] } else { 0 },
                tf: if df == 1 { tfv[0] } else { 0 },
                // Единственное вхождение одиночного слова уезжает внутрь
                // записи: ни куска в `pos.bin`, ни указателя на него.
                inline_pos: if df == 1 && tf_all_one && has_pos { first_pos } else { None },
                qmax,
                tfmax,
                post_len: (bp - post_start) as u32,
                pos_len: (pos_bytes.len() - pos_start) as u32,
            },
        );
        postings += list.len() as u64;
    }
    pack.append(&bytes)?;
    pack.end()?;

    // Метаданные блока лежат **чередованием**: последний номер, потолок и
    // длина подряд, десять байт на блок.
    //
    // Хранится **длина**, а не смещение: блоки списка лежат подряд, курсор
    // проходит их один за другим и накапливает смещение сам. Длина блока не
    // больше 513 байт — байт ширины плюс сто двадцать восемь значений по
    // тридцать два бита, — поэтому два байта вместо четырёх.
    let mut blocks: Vec<u8> = Vec::with_capacity(b_last.len() * 10);
    for i in 0..b_last.len() {
        blocks.extend(b_last[i].to_le_bytes());
        blocks.extend(b_max[i].to_bits().to_le_bytes());
        blocks.extend(b_len[i].to_le_bytes());
    }
    meta_run.push(("blocks.bin".to_string(), blocks));
    tick(&mut phases, "списки", mark.elapsed().as_secs_f64());
    mark = std::time::Instant::now();
    // Поток позиций пишется всегда, когда он непуст, — даже если указателей
    // нет ни одного. Сегмент, где все слова редкие, имеет полный набор
    // позиций и пустой `pos.idx`, и связывать одно с другим значило бы
    // потерять фразы ровно там, где формат работает лучше всего.
    if !pos_bytes.is_empty() {
        pack.put("pos.bin", &pos_bytes)?;
    }
    if !pos_idx.is_empty() {
        let mut pidx = Vec::with_capacity(pos_idx.len() * 4);
        for o in &pos_idx {
            pidx.extend(o.to_le_bytes());
        }
        pack.put("pos.idx", &pidx)?;
    }

    meta_run.push(("terms.bin".to_string(), tbin));
    meta_run.push(("terms.idx".to_string(), tidx));

    // Словарь фронт-кодированием: у соседей по алфавиту общее начало —
    // правило, и повторять его незачем. Разбор — в `dict`.
    // Словарь принимает пару «поле, слово», а буфер держит их одной строкой
    // байтов. Разбор обратно стоит одного прохода по словам сегмента и
    // делается при сбросе, а не на каждом вхождении.
    let spelled: Vec<(u32, String)> = keys
        .iter()
        .map(|k| {
            let f = u32::from_be_bytes([k[0], k[1], k[2], k[3]]);
            (f, String::from_utf8_lossy(&k[4..]).into_owned())
        })
        .collect();
    let (blob, anchors) = crate::dict::encode(&spelled, &format!("{label}/dict.blob"))?;
    meta_run.push(("dict.blob".to_string(), blob));
    meta_run.push(("dict.idx".to_string(), anchors));

    // Фильтр по словам без номера поля — первая ступень глобального каталога
    // терминов. Один и тот же запросный текст обычно повторяется по десяткам
    // полей; отрицательный ответ здесь отсекает сегмент одной проверкой до
    // десятков независимых обращений к словарю. Число элементов берётся по
    // словарным парам «поле, слово»: повторная установка тех же бит безопасна,
    // а размер остаётся линейным по уже существующему словарю.
    let mut term_filter = crate::bloom::Builder::new(spelled.len(), crate::bloom::DEFAULT_BITS);
    for (_, term) in spelled.iter() {
        term_filter.add_hash(crate::bloom::term_hash(term));
    }
    meta_run.push(("terms.bloom".to_string(), term_filter.finish()));

    // Полоса пишется не каждому полю, а каждому **различному** содержимому:
    // у всех числовых уровень нулевой, и полосы вырождаются в считанные
    // единицы. Разбор — в [`crate::norms::bands`].
    let (nb, norms_band) = crate::norms::bands(&buf.norms);
    meta_run.push(("norms.bin".to_string(), nb));

    // Карта живых документов **не пишется вовсе**, пока все живы.

    let (blob, anchors) = crate::ids::encode(&buf.ids, &format!("{label}/ids.bin"))?;
    pack.put("ids.bin", &blob)?;
    pack.put("ids.idx", &anchors)?;

    // На диск идёт **только фильтр**. Само отображение собирается по
    // требованию из `ids.bin` — см. `IdMap::rebuilt`.
    let mbloom = crate::bloom::build(&buf.ids, crate::bloom::DEFAULT_BITS);
    pack.put("idmap.bloom", &mbloom)?;
    for (name, bytes) in bands.drain(..) {
        pack.put(&name, &bytes)?;
    }
    tick(&mut phases, "идентификаторы и нормы", mark.elapsed().as_secs_f64());
    mark = std::time::Instant::now();

    let mut spreads: Vec<f64> = vec![1.0; nfields];
    // Раскладка и признак присутствия — по данным этого сегмента, а не по
    // объявлению: поле, которого здесь нет ни у одного документа, файлов не
    // получает вовсе, а заполненное целиком не платит за биты присутствия.
    // Умолчание — «колонки нет»: у текстового поля её и не бывает, и
    // заголовок обязан говорить это прямо, а не обещать плотную раскладку,
    // которой не существует.
    let mut layouts: Vec<crate::column::Layout> = vec![crate::column::Layout::None; nfields];
    let mut presences: Vec<crate::column::Presence> = vec![crate::column::Presence::Bits; nfields];
    // Сколько значений у поля: разреженной раскладке это нужно, чтобы знать
    // число блоков, а плотной — чтобы отличить «есть у всех» от «есть не у
    // всех».
    let mut values_of: Vec<usize> = vec![0; nfields];
    // Наименьшее и наибольшее значение числового поля во всём сегменте.
    //
    // Две восьмёрки байт в заголовке, ради которых запрос может не читать
    // сегмент **вовсе**: отбор по диапазону, не пересекающемуся с
    // [lo, hi], не найдёт здесь ничего, а сортировка по убыванию не найдёт
    // ничего лучше `hi`. На дописываемом корпусе, где время растёт вместе с
    // номером сегмента, это отсекает почти всё.
    //
    // Только числовые: у ключевого поля в колонке лежат номера слов в
    // словаре **этого** сегмента, и сравнивать их между сегментами нельзя.
    let mut bounds: Vec<Option<(i64, i64)>> = vec![None; nfields];
    let mut multi_counts = vec![(0usize, 0usize); nfields];
    for f in 0..nfields {
        let kind = sc.kinds.get(f).copied().unwrap_or(Kind::Text);
        if !kind.numeric() && !kind.keyword() {
            continue;
        }
        if !sc.searched.get(f).copied().unwrap_or(true) {
            continue;
        }
        let name = &sc.stems[f];
        let (cols, has): (&[i64], &[bool]) =
            if kind.keyword() { (&kw_cols[f], &kw_has[f]) } else { (&buf.cols[f], &buf.has[f]) };
        let keyword_multi = kind.keyword().then(|| std::mem::take(&mut kw_values[f]).finish());
        let multi = keyword_multi.as_ref().unwrap_or(&buf.multi[f]);
        multi_counts[f] = (multi.entries(), multi.values());
        if let Some(bytes) = multi.encode(cols.len())? {
            pack.put(&format!("{name}.nmv"), &bytes)?;
            if kind.numeric() {
                bounds[f] = multi.bounds();
            }
        }
        let values = has.iter().filter(|&&y| y).count();
        values_of[f] = values;
        if values == 0 {
            // Ни одного значения — ни одного файла. Читатель узнаёт об
            // этом из заголовка, а не по отсутствию файла: «его не должно
            // быть» и «он потерялся» обязаны различаться.
            layouts[f] = crate::column::Layout::None;
            continue;
        }
        let present: Vec<(u32, i64)> =
            has.iter().enumerate().filter(|(_, y)| **y).map(|(u, _)| (u as u32, cols[u])).collect();
        if kind.numeric() {
            let lo = present.iter().map(|(_, v)| *v).min().expect("значения есть");
            let hi = present.iter().map(|(_, v)| *v).max().expect("значения есть");
            bounds[f] = Some(bounds[f].map_or((lo, hi), |(a, b)| (a.min(lo), b.max(hi))));
        }
        layouts[f] = crate::column::choose(cols.len(), &present);
        if layouts[f] == crate::column::Layout::Sparse {
            let (sdata, smeta) = crate::column::encode_sparse(&present);
            meta_run.push((format!("{name}.scol"), sdata));
            // Признак разброса считается по тем же границам блоков.
            spreads[f] = crate::column::spread_of(smeta.chunks(crate::column::SMETA).map(|c| {
                let lo = i64::from_le_bytes(c[0..8].try_into().expect("восемь байт"));
                let hi = i64::from_le_bytes(c[8..16].try_into().expect("восемь байт"));
                (lo, hi)
            }));
            meta_run.push((format!("{name}.smeta"), smeta));
            // Корзины — только плотной: у разреженной блоков уже во столько
            // раз меньше, во сколько поле реже, и надстройка поверх них
            // стоила бы больше, чем даёт.
            continue;
        }
        if values == cols.len() {
            presences[f] = crate::column::Presence::All;
        }
        let (data, meta) = crate::column::encode(cols, has);
        spreads[f] = crate::column::spread_of(meta.chunks(crate::column::META).map(|c| {
            let lo = i64::from_le_bytes(c[0..8].try_into().expect("восемь байт"));
            let hi = i64::from_le_bytes(c[8..16].try_into().expect("восемь байт"));
            (lo, hi)
        }));
        meta_run.push((format!("{name}.col"), data));
        meta_run.push((format!("{name}.cmeta"), meta));
        // Корзины — только там, где пропуск по границам блока не отсекает.
        // Решает признак, посчитанный по самим данным; объявлять поле
        // «индексируемым» вручную не нужно: решение определяется данными.
        if spreads[f] >= crate::column::SPREAD_USELESS {
            let (bkt, bidx) = crate::column::encode_buckets(cols, has);
            meta_run.push((format!("{name}.bkt"), bkt));
            meta_run.push((format!("{name}.bktidx"), bidx));
        }
        if presences[f] == crate::column::Presence::Bits {
            meta_run.push((format!("{name}.has"), crate::column::encode_presence(has)));
        }
    }
    tick(&mut phases, "колонки", mark.elapsed().as_secs_f64());
    mark = std::time::Instant::now();

    // Плотные векторы. Границы шкалы берутся по всему сегменту, поэтому
    // сжатие идёт здесь, одним проходом, а не по документу при приёме.
    for f in 0..nfields {
        let Some(dims) = sc.kinds.get(f).copied().unwrap_or(Kind::Text).dims() else {
            continue;
        };
        let Some(built) = crate::vector::build_checked(&buf.vecs[f], dims)? else {
            // Ни одного вектора во всём сегменте — файлов не будет, и это
            // не отличается от поля, которого нет: `Vectors::open` вернёт
            // `None`, а поиск по нему честно ничего не найдёт.
            continue;
        };
        let name = &sc.stems[f];
        pack.put(&format!("{name}.q8"), &built.codes)?;
        pack.put(&format!("{name}.qm"), &built.meta)?;
        // Разбиение на списки — приближение, и оно необязательно. Не
        // построилось (документов мало, размерность не та) — файлов не будет, а
        // поиск пойдёт полным перебором, как шёл всегда.
        if let Some(ivf) = crate::vector::train_ivf(&buf.vecs[f], dims) {
            pack.put(&format!("{name}.ivf"), &ivf.centroids)?;
            pack.put(&format!("{name}.ivfb"), &ivf.band)?;
        }
    }
    tick(&mut phases, "векторы", mark.elapsed().as_secs_f64());
    mark = std::time::Instant::now();

    for f in 0..nfields {
        if !sc.stored.get(f).copied().unwrap_or(true) || buf.vals[f].is_empty() {
            continue;
        }
        // Точное числовое поле не хранится: его печатает обратно колонка.
        // Но у `noindex` колонки нет, и пропустить хранение значило бы
        // выбросить значение совсем — притом что `noindex` заводят ровно
        // ради того, чтобы значение отдавать.
        if sc.kinds.get(f).copied().unwrap_or(Kind::Text).numeric()
            && sc.exact[f]
            && sc.searched.get(f).copied().unwrap_or(true)
        {
            continue;
        }
        let name = &sc.stems[f];
        let vals = &buf.vals[f];
        let Some(built) = crate::store::build(
            |emit| vals.iter().for_each(|v| emit(v.as_bytes())),
            crate::codec::Effort::Fast,
            &format!("{label}/{name}.sbin"),
        )?
        else {
            continue;
        };
        pack.put(&format!("{name}.sbin"), &built.data)?;
        pack.put(&format!("{name}.smrk"), &built.marks)?;
        pack.put(&format!("{name}.sdic"), &built.dict)?;
        pack.put(&format!("{name}.scrc"), &built.crcs)?;
    }
    tick(&mut phases, "содержимое", mark.elapsed().as_secs_f64());
    mark = std::time::Instant::now();

    // Метаданные — сплошным прогоном и последними из кусков. `Index::warm`
    // греет ровно их, и в контейнере это одно упреждающее чтение подряд
    // вместо восьми поисков головки по разным файлам.
    for (name, bytes) in meta_run.drain(..) {
        pack.put(&name, &bytes)?;
    }
    // Приёмник закрыт. У контейнера это значит «лёг на носитель» — `finish`
    // делает `sync_all` сам, и это одна синхронизация вместо двадцати шести,
    // по одной на файл. У памяти закрывать нечего, кроме учёта.
    //
    // Порядок дальше нерушим — для того, что ложится на диск: сначала
    // содержимое, потом карта живых, потом заголовок, и только потом
    // каталог. Заголовок вправе обещать лишь тот контейнер, который уже лёг;
    // иначе после потери питания остался бы сегмент, объявленный готовым и
    // наполовину пустой.
    let (packed, mut memory) = pack.finish()?;

    // Строка `container` — обещание про файл. У сегмента в памяти файла нет,
    // и строки нет тоже: заголовок, обещающий контейнер, которого не
    // существует, отправил бы читателя открывать пустоту.
    let mut head = match packed {
        Some(packed) => format!("container\t{}\t{packed}\n", crate::container::FILE),
        None => String::new(),
    };
    head.push_str(&format!(
        "docs\t{}\nblocks\t{}\nterms\t{}\nlayout\t{}\nseq\t{}\nposblock\t{}\nposmin\t{}\n",
        docs,
        b_last.len(),
        keys.len(),
        crate::index::LAYOUT,
        seq,
        crate::index::POSBLOCK,
        posmin_seen
    ));
    // Средняя длина пишется **без округления**, и это не эстетика.
    //
    // Запись без потерь возвращает то же самое число, и писатель с
    // читателем считают по одному значению. Седьмой раскладке это нужно
    // вдвойне: потолок там не хранится, а восстанавливается.
    for g in 0..ngroups {
        let kind = if g == 0 {
            crate::slots::Kind::Identity
        } else {
            slot_kinds.get(g).copied().unwrap_or(crate::slots::Kind::Identity)
        };
        let units = if g == 0 { docs } else { slot_units.get(g).copied().unwrap_or(0) };
        head.push_str(&format!(
            "group\t{g}\t{}\t{}\t{units}\n",
            sc.group_paths.get(g).map(|s| s.as_str()).unwrap_or(""),
            kind.name()
        ));
    }
    for (i, name) in sc.fields.iter().enumerate() {
        // Устойчивый номер и основа имён файлов. Приём объявляет поля
        // именами без точки — этого требует `valid_field_name`, — поэтому
        // основа совпадает с именем, а номер с позицией. Столбцы пишутся
        // всё равно: читатель обязан брать их **из заголовка**, а не
        // выводить, иначе сегмент со сдвинутым составом полей опять начнёт
        // читать чужую колонку.
        head.push_str(&format!(
            "field\t{}\t{}\t{}\t{}\t{:.3e}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\n",
            name,
            sc.boosts[i],
            avgdl[i],
            sc.kinds.get(i).copied().unwrap_or(Kind::Text).spec(),
            spreads[i],
            u8::from(sc.stored.get(i).copied().unwrap_or(true)),
            u8::from(sc.positioned.get(i).copied().unwrap_or(true)),
            norms_band.get(i).copied().unwrap_or(i as u32),
            sc.fids.get(i).copied().unwrap_or(i as u32),
            // Одиннадцатый столбец — **основа имён файлов**, а не имя поля.
            // Прежде сюда подставлялась та же переменная `name`, и два
            // разных смысла жили одной строкой: оттого точка в имени поля и
            // была запрещена во всём движке.
            sc.stems.get(i).cloned().unwrap_or_else(|| name.to_string()),
            layouts[i].name(),
            presences[i].name(),
            sc.groups.get(i).copied().unwrap_or(0),
            values_of.get(i).copied().unwrap_or(0),
            u8::from(sc.searched.get(i).copied().unwrap_or(true)),
            // Пусто, а не «ноль и ноль»: у поля без значений границ нет, и
            // ноль на их месте читался бы как настоящая граница — то есть
            // отсекал бы сегменты, в которых нужное лежит.
            bounds[i].map_or(String::new(), |(lo, _)| lo.to_string()),
            bounds[i].map_or(String::new(), |(_, hi)| hi.to_string()),
            // Восемнадцатый и девятнадцатый столбцы — целая сумма длин поля и
            // наибольший уровень. Читатель старой сборки их не заметит: разбор
            // берёт столбцы по номеру и молчит об отсутствующих.
            len_fixed[i],
            lmax[i],
            multi_counts[i].0,
            multi_counts[i].1,
            scoring_docs[i].map_or(String::new(), |count| count.to_string())
        ));
    }
    let livemap = crate::live::with_dead(buf.ids.len(), &buf.dead);
    match dir.as_deref() {
        Some(dir) => {
            // Отказ здесь — отказ всего сегмента, а не заметка.
            //
            // `live.bin` держит карту удалённых. Оборванная запись оставила
            // бы сегмент, у которого заголовок обещает N документов, а карта
            // короче — и удалённые ожили бы в выдаче. Пропущенный `?` при
            // переводе на отказы (пункт 1.1) как раз это и допускал: файл
            // писался, ошибка молчала.
            write(dir, crate::live::FILE, &livemap)?;
            // Заголовок пишется последним и сразу за ним — каталог: имя
            // заголовка обязано пережить питание, иначе готовый сегмент
            // выглядит незаконченным.
            write(dir, "head.tsv", head.as_bytes())?;
            tick(&mut phases, "заголовок и суммы", mark.elapsed().as_secs_f64());
            sync_dir(dir);
            // Сводка сумм — после каталога, и это не нарушает правила выше:
            // на неё заголовок не ссылается. Признаком готовности остаётся
            // он, а сводка — только средство проверки. Оборванная запись
            // оставит сегмент без сводки, и проверка скажет об этом
            // заметкой, а не поломкой.
            crate::sums::write(dir).ok();
        }
        // У собранного в память карта живых и заголовок ложатся такими же
        // кусками, как всё прочее. Порядок между ними здесь ничего не
        // значит: терять между двумя записями нечего — питание памяти
        // сегмента не переживает по построению, и восстанавливает его
        // журнал, а не заголовок.
        //
        // Нет и сводки сумм: сверять содержимое с носителем, которого не
        // существует, — не проверка, а её изображение.
        None => {
            let pack = memory.as_mut().expect("приёмник памяти на месте");
            pack.put(crate::live::FILE, &livemap)?;
            pack.put("head.tsv", head.as_bytes())?;
            tick(&mut phases, "заголовок и суммы", mark.elapsed().as_secs_f64());
        }
    }
    // Manifest — точка невозврата: после внесения имени любой читатель и
    // следующий процесс обязаны открыть сегмент. Поэтому писатель проверяет
    // тем же production-разбором ровно те байты, которые только что положил,
    // **до** возврата вызывающему, а вызывающий публикует имя лишь после
    // успешного результата. Это не полный `check --full` и не второй проход по
    // данным: `index::load` читает заголовок, оглавление и отображает куски,
    // проверяя их обязательный состав и размеры. Цена — несколько открытий на
    // сегмент; защита — невозможность записать в manifest сегмент, который сам
    // узел открыть не умеет.
    if let Some(dir) = dir.as_deref() {
        let opened = crate::index::load(dir).map_err(|e| {
            std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                format!("{dir}: собранный сегмент не прошёл самопроверку перед публикацией: {e}"),
            )
        })?;
        if opened.docs != docs {
            return Err(std::io::Error::new(
                std::io::ErrorKind::InvalidData,
                format!(
                    "{dir}: самопроверка открыла {} документов вместо записанных {docs}",
                    opened.docs
                ),
            ));
        }
    }
    Ok(Written { postings, phases, pack: memory })
}

/// Хеш слова, по которому вхождения группируются внутри документа.
///
/// FxHash: умножение и сдвиг на восемь байт. Криптостойкость здесь не нужна и
/// вредна — ключи не приходят от противника, а цена считается на каждом слове
/// каждого документа. Столкновения не портят выдачу: их ловит [`Indexer::group`].
#[inline]
fn word_hash(b: &[u8]) -> u64 {
    const K: u64 = 0x51_7c_c1_b7_27_22_0a_95;
    let mut h = 0u64;
    let mut at = 0usize;
    while at + 8 <= b.len() {
        let w = u64::from_le_bytes(b[at..at + 8].try_into().expect("восемь байт"));
        h = (h.rotate_left(5) ^ w).wrapping_mul(K);
        at += 8;
    }
    let mut tail = 0u64;
    for (i, &c) in b[at..].iter().enumerate() {
        tail |= u64::from(c) << (i * 8);
    }
    h = (h.rotate_left(5) ^ tail).wrapping_mul(K);
    // Длина в хеш входит: иначе `\0`-хвост сделал бы `аб` и `аб\0` неразличимыми.
    h ^ (b.len() as u64)
}

/// Печатается ли разобранное значение тем же текстом, каким пришло.
///
/// Пустой текст — да: колонка отдаст «значения нет», а чтение вернёт пустую
/// строку, то есть ровно то, что и лежало бы в копии.
fn prints_back(kind: Kind, v: Option<i64>, text: &str) -> bool {
    // Сверка идёт с **исходным** текстом, а не с обрезанным. `parse_value`
    // обрезает пробелы сам, поэтому ` 5 ` разбирается в пятёрку и напечаталось
    // бы обратно как `5` — то есть не так, как пришло.
    if text.is_empty() {
        return true;
    }
    let Some(v) = v else { return false };
    match kind {
        Kind::Bool => text == if v != 0 { "true" } else { "false" },
        Kind::Float | Kind::Double => crate::index::float_of(v).to_string() == text,
        _ => v.to_string() == text,
    }
}

/// Прибавляет секунды к фазе с таким именем, заводя её при первой встрече.
fn tick(phases: &mut Vec<(&'static str, f64)>, name: &'static str, secs: f64) {
    match phases.iter_mut().find(|(n, _)| *n == name) {
        Some((_, v)) => *v += secs,
        None => phases.push((name, secs)),
    }
}

/// Заводит часы только в диагностической сборке.
///
/// `stats::ENABLED` — compile-time константа, поэтому в обычном release весь
/// `Option<Instant>` вместе с ветвлением удаляется оптимизатором. Это важно:
/// таймеры токенизации стоят внутри цикла по полям каждого документа и сами
/// не должны становиться частью измеряемого продуктового пути.
#[inline(always)]
fn profile_start() -> Option<std::time::Instant> {
    crate::stats::ENABLED.then(std::time::Instant::now)
}

#[inline(always)]
fn profile_tick(
    phases: &mut Vec<(&'static str, f64)>,
    name: &'static str,
    started: Option<std::time::Instant>,
) {
    if let Some(started) = started {
        tick(phases, name, started.elapsed().as_secs_f64());
    }
}

impl Indexer<Simple> {
    pub fn new(
        dir: &str,
        fields: Vec<String>,
        boosts: Vec<f64>,
        per_segment: u32,
    ) -> Indexer<Simple> {
        let kinds = vec![Kind::Text; fields.len()];
        Indexer::typed(dir, fields, boosts, kinds, per_segment)
    }

    /// Индексатор с объявленными типами, хранением и позициями.
    #[allow(clippy::too_many_arguments)]
    pub fn typed_positioned(
        dir: &str,
        fields: Vec<String>,
        boosts: Vec<f64>,
        kinds: Vec<Kind>,
        stored: Vec<bool>,
        positioned: Vec<bool>,
        per_segment: u32,
    ) -> Indexer<Simple> {
        let mut ix = Indexer::typed_stored(dir, fields, boosts, kinds, stored, per_segment);
        for (i, p) in positioned.into_iter().enumerate() {
            if i < ix.positioned.len() {
                ix.positioned[i] = p;
            }
        }
        ix
    }

    /// Индексатор с объявленными типами полей и признаком хранения.
    ///
    /// `stored` короче списка полей — недостающие считаются хранимыми: поле,
    /// про которое ничего не сказано, обязано вести себя как обычное.
    pub fn typed_stored(
        dir: &str,
        fields: Vec<String>,
        boosts: Vec<f64>,
        kinds: Vec<Kind>,
        stored: Vec<bool>,
        per_segment: u32,
    ) -> Indexer<Simple> {
        let mut ix = Indexer::typed(dir, fields, boosts, kinds, per_segment);
        for (i, s) in stored.into_iter().enumerate() {
            if i < ix.stored.len() {
                let vector = ix.kinds[i].dims().is_some() || ix.kinds[i].dot();
                ix.stored[i] = s && !vector;
            }
        }
        ix
    }

    /// Индексатор с объявленными типами полей.
    pub fn typed(
        dir: &str,
        fields: Vec<String>,
        boosts: Vec<f64>,
        kinds: Vec<Kind>,
        per_segment: u32,
    ) -> Indexer<Simple> {
        let mut ix = Indexer::with_analyzer(dir, fields, boosts, per_segment, Simple);
        ix.kinds = kinds;
        // Позиции есть только у того, у кого есть порядок слов. У вектора,
        // числа и логического значения его нет, и объявлять их позиционными —
        // не безобидная мелочь: проверка целостности сверяет обещание с
        // содержимым и объявляет здоровый индекс сломанным, потому что поле
        // обещало позиции, а блока позиций у него нет.
        for i in 0..ix.kinds.len() {
            if !matches!(ix.kinds[i], Kind::Text) {
                ix.positioned[i] = false;
            }
            let vector = ix.kinds[i].dims().is_some() || ix.kinds[i].dot();
            if vector {
                ix.stored[i] = false;
            }
        }
        ix
    }
}

impl<A: Analyzer> Indexer<A> {
    pub fn with_analyzer(
        dir: &str,
        fields: Vec<String>,
        boosts: Vec<f64>,
        per_segment: u32,
        analyzer: A,
    ) -> Indexer<A> {
        // Путь поля проверяется здесь, а не у вызывающего, потому что
        // вызывающих пять и каждый новый забыл бы проверку по-своему.
        //
        // Проверяется именно **путь**, а не имя: точки в нём законны, ведь
        // вложенный объект документа раскладывается путём через точку. Имя
        // файла из пути выводит [`crate::schema::stem_of`], и требования к
        // файлу остались там, где им и место.
        //
        // Отказ отравляет приёмник, а не роняет процесс. При `panic = "abort"`
        // паника здесь убила бы узел целиком, и убила бы на старте — там, где
        // оператор ждёт внятного сообщения, а не аварийного дампа. Отравление
        // же — уже заведённый в этом файле приём: тем же способом приёмник
        // отказывается работать, когда умер поток фоновой записи.
        let mut refused: Option<String> = None;
        for name in fields.iter() {
            if let Err(e) = crate::schema::valid_field_path(name) {
                refused = Some(format!("схема отвергнута: {e}"));
                break;
            }
        }
        create_dir_all(dir).ok();
        // Нумерация продолжается с наибольшего существующего, а не с их числа.
        let (segment, landed) = std::fs::read_dir(dir)
            .map(|it| {
                let numbers: Vec<u64> = it
                    .filter_map(|e| e.ok())
                    .filter_map(|e| {
                        let n = e.file_name().to_string_lossy().to_string();
                        n.strip_prefix("seg").and_then(|d| d.parse::<u64>().ok())
                    })
                    .collect();
                let next = numbers.iter().copied().max().map_or(Some(0), |n| n.checked_add(1));
                (next, numbers.len())
            })
            .unwrap_or((Some(0), 0));
        let segment = match segment {
            Some(segment) => segment,
            None => {
                refused = Some(format!(
                    "нумерация сегментов исчерпана: в {dir} уже есть seg{}; следующий номер \
                     не помещается в u64, продолжение переиспользовало бы раннее имя",
                    u64::MAX
                ));
                0
            }
        };
        let n = fields.len();
        let kinds = vec![Kind::Text; n];
        Indexer {
            superseded: Vec::new(),
            inflight_superseded: Vec::new(),
            inflight_id_hashes: Vec::new(),
            inflight_live: None,
            frozen: None,
            manifest_ready: false,
            landed_superseded: Vec::new(),
            kinds,
            fids: Vec::new(),
            groups: Vec::new(),
            group_paths: vec![String::new()],
            stored: vec![true; n],
            searched: vec![true; n],
            exact: vec![true; n],
            positioned: vec![true; n],
            posmin: 0,
            flushed_seq: 0,
            seq: 0,
            dir: dir.to_string(),
            fields,
            boosts,
            per_segment,
            // Четверть гигабайта текста — то же по духу, что
            // `indices.memory.index_buffer_size` у Elasticsearch: доля памяти
            // узла, отведённая под приём. Число взято так, чтобы на обычных
            // корпусах первым срабатывал порог по документам (миллион сообщений
            // по семьдесят байт — это семьдесят мегабайт), а управление
            // перехватывалось только там, где документы крупные.
            flush_bytes: default_flush_bytes(),
            analyzer,
            buf: Buffer::new(n),
            spare: None,
            live_max_docs: u32::MAX,
            twins_built: 0,
            twins_skipped: 0,
            buffers_made: 1,
            toks: crate::analyze::Tokens::default(),
            toks_at: Vec::new(),
            parts: crate::analyze::Tokens::default(),
            seen: Vec::new(),
            key: Vec::new(),
            hits: Vec::new(),
            flusher: None,
            layout: std::sync::Arc::new(std::sync::Mutex::new(())),
            next_segment: segment,
            landed,
            poisoned: refused,
            defer_flush: false,
            inflight_docs: 0,
            total_docs: 0,
            total_tokens: 0,
            total_postings: 0,
            phases: Vec::new(),
            flush_ms: Vec::new(),
        }
    }

    /// Отдельный приёмник той же схемы — чтобы собрать кусок **вне замка**.
    ///
    /// ## Зачем не отдельная укладка, а второй приёмник
    ///
    /// От куска требуется, чтобы сегмент из него вышел побайтово таким же, как
    /// из последовательных `add`. Написать вторую укладку и доказывать это
    /// сверкой — работа, которую пришлось бы делать заново при всякой правке
    /// первой. Здесь доказывать нечего: кусок собирается **тем же кодом**,
    /// просто своими номерами документов, а слияние ниже только сдвигает
    /// номера и приписывает списки к спискам.
    ///
    /// У куска нет ни каталога, ни писателя, ни порогов: сбрасывать ему некуда
    /// и незачем — он весь целиком уедет в буфер приёма.
    pub fn detached(&self) -> Indexer<A>
    where
        A: Clone,
    {
        let n = self.fields.len();
        Indexer {
            superseded: Vec::new(),
            inflight_superseded: Vec::new(),
            inflight_id_hashes: Vec::new(),
            inflight_live: None,
            frozen: None,
            manifest_ready: false,
            landed_superseded: Vec::new(),
            kinds: self.kinds.clone(),
            fids: self.fids.clone(),
            groups: self.groups.clone(),
            group_paths: self.group_paths.clone(),
            stored: self.stored.clone(),
            searched: self.searched.clone(),
            exact: vec![true; n],
            positioned: self.positioned.clone(),
            posmin: self.posmin,
            flushed_seq: 0,
            seq: 0,
            dir: String::new(),
            fields: self.fields.clone(),
            boosts: self.boosts.clone(),
            // Ни по числу документов, ни по объёму кусок не сбрасывается: ему
            // некуда. Порог применяет буфер приёма — один раз, после слияния.
            per_segment: u32::MAX,
            flush_bytes: 0,
            analyzer: self.analyzer.clone(),
            buf: Buffer::new(n),
            spare: None,
            live_max_docs: u32::MAX,
            twins_built: 0,
            twins_skipped: 0,
            buffers_made: 1,
            toks: crate::analyze::Tokens::default(),
            toks_at: Vec::new(),
            parts: crate::analyze::Tokens::default(),
            seen: Vec::new(),
            key: Vec::new(),
            hits: Vec::new(),
            flusher: None,
            layout: std::sync::Arc::new(std::sync::Mutex::new(())),
            next_segment: 0,
            landed: 0,
            poisoned: None,
            defer_flush: false,
            inflight_docs: 0,
            total_docs: 0,
            total_tokens: 0,
            total_postings: 0,
            phases: Vec::new(),
            flush_ms: Vec::new(),
        }
    }

    /// Сколько живых двойников собрано и сколько пропущено.
    ///
    /// Наружу — чтобы про сборку двойника можно было говорить числом. Она идёт
    /// под замком приёма, и вопрос «сколько это стоит» решается не рассуждением,
    /// а этой парой: на боевой настройке (`flush_docs` в сотни раз больше
    /// `live_max_docs`) двойник пропускается всегда, и стоит она ноль.
    pub fn twins(&self) -> (u64, u64) {
        (self.twins_built, self.twins_skipped)
    }

    /// Сколько документов лежит в куске.
    pub fn staged(&self) -> u32 {
        self.buf.docs
    }

    /// Вливает кусок в буфер приёма. Кусок остаётся пустым и годным к новому.
    ///
    /// ## Что здесь происходит и чего не происходит
    ///
    /// Не происходит ни разбора, ни токенизации, ни хеширования каждого
    /// вхождения: всё это кусок сделал у себя, без замка. Здесь номера
    /// документов сдвигаются на длину буфера, а списки приписываются к спискам —
    /// то есть на каждое **слово куска** приходится один поиск в общем словаре
    /// вместо одного на каждое вхождение.
    ///
    /// Именно в этом весь размен: под замком остаётся работа, пропорциональная
    /// числу **разных** слов пачки, а не числу их вхождений. На обычном тексте
    /// это разница в разы.
    ///
    /// ## Почему порядок сохраняется
    ///
    /// Документы куска идут после уже принятых, поэтому их номера больше всех
    /// имеющихся, и списки остаются возрастающими простым приписыванием.
    /// Позиции внутри документа кусок уже разложил в том же порядке, в каком их
    /// разложил бы приём.
    pub fn absorb(&mut self, frag: &mut Indexer<A>) {
        if frag.buf.docs == 0 {
            return;
        }
        let base = self.buf.docs;
        let nfields = self.fields.len();
        for f in 0..nfields {
            let unit_base = self.buf.cols.get(f).map_or(0, Vec::len);
            self.buf.multi[f].append(&mut frag.buf.multi[f], unit_base);
            if let (Some(dst), Some(src)) = (self.buf.vals.get_mut(f), frag.buf.vals.get_mut(f)) {
                dst.append(src);
            }
            if let (Some(dst), Some(src)) = (self.buf.cols.get_mut(f), frag.buf.cols.get_mut(f)) {
                dst.append(src);
            }
            if let (Some(dst), Some(src)) = (self.buf.has.get_mut(f), frag.buf.has.get_mut(f)) {
                dst.append(src);
            }
            if let (Some(dst), Some(src)) = (self.buf.vecs.get_mut(f), frag.buf.vecs.get_mut(f)) {
                dst.append(src);
            }
            if let (Some(dst), Some(src)) = (self.buf.norms.get_mut(f), frag.buf.norms.get_mut(f)) {
                dst.append(src);
            }
            // Признак «значения печатаются обратно» — общий для сегмента:
            // достаточно одного значения в куске, которое не печатается, чтобы
            // копию пришлось хранить всему сегменту.
            if let (Some(dst), Some(src)) = (self.exact.get_mut(f), frag.exact.get(f)) {
                *dst &= *src;
            }
        }
        // Арность индексируется **группой**, а не полем. Прежний код сливал
        // её внутри цикла `0..nfields` и только когда такой столбец уже был у
        // целевого буфера. У пустого общего буфера столбцов ещё нет, поэтому
        // первая parallel-ingest пачка теряла их целиком. Если затем рядом
        // попадал один документ обычным путём, заголовок сегмента обещал
        // `dense` на сотню тысяч документов, а `g*.aidx` описывал один. Такой
        // сегмент успевал попасть в manifest и не открывался ни поиском, ни
        // после `kill -9`.
        //
        // Целевой набор сначала принимает саму форму куска, а затем полосы
        // переставляются без копии. Число полей здесь намеренно не участвует:
        // несколько полей одной nested-группы делят одну полосу, а широкая
        // схема может иметь сотни полей и всего две группы.
        if self.buf.arity.len() < frag.buf.arity.len() {
            self.buf.arity.resize_with(frag.buf.arity.len(), Vec::new);
        }
        for g in 0..frag.buf.arity.len() {
            self.buf.arity[g].append(&mut frag.buf.arity[g]);
        }
        // Где какой список начинался **до** приписывания: по этим числам
        // сдвигаются номера постингов у частот, не поместившихся в байт.
        let mut at_of: HashMap<Box<[u8]>, u32> = HashMap::with_capacity(frag.buf.lists.len());
        for (key, mut p) in frag.buf.lists.drain() {
            let e = self.buf.lists.entry(key.clone()).or_default();
            self.buf.delta.touch(&key, e);
            at_of.insert(key, e.tfs.len() as u32);
            e.docs.extend(p.docs.iter().map(|d| d + base));
            e.tfs.append(&mut p.tfs);
            e.poss.append(&mut p.poss);
        }
        for (key, v) in frag.buf.big.drain() {
            let at = at_of.get(&key).copied().unwrap_or(0);
            let e = self.buf.big.entry(key).or_default();
            e.extend(v.into_iter().map(|(i, tf)| (i + at, tf)));
        }
        // Идентификаторы кладутся до таблицы поиска: таблица хранит номера, а
        // строки читает из `ids`, и вставка в неё до `append` искала бы их там,
        // где их ещё нет.
        let from = self.buf.ids.len();
        self.buf.ids.append(&mut frag.buf.ids);
        self.buf.dead.append(&mut frag.buf.dead);
        for i in from..self.buf.ids.len() {
            let h = crate::bloom::hash(&self.buf.ids[i]);
            self.buf.slots.insert(h, i as u32, &self.buf.ids);
        }
        self.buf.docs += frag.buf.docs;
        self.buf.bytes += frag.buf.bytes;
        self.buf.build_reserve = self.buf.build_reserve.saturating_add(frag.buf.build_reserve);
        self.total_docs += frag.total_docs;
        self.total_tokens += frag.total_tokens;
        for (n, v) in std::mem::take(&mut frag.phases) {
            tick(&mut self.phases, n, v);
        }
        // Кусок опустошается целиком: ёмкости его векторов остаются при нём и
        // пригодятся следующей пачке.
        frag.buf.docs = 0;
        frag.buf.bytes = 0;
        frag.buf.build_reserve = 0;
        frag.buf.delta.clear();
        frag.buf.slots.clear();
        frag.total_docs = 0;
        frag.total_tokens = 0;
        frag.exact.iter_mut().for_each(|e| *e = true);
        // Порог сброса проверяется **после** вливания, ровно один раз на кусок.
        //
        // Прежде его проверял каждый документ, и сегмент выходил в точности
        // заданного размера. Кусок вливается целиком, поэтому сегмент вправе
        // перерасти порог на неполную пачку — но не больше: следующий кусок
        // застанет буфер уже отданным.
        //
        // Забыть эту проверку значит выключить сброс по счётчику вовсе: буфер
        // растёт до самой памяти, а сегмент выходит один на весь индекс. Так и
        // было, и поймали это проверки пределов, а не рассуждение.
        if !self.defer_flush && self.full() {
            self.flush();
        }
    }

    /// Вливает detached-кусок, собранный заменами вне общего ingest-lock.
    ///
    /// Повторные ID внутри куска должны быть погашены его `replace*` путём.
    /// Здесь старые копии в целевом буфере гасятся до присоединения новых,
    /// а гашения дисковых версий публикуются вместе с новым хранителем.
    /// Возвращает число погашенных buffered-версий, включая уже мёртвые
    /// версии внутри куска; дисковые supersede в это число не входят.
    /// Кусок остаётся пустым, без pending supersede, и пригодным к повтору.
    /// Для атомарной WAL-пачки вызывающий окружает вызов `begin_atomic_batch`
    /// / `finish_atomic_batch` и удерживает свой apply/visibility lock.
    pub fn absorb_replacing(&mut self, frag: &mut Indexer<A>) -> usize {
        let mut killed = frag.buf.dead.iter().filter(|&&dead| dead).count();
        {
            let mut seen = std::collections::HashSet::with_capacity(frag.buf.ids.len());
            for id in &frag.buf.ids {
                if seen.insert(id.as_str()) {
                    killed += self.kill_buffered(id);
                    self.supersedes(id);
                }
            }
        }
        // Detached supersedes refer to the same staged IDs. The receiving
        // buffer now owns that obligation; retain no stale IDs in the pool.
        frag.superseded.clear();
        self.absorb(frag);
        killed
    }

    /// Ставит порог, ниже которого слово не хранит позиций.
    ///
    /// Порядок тот же, что у объявленных полей. Не задано — номер равен
    /// позиции, и это верно ровно до первого изменения схемы: как только поле
    /// вставили в середину или похоронили, позиция перестаёт быть личностью
    /// поля, и сегменты разного возраста начинают понимать один номер по-разному.
    pub fn set_fids(&mut self, fids: Vec<u32>) {
        assert_eq!(
            fids.len(),
            self.fields.len(),
            "устойчивых номеров {}, а полей {}",
            fids.len(),
            self.fields.len()
        );
        self.fids = fids;
    }

    /// Объявляет группу каждого поля и путь каждой группы.
    pub fn set_groups(&mut self, groups: Vec<u32>, paths: Vec<String>) {
        assert_eq!(
            groups.len(),
            self.fields.len(),
            "групп {}, а полей {}",
            groups.len(),
            self.fields.len()
        );
        assert!(!paths.is_empty() && paths[0].is_empty(), "нулевая группа обязана быть корневой");
        self.groups = groups;
        self.group_paths = paths;
        // Поле внутри массива получает позиции, даже если оно ключевое слово.
        for f in 0..self.fields.len() {
            let g = self.groups.get(f).copied().unwrap_or(0);
            let kind = self.kinds.get(f).copied().unwrap_or(Kind::Text);
            if g != 0
                && (kind.numeric()
                    || matches!(
                        kind,
                        Kind::Text | Kind::Keyword | Kind::KeywordExact | Kind::Binary
                    ))
            {
                self.positioned[f] = true;
            }
        }
    }

    /// Добавляет документ с массивами.
    ///
    /// `arity` — длина массива каждой группы по её номеру; нулевая ячейка не
    /// читается, у корня всегда один слот. `cells` — значения по элементам, в
    /// любом порядке; слот обязан быть меньше арности своей группы.
    ///
    /// Арность приходит **явно**, а не выводится как наибольший встреченный
    /// слот: последние элементы массива могут не иметь ни одного
    /// индексируемого поля, и вывод дал бы им исчезнуть.
    pub fn add_cells(&mut self, id: &str, arity: &[u32], cells: &[Cell<'_>]) {
        self.add_cells_pre(id, arity, cells, None);
    }

    /// Presence-safe ячейковый путь с токенами, разобранными вне общего
    /// буфера приёма.
    ///
    /// Плотный `add_pre` не различает отсутствующее значение и пустую строку.
    /// Для lossless source это недопустимо, но возвращать токенизацию под
    /// общий lock тоже нельзя: на Flat-10M она отняла почти половину приёма.
    /// Cells сохраняют presence, а `pre` выносит чистую работу наружу.
    pub fn add_cells_pre(
        &mut self,
        id: &str,
        arity: &[u32],
        cells: &[Cell<'_>],
        pre: Option<&mut [crate::analyze::Tokens]>,
    ) {
        let t0 = std::time::Instant::now();
        self.add_cells_inner(id, arity, cells, pre);
        tick(&mut self.phases, "разбор", t0.elapsed().as_secs_f64());
        if !self.defer_flush && self.full() {
            self.flush();
        }
    }

    fn add_cells_inner(
        &mut self,
        id: &str,
        arity: &[u32],
        cells: &[Cell<'_>],
        mut pre: Option<&mut [crate::analyze::Tokens]>,
    ) {
        let doc = self.buf.docs;
        let ngroups = self.group_paths.len().max(1);
        if self.buf.arity.len() < ngroups {
            self.buf.arity.resize(ngroups, Vec::new());
        }
        // Арность корня всегда единица: у документа один «элемент» — он сам.
        self.buf.took(id.len() + HEAD + 1 + 8 + 4 * ngroups);
        for g in 0..ngroups {
            let a = if g == 0 { 1 } else { arity.get(g).copied().unwrap_or(0) };
            self.buf.arity[g].push(a);
        }

        for f in 0..self.fields.len() {
            let g = self.groups.get(f).copied().unwrap_or(0) as usize;
            let n = if g == 0 { 1 } else { arity.get(g).copied().unwrap_or(0) };
            let kind = self.kinds.get(f).copied().unwrap_or(Kind::Text);

            if self.stored.get(f).copied().unwrap_or(true) {
                let mut s = String::new();
                for slot in 0..n {
                    if slot > 0 {
                        s.push(US);
                    }
                    if let Some(c) = cells.iter().find(|c| c.field == f && c.slot == slot) {
                        s.push_str(c.text);
                    }
                }
                self.buf.took(s.len() + HEAD);
                self.buf.vals[f].push(s);
            }

            // `noindex` — то же правило, что и на обычном пути. Два пути приёма
            // уже расходились однажды; повторять это по одному признаку за раз
            // — верный способ получить два разных индекса из одного корпуса.
            if !self.searched.get(f).copied().unwrap_or(true) {
                self.buf.took(1);
                self.buf.norms[f].push(0);
                continue;
            }

            if let Some(dims) = kind.dims() {
                // Вектор внутри массива не поддержан: у него нет понятия
                // элемента. Корневой lossless-документ при этом тоже идёт
                // ячейками и обязан получить тот же vector-код, что плотный
                // путь, а не молча пустой вектор.
                let value = (g == 0)
                    .then(|| cells.iter().find(|cell| cell.field == f && cell.slot == 0))
                    .flatten()
                    .and_then(|cell| crate::vector::parse(cell.text, dims))
                    .unwrap_or_default();
                self.buf.took(value.len() * 4 + HEAD + 1);
                self.buf.vecs[f].push(value);
                self.buf.norms[f].push(0);
                continue;
            }

            if kind.dot() {
                // Sparse-vector хранится постингами измерений. Внутри массива
                // он, как и dense, не имеет определённой slot-семантики;
                // корневой ячейковый путь совпадает с `add_inner_with`.
                self.buf.norms[f].push(0);
                if g != 0 {
                    continue;
                }
                let pairs = cells
                    .iter()
                    .find(|cell| cell.field == f && cell.slot == 0)
                    .and_then(|cell| crate::sparse::parse(cell.text))
                    .unwrap_or_default();
                for (dim, weight) in pairs {
                    let code = crate::sparse::encode(weight);
                    if code == 0 {
                        continue;
                    }
                    self.key.clear();
                    self.key.extend_from_slice(&(f as u32).to_be_bytes());
                    self.key.extend_from_slice(dim.as_bytes());
                    let entry = match self.buf.lists.get_mut(self.key.as_slice()) {
                        Some(entry) => entry,
                        None => self.buf.lists.entry(self.key.as_slice().into()).or_default(),
                    };
                    self.buf.delta.touch(&self.key, entry);
                    entry.docs.push(doc);
                    entry.tfs.push(code);
                    self.buf.took(5);
                }
                continue;
            }

            if kind.numeric() {
                // Значение на каждый слот: пропуск занимает место, но не
                // получает бита присутствия. Так номер слота остаётся номером
                // элемента, а не номером присутствующего значения.
                let mut exact_values = Vec::new();
                for slot in 0..n {
                    let text = cells
                        .iter()
                        .find(|c| c.field == f && c.slot == slot)
                        .map(|c| c.text)
                        .unwrap_or("");
                    let parts = multi_parts(text);
                    let values = parts.as_deref().unwrap_or_else(|| std::slice::from_ref(&text));
                    let v = if values.len() == 1 { kind.parse_value(values[0]) } else { None };
                    if self.exact[f] {
                        self.exact[f] = prints_back(kind, v, text);
                    }
                    let parsed: Vec<i64> = if values.len() > 1 {
                        values.iter().filter_map(|value| kind.parse_value(value)).collect()
                    } else {
                        Vec::new()
                    };
                    let added = self.buf.multi[f].add(self.buf.cols[f].len(), &parsed);
                    self.buf.took(added);
                    self.buf.build_reserve =
                        self.buf.build_reserve.saturating_add(parsed.len().saturating_mul(96));
                    self.buf.took(8 + 1);
                    self.buf.cols[f].push(v.unwrap_or(0));
                    self.buf.has[f].push(v.is_some());
                    for value in values {
                        if let Some(parsed) = kind.parse_value(value) {
                            exact_values.push((parsed, slot));
                        }
                    }
                }
                self.write_numeric_exact(f, doc, &exact_values, !exact_values.is_empty());
                self.buf.took(1);
                self.buf.norms[f].push(0);
                continue;
            }

            // Текст и ключевое слово: позиция токена — номер элемента.
            let tokenize_started = profile_start();
            self.toks.clear();
            self.toks_at.clear();
            let prepared = if g == 0 {
                pre.as_mut().and_then(|fields| fields.get_mut(f)).filter(|words| !words.is_empty())
            } else {
                None
            };
            if let Some(words) = prepared {
                std::mem::swap(&mut self.toks, words);
                self.toks_at.extend(0..self.toks.len() as u32);
            } else {
                for slot in 0..n {
                    let Some(c) = cells.iter().find(|c| c.field == f && c.slot == slot) else {
                        continue;
                    };
                    if kind.keyword() || kind == Kind::Binary {
                        let values = multi_parts(c.text).unwrap_or_else(|| vec![c.text]);
                        for value in values {
                            if kind == Kind::Binary {
                                let t = value.trim();
                                if t.is_empty() {
                                    continue;
                                }
                                self.toks.push(t);
                            } else {
                                let term = keyword_term(value, kind.folds_case());
                                self.toks.push(&term);
                            }
                            if kind != Kind::Binary || !value.trim().is_empty() {
                                self.toks_at.push(slot);
                            }
                        }
                    } else {
                        let values = multi_parts(c.text).unwrap_or_else(|| vec![c.text]);
                        for value in values {
                            let before = self.toks.len();
                            let mut part = std::mem::take(&mut self.parts);
                            self.analyzer.tokenize_flat(value, &mut part);
                            self.toks.append(&mut part);
                            self.parts = part;
                            let added = self.toks.len() - before;
                            if g == 0 {
                                // Корневое поле: позиция — номер слова по порядку.
                                self.toks_at.extend(before as u32..(before + added) as u32);
                            } else {
                                // Поле внутри массива объектов: слова одного
                                // элемента делят его slot.
                                self.toks_at.extend(std::iter::repeat_n(slot, added));
                            }
                        }
                    }
                }
            }
            profile_tick(&mut self.phases, "токенизация", tokenize_started);
            // Ключевому полю — постоянная единица, как и на обычном пути: у
            // него длина не бывает иной, и постоянство сливает его полосу с
            // полосами остальных ключевых полей.
            if kind.keyword() {
                let present = if g == 0 {
                    usize::from(!self.toks.is_empty())
                } else {
                    usize::from(!self.toks_at.is_empty())
                        + self.toks_at.windows(2).filter(|pair| pair[0] != pair[1]).count()
                };
                self.buf.reserve_keyword_build(n as usize, self.toks.len(), present);
            }
            let q = match (g, kind) {
                (0, Kind::Keyword) | (0, Kind::KeywordExact) | (0, Kind::Binary) => 1,
                (0, _) => level(self.toks.len()),
                _ => 0,
            };
            self.buf.took(1);
            self.buf.norms[f].push(q);
            for cell in cells.iter().filter(|cell| cell.field == f) {
                let present = presence_term(kind);
                self.toks.push(&present);
                self.toks_at.push(cell.slot);
            }
            if crate::stats::ENABLED {
                self.total_tokens += self.toks.len() as u64;
            }
            let postings_started = profile_start();
            self.seen.clear();
            self.seen.extend(self.toks.iter().enumerate().map(|(i, t)| (word_hash(t), i as u32)));
            Self::group(&mut self.seen, &self.toks);
            // Slots нужны для построения keyword doc values даже при nopos.
            // На диске полоса поисковых позиций всё ещё определяется schema.
            let keep = self.positioned.get(f).copied().unwrap_or(true)
                || (kind.keyword() && self.groups.get(f).copied().unwrap_or(0) != 0);
            write_postings(
                &mut self.buf,
                &mut self.key,
                &self.seen,
                &self.toks,
                &self.toks_at,
                f,
                doc,
                keep,
            );
            profile_tick(&mut self.phases, "словарь и постинги", postings_started);
        }
        self.buf.ids.push(id.to_string());
        self.buf.dead.push(false);
        // Тем же хешем, что и плоский путь, и что все три опроса таблицы.
        // `word_hash` здесь был опиской с далёкими последствиями: документ
        // ложился в корзину от одной функции, а искался от другой, и для
        // замены с удалением попросту не существовал. Разбор — у
        // [`slots_hash_tests`].
        self.buf.slots.insert(crate::bloom::hash(id), doc, &self.buf.ids);
        self.buf.docs += 1;
        self.total_docs += 1;
    }

    /// Предел, за которым живой двойник отданного буфера не собирается.
    pub fn set_live_max_docs(&mut self, v: u32) {
        self.live_max_docs = v;
    }

    pub fn set_posmin(&mut self, v: u32) {
        let usable = self.kinds.iter().enumerate().any(|(f, k)| {
            *k == Kind::Text
                && self.positioned.get(f).copied().unwrap_or(true)
                && self.stored.get(f).copied().unwrap_or(true)
        });
        self.posmin = if usable { v } else { 0 };
    }

    /// Добавляет документ. `values` — по значению на каждое объявленное поле.
    pub fn add(&mut self, id: &str, values: &[&str]) {
        self.add_pre(id, values, None)
    }

    /// Приём документа со словами, разобранными заранее.
    ///
    /// ## Зачем
    ///
    /// Токенизация — самая дорогая часть укладки после сжатия, и вся она шла
    /// под замком буфера приёма, то есть в один поток на весь узел. Замер на
    /// разнородном корпусе: 178 секунд процессора на десять миллионов
    /// документов, тогда как весь сериализованный участок плоского корпуса —
    /// тринадцать микросекунд на документ.
    ///
    /// Разобрать слова снаружи можно: разборщик не имеет состояния, а схема
    /// узла неизменна с его старта. Под замком остаётся то, что без него
    /// невозможно, — словарь и списки.
    ///
    /// Слова **переставляются** в рабочий буфер, а не копируются: вызывающий
    /// получает свои векторы опустошёнными и переиспользует их ёмкости на
    /// следующем документе.
    pub fn add_pre(
        &mut self,
        id: &str,
        values: &[&str],
        pre: Option<&mut [crate::analyze::Tokens]>,
    ) {
        let t0 = std::time::Instant::now();
        self.add_inner_with(id, values, pre);
        tick(&mut self.phases, "разбор", t0.elapsed().as_secs_f64());
        if !self.defer_flush && self.full() {
            self.flush();
        }
    }

    /// Пора ли сбрасывать: по числу документов **или** по объёму.
    #[inline]
    fn full(&self) -> bool {
        self.buf.docs >= self.per_segment
            || (self.flush_bytes > 0 && self.buffered_bytes() >= self.flush_bytes)
    }

    /// Начинает малую атомарную пачку: автоматический порог не режет её надвое.
    pub fn begin_atomic_batch(&mut self) {
        debug_assert!(!self.defer_flush, "атомарная пачка вложена сама в себя");
        self.defer_flush = true;
    }

    /// Завершает пачку и применяет отложенный порог ровно один раз.
    ///
    /// Возвращает `true`, если буфер был передан на запись.
    pub fn finish_atomic_batch(&mut self) -> bool {
        self.defer_flush = false;
        if self.full() {
            let before = self.segments();
            self.flush();
            return self.segments() != before || self.flush_inflight();
        }
        false
    }

    /// Снимает запрет автоматического сброса после отказавшей пачки.
    ///
    /// Отката содержимого здесь намеренно нет: индексатор не знает границу
    /// транзакции внутри своих колонок. Вызывающий обязан прекратить работу и
    /// переиграть durable WAL; главное — не опубликовать частичную пачку в
    /// процессе обработки ошибки.
    pub fn cancel_atomic_batch(&mut self) {
        self.defer_flush = false;
    }

    /// Меняет потолок объёма буфера. `0` — только по числу документов.
    pub fn set_flush_bytes(&mut self, n: usize) {
        self.flush_bytes = n;
    }

    /// Действующий потолок объёма буфера в байтах.
    pub fn flush_bytes(&self) -> usize {
        self.flush_bytes
    }

    /// Обычный путь — целочисленная сортировка по паре «хеш, позиция». Порядок
    /// между разными словами не важен: словарь сортируется заново при сбросе, а
    /// от этого прохода нужна только смежность повторов и возрастание позиций
    /// внутри группы.
    ///
    /// Столкновение хешей разложило бы два **разных** слова вперемешку, и
    /// группировка выдала бы одному слову два постинга на один документ — то
    /// есть повторяющийся номер в списке. Поэтому столкновение не
    /// предполагается невозможным, а ловится: если после группы идёт элемент с
    /// тем же хешем, порядок пересобирается по самим строкам. На 64-битном хеше
    /// эта ветка не срабатывает никогда, но стоить она обязана ровно ноль, пока
    /// не сработала.
    fn group(seen: &mut [(u64, u32)], toks: &crate::analyze::Tokens) {
        seen.sort_unstable();
        let mut at = 0usize;
        while at < seen.len() {
            let word = toks.get(seen[at].1 as usize);
            let mut to = at + 1;
            while to < seen.len()
                && seen[to].0 == seen[at].0
                && toks.get(seen[to].1 as usize) == word
            {
                to += 1;
            }
            if to < seen.len() && seen[to].0 == seen[at].0 {
                // Тот же хеш, другое слово. Дальше по хешу верить нельзя.
                seen.sort_unstable_by(|a, b| {
                    toks.get(a.1 as usize).cmp(toks.get(b.1 as usize)).then(a.1.cmp(&b.1))
                });
                return;
            }
            at = to;
        }
    }

    /// Слова поля: ровно то, что путь приёма кладёт в словарь.
    ///
    /// Вынесено отдельной функцией не ради опрятности, а ради **тождества**.
    /// Слова теперь разбираются в двух местах — под замком буфера и заранее,
    /// вне его, — и разойдись эти два места хоть в одном правиле, сегмент
    /// зависел бы от того, каким путём документ попал в приём. Один код на обоих
    /// вызывающих делает расхождение невозможным по построению.
    pub fn field_tokens<A2: Analyzer>(
        a: &A2,
        kind: Kind,
        text: &str,
        out: &mut crate::analyze::Tokens,
    ) {
        if kind.keyword() || kind == Kind::Binary {
            // Ключевое слово — значение целиком, без разбора на слова.
            //
            // Регистр сводится у ключевого и **не сводится** у двоичного:
            // Base64 регистрозначим, и `AQAAAB8ABbBc` с `aqaaab8abbbc` — разные
            // байты. Свести их значило бы склеить два разных значения в одно, и
            // склеить молча.
            out.clear();
            let values = multi_parts(text).unwrap_or_else(|| vec![text]);
            for value in values {
                if kind == Kind::Binary {
                    let t = value.trim();
                    if !t.is_empty() {
                        out.push(t);
                    }
                } else {
                    let term = keyword_term(value, kind.folds_case());
                    out.push(&term);
                }
            }
        } else {
            match multi_parts(text) {
                Some(values) => {
                    out.clear();
                    for value in values {
                        let mut part = crate::analyze::Tokens::default();
                        a.tokenize_flat(value, &mut part);
                        out.append(&mut part);
                    }
                }
                None => a.tokenize_flat(text, out),
            }
        }
    }

    /// Точное совпадение по числу идёт тем же инвертированным списком, что
    /// keyword. Колонка остаётся для range/sort; список закрывает ES term/terms
    /// и несколько чисел в одном JSON-массиве.
    fn write_numeric_exact(
        &mut self,
        field: usize,
        doc: u32,
        values: &[(i64, u32)],
        present: bool,
    ) {
        self.toks.clear();
        self.toks_at.clear();
        let rendered: Vec<String> = values.iter().map(|(value, _)| value.to_string()).collect();
        for ((_, slot), text) in values.iter().zip(rendered.iter()) {
            self.toks.push(text);
            self.toks_at.push(*slot);
        }
        if present {
            let marker = presence_term(self.kinds.get(field).copied().unwrap_or(Kind::Text));
            let mut slots: Vec<u32> = values.iter().map(|(_, slot)| *slot).collect();
            slots.sort_unstable();
            slots.dedup();
            for slot in slots {
                self.toks.push(&marker);
                self.toks_at.push(slot);
            }
        }
        self.seen.clear();
        self.seen
            .extend(self.toks.iter().enumerate().map(|(i, token)| (word_hash(token), i as u32)));
        Self::group(&mut self.seen, &self.toks);
        write_postings(
            &mut self.buf,
            &mut self.key,
            &self.seen,
            &self.toks,
            &self.toks_at,
            field,
            doc,
            true,
        );
    }

    /// То же, но со словами, разобранными заранее и вне замка буфера.
    ///
    /// `pre` — по номеру поля; пустой вектор означает «разобрать здесь».
    /// Векторы **переставляются** в рабочий буфер, поэтому вызывающий получает
    /// их обратно опустошёнными и может переиспользовать ёмкости.
    fn add_inner_with(
        &mut self,
        id: &str,
        values: &[&str],
        mut pre: Option<&mut [crate::analyze::Tokens]>,
    ) {
        let doc = self.buf.docs;
        // Документ сам по себе: строка идентификатора с заголовком, байт в
        // карте живых и ячейка таблицы поиска по идентификатору.
        self.buf.took(id.len() + HEAD + 1 + 8);
        for (f, text) in values.iter().enumerate() {
            if self.stored.get(f).copied().unwrap_or(true) {
                // Заголовок `String` — на **каждое** поле, заполнено оно или
                // нет. Именно он делает широкую схему дорогой: у документа,
                // трогающего три процента из четырёхсот семидесяти полей,
                // заголовки весят одиннадцать килобайт, а данные — двести байт.
                self.buf.took(text.len() + HEAD);
                self.buf.vals[f].push((*text).to_string());
            }
            let kind = self.kinds.get(f).copied().unwrap_or(Kind::Text);
            // `noindex`: содержимое уже легло в хранимое выше, а дальше поле не
            // идёт никуда — ни списком в словарь, ни значением в колонку.
            //
            // Место в полосе норм отводится всё равно, чтобы полоса на поле
            // оставалась одной длины: `norms::bands` режет её по числу
            // документов, и поле короче сдвинуло бы все следующие.
            if !self.searched.get(f).copied().unwrap_or(true) {
                self.buf.norms[f].push(0);
                continue;
            }
            if let Some(dims) = kind.dims() {
                // Не разобравшийся вектор кладётся пустым, а не отвергает
                // документ целиком: остальные поля у него в порядке, и терять
                // их из-за одного кривого значения не за что. Пустой в выдачу
                // не попадёт — см. [`crate::vector::build`].
                let v = crate::vector::parse(text, dims).unwrap_or_default();
                self.buf.took(v.len() * 4 + HEAD + 1);
                self.buf.vecs[f].push(v);
                // Ни колонки, ни бита присутствия: у вектора нет значения,
                // которое можно сравнить, и отбор по нему идёт не диапазоном.
                // В нормах место отводится, чтобы полоса на поле оставалась
                // одной длины, но длина всегда нулевая.
                self.buf.norms[f].push(0);
                continue;
            }
            if kind.dot() {
                let pairs = crate::sparse::parse(text).unwrap_or_default();
                // Длина документа для BM25 не считается: её здесь нет как
                // понятия. Место в полосе норм всё равно отводится, чтобы полоса
                // на поле оставалась одной длины.
                self.buf.norms[f].push(0);
                for (dim, w) in pairs.iter() {
                    let code = crate::sparse::encode(*w);
                    if code == 0 {
                        continue;
                    }
                    self.key.clear();
                    self.key.extend_from_slice(&(f as u32).to_be_bytes());
                    self.key.extend_from_slice(dim.as_bytes());
                    let e = match self.buf.lists.get_mut(self.key.as_slice()) {
                        Some(e) => e,
                        None => self.buf.lists.entry(self.key.as_slice().into()).or_default(),
                    };
                    self.buf.delta.touch(&self.key, e);
                    e.docs.push(doc);
                    e.tfs.push(code);
                    self.buf.took(5);
                }
                continue;
            }
            if kind.numeric() {
                let parts = multi_parts(text);
                let values = parts.as_deref().unwrap_or_else(|| std::slice::from_ref(text));
                let v = if values.len() == 1 { kind.parse_value(values[0]) } else { None };
                if self.exact[f] {
                    self.exact[f] = prints_back(kind, v, text);
                }
                let parsed: Vec<i64> = if values.len() > 1 {
                    values.iter().filter_map(|value| kind.parse_value(value)).collect()
                } else {
                    Vec::new()
                };
                let added = self.buf.multi[f].add(self.buf.cols[f].len(), &parsed);
                self.buf.took(added);
                self.buf.build_reserve =
                    self.buf.build_reserve.saturating_add(parsed.len().saturating_mul(96));
                self.buf.took(8 + 1 + 1);
                self.buf.cols[f].push(v.unwrap_or(0));
                self.buf.has[f].push(v.is_some());
                self.buf.norms[f].push(0);
                let exact: Vec<(i64, u32)> = values
                    .iter()
                    .filter_map(|value| kind.parse_value(value).map(|v| (v, 0)))
                    .collect();
                self.write_numeric_exact(f, doc, &exact, !exact.is_empty());
                continue;
            }
            let tokenize_started = profile_start();
            // Слова либо разобраны заранее — вне замка буфера, — либо здесь.
            //
            // Заранее разобранные **переставляются**, а не копируются: обмен
            // векторов не трогает кучу вовсе, тогда как копия вернула бы под
            // замок ровно те выделения, ради выноса которых всё и делалось.
            match pre.as_mut().and_then(|p| p.get_mut(f)).filter(|w| !w.is_empty()) {
                Some(words) => std::mem::swap(&mut self.toks, words),
                None => Self::field_tokens(&self.analyzer, kind, text, &mut self.toks),
            }
            profile_tick(&mut self.phases, "токенизация", tokenize_started);
            // Длина поля — в токенах, до схлопывания повторов: BM25 нормирует
            // на длину документа, а не на размер его словаря.
            //
            // У ключевого поля длина **постоянна**, и это не упрощение.
            // Значение там одно и целиком, то есть уровень бывает только 0
            // (значения нет) или 1 (есть); `avgdl` в обоих случаях выходит 1.0
            // из-за `max(1.0)`, а `Index::level` читается **только** для
            // документов, найденных в постингах, — то есть для тех, у кого
            // значение есть. Значит ноль отсутствующих не наблюдаем ниоткуда,
            // а постоянная полоса сливается с полосами всех остальных
            // ключевых полей: было по байту на документ на каждое поле, стало
            // по байту на все. На схеме с двумя сотнями ключевых полей это
            // двести байт на документ.
            let flat = kind.keyword() || kind == Kind::Binary;
            if kind.keyword() {
                self.buf.reserve_keyword_build(
                    1,
                    self.toks.len(),
                    usize::from(!self.toks.is_empty()),
                );
            }
            self.buf.took(1);
            self.buf.norms[f].push(if flat { 1 } else { level(self.toks.len()) });
            if crate::stats::ENABLED {
                self.total_tokens += self.toks.len() as u64;
            }
            let postings_started = profile_start();
            // Позиция обычного текста — номер токена по порядку. У поля внутри
            // массива она приходит извне и означает номер элемента.
            self.toks_at.clear();
            self.toks_at.extend(0..self.toks.len() as u32);
            self.seen.clear();
            self.seen.extend(self.toks.iter().enumerate().map(|(i, t)| (word_hash(t), i as u32)));
            Self::group(&mut self.seen, &self.toks);
            let keep = self.positioned.get(f).copied().unwrap_or(true);
            write_postings(
                &mut self.buf,
                &mut self.key,
                &self.seen,
                &self.toks,
                &self.toks_at,
                f,
                doc,
                keep,
            );
            profile_tick(&mut self.phases, "словарь и постинги", postings_started);
        }
        self.buf.ids.push(id.to_string());
        self.buf.dead.push(false);
        // Идентификатор запоминается **после** того, как строка легла в `ids`:
        // таблица хранит номера, а строки читает оттуда, и пересборка при росте
        // ищет их там же.
        self.buf.slots.insert(crate::bloom::hash(id), doc, &self.buf.ids);
        self.buf.docs += 1;
        self.total_docs += 1;
    }

    /// Гасит в буфере приёма все живые копии документа. Отдаёт, сколько погасил.
    pub fn kill_buffered(&mut self, id: &str) -> usize {
        // A matching flying buffer must land before callers search disk
        // segments for older copies. An absent ID cannot be resurrected by
        // that flush, so unrelated replacements need not wait for disk.
        if self.flush_inflight()
            && self.inflight_id_hashes.binary_search(&crate::bloom::hash(id)).is_ok()
        {
            self.drain();
        }
        if self.buf.docs == 0 {
            return 0;
        }
        self.hits.clear();
        self.buf.slots.find(crate::bloom::hash(id), id, &self.buf.ids, &mut self.hits);
        let mut killed = 0usize;
        for &d in self.hits.iter() {
            let slot = &mut self.buf.dead[d as usize];
            if !*slot {
                *slot = true;
                killed += 1;
            }
        }
        killed
    }

    /// Последнее живое значение поля у документа в текущем буфере.
    ///
    /// Метод ничего не ждёт и не трогает карту живых. Вызывающий, которому
    /// нужна полная картина для CAS, обязан сперва забрать фоновый flush и затем
    /// проверить уже опубликованные сегменты. Разделение намеренное: только
    /// сервер знает, под какими ingest/layout-замками это можно сделать без окна.
    pub fn buffered_value(&mut self, id: &str, field: usize) -> Option<String> {
        if !self.stored.get(field).copied().unwrap_or(false) {
            return None;
        }
        let doc = self.buffered_doc(id)?;
        self.buffered_at(doc, field)
    }

    /// Номер последней **живой** версии документа в текущем буфере.
    ///
    /// Отдельно от [`Indexer::buffered_value`], потому что читателей у поиска по
    /// идентификатору два: условию CAS нужно одно поле, а выдаче документа —
    /// все сразу. Искать документ заново на каждое поле значило бы обойти буфер
    /// столько раз, сколько в схеме полей, — и, что хуже, между обходами
    /// собрать значения **разных** версий, если рядом идёт запись.
    pub fn buffered_doc(&mut self, id: &str) -> Option<u32> {
        if self.buf.docs == 0 {
            return None;
        }
        self.hits.clear();
        self.buf.slots.find(crate::bloom::hash(id), id, &self.buf.ids, &mut self.hits);
        // С конца: живых версий одного идентификатора в буфере бывает несколько,
        // и нужна последняя.
        self.hits
            .iter()
            .rev()
            .copied()
            .find(|&d| !self.buf.dead.get(d as usize).copied().unwrap_or(true))
    }

    /// Значение поля у буферизованной версии, найденной [`Indexer::buffered_doc`].
    pub fn buffered_at(&self, doc: u32, field: usize) -> Option<String> {
        if !self.stored.get(field).copied().unwrap_or(false) {
            return None;
        }
        self.buf.vals.get(field).and_then(|v| v.get(doc as usize)).cloned()
    }

    /// Гашение в сегментах — забота вызывающего: буфер знает только про себя.
    /// Отдаёт, сколько версий погашено здесь.
    pub fn replace(&mut self, id: &str, values: &[&str]) -> usize {
        self.replace_pre(id, values, None)
    }

    /// Замена с токенами, подготовленными до захвата ingest-lock.
    pub fn replace_pre(
        &mut self,
        id: &str,
        values: &[&str],
        pre: Option<&mut [crate::analyze::Tokens]>,
    ) -> usize {
        let killed = self.kill_buffered(id);
        self.supersedes(id);
        self.add_pre(id, values, pre);
        killed
    }

    /// То же для документа с массивами.
    pub fn replace_cells(&mut self, id: &str, arity: &[u32], cells: &[Cell]) -> usize {
        self.replace_cells_pre(id, arity, cells, None)
    }

    /// Разреженная замена с заранее подготовленными токенами.
    pub fn replace_cells_pre(
        &mut self,
        id: &str,
        arity: &[u32],
        cells: &[Cell],
        pre: Option<&mut [crate::analyze::Tokens]>,
    ) -> usize {
        let killed = self.kill_buffered(id);
        self.supersedes(id);
        self.add_cells_pre(id, arity, cells, pre);
        killed
    }

    /// Запоминает, что прежние версии этого идентификатора обязаны погаснуть,
    /// когда нынешний буфер будет опубликован. См. [`Indexer::superseded`].
    fn supersedes(&mut self, id: &str) {
        // Повтор в пределах одного буфера не нужен: гашение идёт по составу и
        // от числа упоминаний не зависит, а список едет до самой публикации.
        if self.superseded.last().is_some_and(|last| last == id)
            && self
                .frozen
                .as_ref()
                .is_none_or(|state| self.superseded.len() > state.recorded_superseded)
        {
            return;
        }
        self.superseded.push(id.to_string());
    }

    /// Забирает список идентификаторов, чьи прежние версии пора погасить.
    ///
    /// Пуст, пока сегмент не лёг и не внесён в состав. Вызывающий обязан
    /// применить его **после** внесения: до — и документ на миг остался бы без
    /// единой живой версии, ради чего гашение и откладывалось.
    pub fn take_superseded(&mut self) -> Vec<(String, Vec<String>)> {
        std::mem::take(&mut self.landed_superseded)
    }

    /// Возвращает не применённое обратно: хранителя не нашлось в составе, и
    /// попытку надо повторить, а не потерять.
    /// Слияние подменило имена сегментов — обязательства переезжают на выход.
    ///
    /// ## Зачем
    ///
    /// Обязательство погасить прежние версии привязано к хранителю **именем
    /// каталога**, а `maintain::supersede_in` разрешает его точным сравнением
    /// строк. Слияние законно уничтожает это имя: источники сносятся, выход
    /// встаёт под своим. Обязательство, не успевшее примениться до слияния,
    /// становится неисполнимым **навсегда** — имена монотонны и не
    /// возвращаются, а `supersede_in` кладёт ненайденное обратно под тем же
    /// мёртвым именем и пробует снова, круг за кругом, впустую.
    ///
    /// Итог на стенде: после одиннадцати тысяч замен одного `id` под приёмом,
    /// поиском и удалением в составе оставались **две** живые версии, и они
    /// переживали покой. Прежнюю должно было погасить пропавшее обязательство;
    /// всё, что старше, погасили обязательства прежние — успешные.
    ///
    /// ## Почему выход слияния — законный хранитель
    ///
    /// Слияние переносит живые документы как есть: `remap` читает карту живых
    /// один раз и перекладывает уцелевших в выход. Значит всё, что жило в
    /// источнике, живёт и в выходе, и «гасить в пользу источника» ровно то же,
    /// что «гасить в пользу выхода». Семантика не меняется, меняется имя.
    ///
    /// Порядок «сперва состав, потом гашение» не трогается: окно, где у
    /// документа нет ни одной живой версии, не возвращается.
    pub fn rename_keeper(&mut self, gone: &[String], now: &str) {
        if gone.is_empty() {
            return;
        }
        // Сравниваем по последнему звену пути: обязательство хранит полный
        // путь (`{корень}/seg0007`), а слияние знает имена каталогов. Сверять
        // строку целиком значило бы промахиваться на одном лишь написании.
        let tail = |p: &str| p.rsplit('/').next().unwrap_or(p).to_string();
        let gone_tails: Vec<String> = gone.iter().map(|g| tail(g)).collect();
        let mut moved: Vec<String> = Vec::new();
        for (keeper, ids) in self.landed_superseded.iter_mut() {
            if gone_tails.contains(&tail(keeper)) {
                moved.append(ids);
                // Помечаем опустевшим: убирать сразу нельзя, идём по ссылке.
                keeper.clear();
            }
        }
        self.landed_superseded.retain(|(k, ids)| !k.is_empty() && !ids.is_empty());
        if !moved.is_empty() {
            self.put_back_superseded(vec![(now.to_string(), moved)]);
        }
    }

    pub fn put_back_superseded(&mut self, pending: Vec<(String, Vec<String>)>) {
        for (keeper, ids) in pending {
            match self.landed_superseded.iter_mut().find(|(k, _)| *k == keeper) {
                Some((_, have)) => have.extend(ids),
                None => self.landed_superseded.push((keeper, ids)),
            }
        }
    }

    /// Сколько документов буфера уже погашено — для отчёта и для сверки.
    /// Оценка **занятой** буфером приёма памяти в байтах — та самая, по которой
    /// решается сброс. С поправкой на запас ёмкости; см. [`SLACK`].
    /// Перерос ли буфер отведённое ему — признак, по которому приём осаживают.
    ///
    /// ## Зачем понадобилось
    ///
    /// Порог сброса (`flush_bytes`) говорит, когда буфер пора отдать писателю.
    /// Он не говорит, что делать, если писатель ещё занят предыдущим сегментом:
    /// приём продолжал класть в буфер, и тот рос, пока хватало памяти. На
    /// стенде это и убивало узел — куча доходила до восемнадцати гигабайт, и
    /// ядро снимало процесс на тридцать первом миллионе.
    ///
    /// Уменьшать расход мало: любой предел, не осаживающий пишущего, рано или
    /// поздно перерастается, если писать быстрее, чем узел успевает укладывать
    /// на диск. Нужна не экономия, а **встречное давление**.
    ///
    /// ## Почему потолок именно вдвое
    ///
    /// Это не подобранное число, а само устройство оборота: буферов в работе
    /// ровно два — набираемый и отданный писателю. Больше двух взяться неоткуда
    /// (см. `spare`), поэтому и памяти под них нужно ровно на два. Потолок
    /// растёт вместе с порогом, а тот выводится из доступной памяти, — значит
    /// на машине с шестнадцатью гигабайтами он окажется меньше сам, без единой
    /// настройки.
    pub fn memory_ceiling(&self) -> usize {
        // Ноль порога означает «без предела по объёму» — потолка тогда нет.
        if self.flush_bytes == 0 {
            0
        } else {
            self.flush_bytes.saturating_mul(2)
        }
    }

    /// Перерос ли буфер потолок прямо сейчас.
    ///
    /// Наступить это может только при **занятом** писателе: свободный забирает
    /// буфер по порогу, и до потолка тот не доходит. Потому проверка правила
    /// живёт у [`Self::memory_ceiling`], а проверка поведения — на стенде под
    /// урезанной памятью, где писатель заведомо отстаёт.
    pub fn over_memory_ceiling(&self) -> bool {
        let ceiling = self.memory_ceiling();
        ceiling > 0 && self.buffered_bytes() >= ceiling
    }

    pub fn buffered_bytes(&self) -> usize {
        // Raw pairs, отсортированные offsets/values и encoded output могут
        // одновременно существовать. Резерв не зависит от stored/source.
        (self.buf.bytes.saturating_mul(SLACK) / 100)
            .saturating_add(self.buf.build_reserve)
            .saturating_add(self.buf.delta.bytes())
            .saturating_add(self.inflight_id_hashes.capacity().saturating_mul(8))
            .saturating_add(self.frozen_memory_bytes())
    }

    pub fn buffered_dead(&self) -> u32 {
        self.buf.dead.iter().filter(|&&d| d).count() as u32
    }

    /// Включает фоновую запись сегментов.
    ///
    /// `layout` — замок состава сегментов: тот же, под которым состав переписывает
    /// укрупнение. Внесение свежего сегмента в список обязано идти под ним, иначе
    /// слияние, прочитавшее состав до нас и записавшее после, вычеркнет сегмент,
    /// который в это время появился.
    pub fn background(&mut self, layout: std::sync::Arc<std::sync::Mutex<()>>) {
        self.drain();
        self.layout = std::sync::Arc::clone(&layout);
        if !self.ensure_manifest() {
            return;
        }
        self.flusher = Some(Flusher::new(layout));
    }

    fn ensure_manifest(&mut self) -> bool {
        if self.manifest_ready {
            return true;
        }
        let _layout = self.layout.lock().unwrap_or_else(|error| error.into_inner());
        match crate::manifest::ensure_listed(&self.dir) {
            Ok(()) => {
                self.manifest_ready = true;
                true
            }
            Err(error) => {
                self.poisoned = Some(format!("начальная граница manifest: {error}"));
                false
            }
        }
    }

    /// Ставит общий замок состава, не заводя фонового потока.
    ///
    /// Нужен там, где сброс синхронный, но состав всё равно делится с
    /// укрупнением: внесение в список обязано идти под тем же замком.
    pub fn share_layout(&mut self, layout: std::sync::Arc<std::sync::Mutex<()>>) {
        self.layout = layout;
    }

    /// Записывает накопленное отдельным сегментом.
    ///
    /// При фоновой записи возвращается **до** того, как сегмент лёг на диск.
    /// Дождаться его — [`Indexer::drain`]; она же зовётся сама перед тем, как
    /// отдать следующий буфер.
    pub fn flush(&mut self) {
        if self.buf.docs == 0 {
            return;
        }
        if !self.check_alive() {
            return;
        }
        if !self.ensure_manifest() {
            return;
        }
        // Имя сегмента — часть долговечного состава, поэтому переполнение его
        // номера не может быть «просто следующим нулём». Проверка стоит до
        // перемещения буфера: при отказе все подтверждённые документы остаются
        // и в памяти, и в WAL, а узел объявляет приём нездоровым.
        let Some(next_segment) = self.next_segment.checked_add(1) else {
            self.poisoned = Some(format!(
                "нумерация сегментов исчерпана на seg{}; следующий номер не помещается в u64",
                self.next_segment
            ));
            return;
        };
        // Последний суффикс замораживается до передачи raw buffer. Отказ
        // останавливает приём до изменения владения: ACK остаётся восстановим
        // из WAL, старые ReadView не теряются и checkpoint не продвигается.
        if self.frozen.is_some() {
            if let Err(error) = self.freeze_live() {
                self.poisoned = Some(format!("frozen publication перед flush: {error}"));
                return;
            }
        }
        let mine_frozen = self.frozen.as_mut().map(|state| {
            state.inflight_recorded_superseded = state.recorded_superseded;
            state.recorded_superseded = 0;
            let mine = std::mem::take(&mut state.active);
            state.inflight = mine.clone();
            mine
        });
        self.inflight_docs = self.buf.docs;
        // Список отложенных гашений забирается у буфера здесь — вместе с самим
        // буфером, — но в «отданное на запись» кладётся ниже, и не раньше, чем
        // предыдущее отданное будет забрано.
        //
        // Порядок здесь не косметический, и стоила его перестановка дорого.
        // Пока присваивание стояло на этой строке, сброс, уходящий поверх ещё
        // летящего, **затирал** чужой список: прежние версии его документов не
        // гасились никогда, и у идентификатора навсегда оставались две живые
        // версии. Поймано стендом под смешанной нагрузкой; на спокойном узле,
        // где сброс всегда успевает лечь, не воспроизводится вовсе.
        let superseded = std::mem::take(&mut self.superseded);
        // Живой сегмент отдаваемого буфера собирается **до** передачи и из него
        // же: иначе всё время записи его документы невидимы никому.
        //
        // Отказ сборки не отменяет сброса: это потеря свежести на время записи,
        // а не потеря данных. Молчать о нём всё же нельзя — он вернётся
        // вызывающему признаком через `poisoned`, только если сломалась запись,
        // а здесь достаточно оставить `None`.
        let sc = self.schema();
        // Двойник и число летящих запоминаются отдельно: ожидание предыдущего
        // сброса ниже снимет их вместе с чужими, и своё придётся вернуть.
        let mine_docs = self.buf.docs;
        // Двойник собирается только пока буфер обещан поиску.
        //
        // Состав решает про **текущий** буфер по тому же пределу, и на крупном
        // буфере отвечает «не собирать»: видимость такого буфера возвращается к
        // сбросу на диск. Двойник же собирался безусловно — то есть закрывал
        // окно, которое политика уже объявила открытым, и стоил при этом
        // полного повторного разбора всех документов буфера под замком приёма.
        // На буфере в миллион документов при пределе в десять тысяч это
        // делалось всегда и всегда впустую.
        //
        // Гарантии не страдают: без двойника список отложенных гашений не
        // применяется здесь, а переезжает в «легло» и применяется после
        // посадки сегмента, поэтому окна «ни одной живой версии» не возникает.
        self.inflight_live = if self.frozen.is_some() {
            None
        } else if self.buf.docs <= self.live_max_docs {
            self.twins_built += 1;
            match write_segment(Target::Memory, self.seq, &sc, &self.buf) {
                Ok(built) => built.pack.and_then(|pack| {
                    let src = std::sync::Arc::new(pack.source(INFLIGHT_SEGMENT));
                    crate::index::open_memory(src).ok().map(std::sync::Arc::new)
                }),
                Err(_) => None,
            }
        } else {
            self.twins_skipped += 1;
            None
        };
        let mine_live = self.inflight_live.clone();
        let job = Job {
            // На место отданного встаёт запасённый, если он есть: у него уже
            // есть ёмкости прошлого цикла, и лестницу удвоений отращивать
            // заново не приходится.
            buf: {
                let fresh = match self.spare.take() {
                    Some(kept) => kept,
                    None => {
                        self.buffers_made += 1;
                        Buffer::new(self.fields.len())
                    }
                };
                std::mem::replace(&mut self.buf, fresh)
            },
            sc,
            root: self.dir.clone(),
            segment: self.next_segment,
            seq: self.seq,
            began: std::time::Instant::now(),
        };
        self.next_segment = next_segment;
        // Признак «значения печатаются обратно» относится к **сегменту**, а не
        // к жизни индексатора. Без сброса одно значение `007` в первом сегменте
        // заставляло бы хранить копию во всех последующих — не ошибка, но
        // лишний десяток мегабайт на ровном месте.
        self.exact.iter_mut().for_each(|e| *e = true);

        let Some(f) = self.flusher.as_ref() else {
            // Своего потока нет — писать некому, значит и в полёте никого:
            // список кладётся сразу, `take_back` ниже его и заберёт.
            self.inflight_superseded = superseded;
            // Пишем здесь же, тем же кодом и с тем же отношением к отказу.
            let outcome = write_segment(
                Target::Disk { root: &job.root, segment: job.segment },
                job.seq,
                &job.sc,
                &job.buf,
            )
            .and_then(|w| {
                let name = format!("seg{:04}", job.segment);
                let _guard = self.layout.lock().unwrap_or_else(|e| e.into_inner());
                crate::manifest::append(&job.root, &name).map_err(|e| {
                    std::io::Error::other(format!(
                        "{}/{}: список сегментов не обновился: {e}",
                        job.root,
                        crate::manifest::FILE
                    ))
                })?;
                Ok(w)
            });
            let mut buf = job.buf;
            buf.clear();
            let dir = format!("{}/seg{:04}", job.root, job.segment);
            self.take_back(Back {
                buf,
                dir,
                outcome: match outcome {
                    Ok(w) => Outcome::Done {
                        postings: w.postings,
                        phases: w.phases,
                        elapsed_ms: job.began.elapsed().as_secs_f64() * 1000.0,
                        seq: job.seq,
                    },
                    Err(e) => Outcome::Failed(format!("{e}")),
                },
            });
            return;
        };
        // Место под задание освобождается забором предыдущего: в полёте всегда
        // не больше одного, значит живых буферов не больше двух.
        if f.inflight {
            self.collect();
            // Забор мог узнать об отказе. Отдать следующий сегмент после
            // упавшего — значит оставить дыру в середине пространства номеров:
            // seg0004 в списке, seg0003 нет, и номера всех следующих документов
            // уехали. Проверка обязана стоять **между** забором и передачей.
            if !self.check_alive() {
                return;
            }
            // Забор чужого сбросил **и своё**: `take_back` снимает живой
            // двойник и число летящих документов, не различая, чьи они.
            //
            // Двойник этого сброса собран выше, до ожидания, — иначе собирать
            // было бы уже не из чего, буфер отдан писателю. А `take_back`
            // предыдущего сброса тут же его обнулял, и под плотной заливкой
            // двойник умирал сразу после рождения: документы отданного буфера
            // становились невидимы никому на всё время записи сегмента — из
            // текущего буфера их забрали, на диск ещё не положили, прежние
            // версии погашены. Отсюда и «поиск не нашёл», и точечное чтение,
            // отдающее прошлую редакцию: 0.2% на стенде под смешанной
            // нагрузкой, и ноль на спокойном узле, где ожидание не нужно.
            //
            // Восстанавливаем ровно своё и ровно здесь: раньше нечего, позже
            // поздно — ниже задание уже уходит писателю.
            self.inflight_live = mine_live;
            if let (Some(state), Some(mine)) = (&mut self.frozen, mine_frozen) {
                state.inflight = mine;
            }
            self.inflight_docs = mine_docs;
        }
        // Теперь предыдущее отданное точно забрано (`collect` перенёс его
        // список в «легло»), и место под свой список свободно.
        //
        // Отдать его раньше значило бы затереть чужой; отдать позже —
        // приписать этому сегменту гашения, которых он не несёт, и погасить
        // прежние версии до того, как их замена стала видимой. Ровно здесь и
        // ровно один раз.
        self.inflight_superseded = superseded;
        self.inflight_id_hashes.clear();
        self.inflight_id_hashes.extend(job.buf.ids.iter().map(|id| crate::bloom::hash(id)));
        self.inflight_id_hashes.sort_unstable();
        self.inflight_id_hashes.dedup();
        let f = self.flusher.as_mut().expect("писатель на месте");
        if f.hand.send(job).is_err() {
            self.poisoned = Some("поток фоновой записи сегмента умер".into());
        } else {
            f.inflight = true;
        }
    }

    /// Записывает накопленное и дожидается, пока оно ляжет на диск.
    pub fn flush_now(&mut self) {
        self.flush();
        self.drain();
    }

    /// Забирает результат отданного сброса. Ждёт, если он ещё пишется.
    fn collect(&mut self) {
        let Some(f) = self.flusher.as_mut() else { return };
        if !f.inflight {
            return;
        }
        match f.back.recv() {
            Ok(done) => {
                f.inflight = false;
                self.take_back(done);
            }
            Err(_) => {
                // Канал закрыт — значит поток запаниковал. Молчать нельзя:
                // приём продолжал бы отвечать «принято» на документы, которых
                // никто не записывает.
                f.inflight = false;
                self.poisoned = Some("фоновая запись сегмента прервалась: поток не ответил".into());
            }
        }
    }

    /// Принимает итог записанного сегмента обратно в состояние приёма.
    fn take_back(&mut self, done: Back) {
        self.inflight_id_hashes.clear();
        self.inflight_docs = 0;
        let inflight_frozen = self
            .frozen
            .as_mut()
            .map(|state| std::mem::take(&mut state.inflight))
            .unwrap_or_default();
        match done.outcome {
            Outcome::Done { postings, phases, elapsed_ms, seq } => {
                self.total_postings += postings;
                for (n, v) in phases {
                    tick(&mut self.phases, n, v);
                }
                self.flushed_seq = seq;
                self.landed += 1;
                self.flush_ms.push(elapsed_ms);
                // Сегмент лёг. Гасить прежние версии всё ещё рано — он не в
                // составе; список переходит тому, кто его туда внесёт, вместе с
                // именем сегмента: без него неизвестно, в чью пользу гасить.
                let mut all_ids = std::mem::take(&mut self.inflight_superseded);
                for generation in &inflight_frozen {
                    all_ids.extend(generation.superseded.iter().cloned());
                }
                if !all_ids.is_empty() {
                    self.landed_superseded.push((done.dir.clone(), all_ids));
                }
                // Сегмент лёг — живой двойник больше не нужен: его содержимое
                // теперь на диске, и держать оба значило бы показать каждый
                // документ дважды.
                self.inflight_live = None;
                if let Some(state) = &mut self.frozen {
                    state.recorded_superseded = 0;
                    state.inflight_recorded_superseded = 0;
                }
            }
            // Отметка журнала **не** двигается: сегмента на диске нет, и
            // объявить его документы долговечными значило бы потерять их при
            // следующем подъёме — журнал бы их уже не переиграл.
            Outcome::Failed(why) => {
                // Сегмент не лёг, приём останавливается. Живой двойник снимается
                // тоже: показывать документы сегмента, которого нет и не будет,
                // значит обещать то, чего не переживёт перезапуск.
                self.inflight_live = None;
                // Возвращаем старый список supersede перед новыми ID, которые
                // могли накопиться в fresh active buffer во время записи.
                let newer = std::mem::take(&mut self.superseded);
                let mut older = std::mem::take(&mut self.inflight_superseded);
                older.extend(newer);
                self.superseded = older;
                if let Some(state) = &mut self.frozen {
                    let mut restored = inflight_frozen;
                    restored.append(&mut state.active);
                    state.active = restored;
                    state.recorded_superseded = state.inflight_recorded_superseded;
                    state.inflight_recorded_superseded = 0;
                }
                if self.poisoned.is_none() {
                    self.poisoned = Some(why);
                }
            }
        }
        // Буфер возвращается с прижившимися ёмкостями — берём его себе, а
        // свежий, заведённый при передаче, выбрасываем.
        if done.buf.vals.len() == self.buf.vals.len() {
            if self.buf.docs == 0 {
                // Текущий пуст — берём возвращённый, у него ёмкости прошлого
                // цикла. Пустой при этом не выбрасывается, а идёт в запас:
                // прежде выбрасывался именно он, и следующая передача заводила
                // ещё один свежий.
                let empty = std::mem::replace(&mut self.buf, done.buf);
                self.spare = Some(empty);
            } else {
                // Текущий уже набирается — переливать в него ёмкость нечем.
                // Кладём возвращённый в запас: его возьмёт ближайший сброс.
                self.spare = Some(done.buf);
            }
        }
    }

    /// Забирает результат, если запись уже кончилась. Не ждёт.
    pub fn poll(&mut self) {
        let Some(f) = self.flusher.as_mut() else { return };
        if !f.inflight {
            return;
        }
        match f.back.try_recv() {
            Ok(done) => {
                f.inflight = false;
                self.take_back(done);
            }
            Err(std::sync::mpsc::TryRecvError::Empty) => {}
            Err(std::sync::mpsc::TryRecvError::Disconnected) => {
                f.inflight = false;
                self.poisoned = Some("фоновая запись сегмента прервалась: поток не ответил".into());
            }
        }
    }

    /// Дожидается, пока всё отданное на запись ляжет на диск.
    pub fn drain(&mut self) {
        self.collect();
    }

    /// Чем отравлен приём. `None` — всё в порядке.
    ///
    /// Отказ фоновой записи, о котором знает только фоновый поток, — это приём,
    /// отвечающий «принято» в пустоту. Прежде здесь была паника: громко и
    /// сразу, но при `panic = "abort"` громкость означает смерть узла со всеми
    /// соединениями, хотя виноват один сегмент.
    ///
    /// Признак липкий и не снимается: отказ записи не «проходит». Узел обязан
    /// быть перезапущен, и тогда переигрывание журнала само расскажет, что
    /// уцелело, — тот же порядок, что у `Writer::poisoned` на стороне сервера.
    pub fn poisoned(&self) -> Option<&str> {
        self.poisoned.as_deref()
    }

    /// Сброс на отравленном приёме не делается: писать нечем.
    fn check_alive(&self) -> bool {
        self.poisoned.is_none()
    }

    /// Всё, что писателю сегмента нужно знать сверх самого буфера.
    fn schema(&self) -> Schema {
        Schema {
            fields: self.fields.clone(),
            // Считаются здесь, а не в конструкторе: `set_fids` зовут **после**
            // него, и основа поля с точкой зависит от устойчивого номера.
            stems: self
                .fields
                .iter()
                .enumerate()
                .map(|(i, path)| {
                    crate::schema::stem_of(path, self.fids.get(i).copied().unwrap_or(i as u32))
                })
                .collect(),
            fids: self.fids.clone(),
            groups: self.groups.clone(),
            group_paths: self.group_paths.clone(),
            boosts: self.boosts.clone(),
            kinds: self.kinds.clone(),
            stored: self.stored.clone(),
            searched: self.searched.clone(),
            positioned: self.positioned.clone(),
            exact: self.exact.clone(),
            posmin: self.posmin,
        }
    }

    /// Сколько сегментов **дописано** и внесено в список.
    ///
    /// Не сколько отдано на запись. По этому числу решают, стал ли виден новый
    /// сегмент, и назвать видимым тот, что ещё пишется, значило бы перечитать
    /// состав впустую — а гашению отдать список, где документа ещё нет.
    pub fn segments(&self) -> usize {
        self.landed
    }

    /// Сколько документов лежит в буфере и ещё не видно поиску.
    pub fn buffered(&self) -> u32 {
        self.buf.docs + self.inflight_docs
    }

    /// Собирает нынешний буфер в живой сегмент, **не забирая** его.
    ///
    /// ## Почему буфер не забирается
    ///
    /// Очевидный способ сделать приём видимым — запечатывать буфер на каждом
    /// refresh: получился бы сегмент, буфер начинался бы заново. Тогда за минуту
    /// работы у узла набирается шестьдесят сегментов, каждый из которых надо
    /// потом слить и записать, — то есть тот самый шторм мелких сегментов,
    /// против которого в 0.2 заводились `refresh_min_docs` и профиль
    /// `update_heavy`, только теперь ещё и в памяти.
    ///
    /// Здесь буфер остаётся на месте и копится до обычного сброса на диск, а
    /// живой сегмент **пересобирается целиком** и подменяет предыдущий. Живой
    /// сегмент всегда один, состав не растёт, слияние живых не нужно вовсе, а
    /// путь записи на диск остаётся ровно тем же, каким был.
    ///
    /// ## Чего это стоит
    ///
    /// Пересборка стоит размера буфера на каждый refresh. Для control plane это
    /// копейки: между сбросами там лежат десятки документов. Для массовой
    /// загрузки это разорительно — миллион документов, пересобираемый раз в
    /// секунду, — и потому вызывающий обязан спрашивать размер буфера прежде,
    /// чем звать сюда. Границу держит он, а не эта функция: она не знает ни
    /// настроек, ни того, зачем её позвали.
    ///
    /// `None` — в буфере нечего показывать.
    pub fn build_live(
        &self,
        name: &str,
    ) -> std::io::Result<Option<std::sync::Arc<crate::index::Index>>> {
        if self.buf.docs == 0 {
            return Ok(None);
        }
        let built = write_segment(Target::Memory, self.seq, &self.schema(), &self.buf)?;
        let pack =
            built.pack.ok_or_else(|| std::io::Error::other("живой сегмент собрался без кусков"))?;
        let src = std::sync::Arc::new(pack.source(name));
        Ok(Some(std::sync::Arc::new(crate::index::open_memory(src)?)))
    }

    /// Публикует только новые документы raw buffer. Владение прежними views,
    /// supersede и передача flusher остаются обязанностью вызывающего runtime.
    /// Имя должно быть уникально среди одновременно удерживаемых memory views.
    /// При отказе encode/open граница и touched keys не расходуются.
    pub fn build_live_delta(
        &mut self,
        name: &str,
    ) -> std::io::Result<Option<std::sync::Arc<crate::index::Index>>> {
        if self.buf.delta.epoch == 0 {
            self.buf.delta.epoch = 1;
            let Buffer { lists, delta, .. } = &mut self.buf;
            for (key, postings) in lists {
                delta.touch(key, postings);
            }
        }
        if self.buf.delta.published_docs == self.buf.docs {
            return Ok(None);
        }
        let next = self
            .buf
            .delta
            .epoch
            .checked_add(1)
            .ok_or_else(|| std::io::Error::other("исчерпана эпоха delta publication"))?;
        let (delta, units) = self.buf.copy_delta(&self.groups, self.group_paths.len())?;
        let built = write_segment(Target::Memory, self.seq, &self.schema(), &delta)?;
        let pack =
            built.pack.ok_or_else(|| std::io::Error::other("delta построена без memory source"))?;
        let source = std::sync::Arc::new(pack.source(name));
        let view = std::sync::Arc::new(crate::index::open_memory(source)?);
        self.buf.delta.published_docs = self.buf.docs;
        self.buf.delta.published_units = units;
        self.buf.delta.keys.clear();
        self.buf.delta.key_bytes = 0;
        self.buf.delta.epoch = next;
        Ok(Some(view))
    }

    /// Включается runtime до приёма документов. Резерв под raw buffer,
    /// encoded generations и пик coalescing должен быть получен вызывающим.
    /// Старый single-view API после включения не описывает весь live состав.
    pub fn enable_frozen_memtables(&mut self, max_generations: usize) -> std::io::Result<()> {
        if !(1..=32).contains(&max_generations) {
            return Err(std::io::Error::other("предел frozen generations должен быть от 1 до 32"));
        }
        if self.flush_inflight() || self.frozen.is_some() {
            return Err(std::io::Error::other(
                "frozen lifecycle включается только на пустом приёмнике",
            ));
        }
        self.frozen = Some(FrozenMemtables {
            active: Vec::new(),
            inflight: Vec::new(),
            inflight_recorded_superseded: 0,
            recorded_superseded: 0,
            max_generations,
        });
        Ok(())
    }

    /// Публикует delta либо коалесцирует retained buffer при достижении
    /// предела поколений. Не пишет disk segment и не двигает WAL checkpoint.
    /// При любой ошибке прежние views и границы остаются пригодны к повтору.
    pub fn freeze_live(&mut self) -> std::io::Result<()> {
        let frozen = self
            .frozen
            .as_ref()
            .ok_or_else(|| std::io::Error::other("frozen lifecycle не включён"))?;
        if self.buf.delta.published_docs == self.buf.docs {
            return Ok(());
        }
        let coalesce = frozen.active.len() >= frozen.max_generations;
        let recorded = if coalesce { 0 } else { frozen.recorded_superseded };
        let number = NEXT_FROZEN
            .fetch_update(
                std::sync::atomic::Ordering::Relaxed,
                std::sync::atomic::Ordering::Relaxed,
                |n| n.checked_add(1),
            )
            .map_err(|_| std::io::Error::other("исчерпана identity frozen generation"))?;
        let name = format!("@svindb-frozen-{number}");
        // Fallible границы проверяются до успешной сборки и расходования delta.
        let superseded: std::sync::Arc<[String]> = self
            .superseded
            .get(recorded..)
            .ok_or_else(|| std::io::Error::other("граница supersede выходит за active buffer"))?
            .into();
        let next_epoch = self
            .buf
            .delta
            .epoch
            .checked_add(1)
            .ok_or_else(|| std::io::Error::other("исчерпана эпоха frozen coalescing"))?;
        let built = if coalesce { self.build_live(&name)? } else { self.build_live_delta(&name)? };
        let index = built.ok_or_else(|| std::io::Error::other("непустая delta не построена"))?;
        if coalesce {
            self.buf.delta.published_docs = self.buf.docs;
            self.buf.delta.published_units =
                index.slots.iter().map(|slots| slots.units()).collect();
            self.buf.delta.keys.clear();
            self.buf.delta.key_bytes = 0;
            self.buf.delta.epoch = next_epoch;
        }
        let frozen = self.frozen.as_mut().expect("владение lifecycle не менялось");
        if coalesce {
            frozen.active.clear();
        }
        frozen.active.push(FrozenGeneration { index, superseded });
        frozen.recorded_superseded = self.superseded.len();
        Ok(())
    }

    /// Согласованный порядок для публикации: летящие поколения, затем active.
    /// Клонируются только Arc, не payload и не списки document IDs.
    pub fn frozen_generations(&self) -> Vec<FrozenGeneration> {
        self.frozen
            .as_ref()
            .map(|state| state.inflight.iter().chain(&state.active).cloned().collect())
            .unwrap_or_default()
    }

    /// Включён ли новый lifecycle. Отдельный признак нужен серверу, чтобы не
    /// смешать старый live-twin API с несколькими frozen generations.
    pub fn frozen_memtables_enabled(&self) -> bool {
        self.frozen.is_some()
    }

    /// Полезные байты всех active/inflight memory generations. Это нижняя
    /// граница anonymous ownership: reader tables, Arc-объекты и allocator
    /// slack учитываются отдельным admission-счётчиком, а не выдаются за disk
    /// bytes.
    pub fn frozen_memory_bytes(&self) -> usize {
        self.frozen_generations()
            .iter()
            .map(|generation| generation.index.memory_source_bytes())
            .sum()
    }

    pub fn frozen_generation_count(&self) -> usize {
        self.frozen.as_ref().map_or(0, |state| state.active.len() + state.inflight.len())
    }

    /// Идентификаторы, чьи прежние версии пора погасить, — не забирая список.
    ///
    /// Живой сегмент публикуется много раз подряд из одного и того же буфера, и
    /// список нужен на каждой публикации: гасить прежние версии надо всякий раз,
    /// когда новая появляется в составе. Забери его первая публикация — и
    /// замены, пришедшие до неё, остались бы непогашенными до самого сброса.
    ///
    /// Повторное применение безвредно: [`crate::maintain::supersede_in`] гасит
    /// всё, кроме новейшей версии, и на уже прибранном составе не делает ничего.
    pub fn superseded_now(&self) -> &[String] {
        &self.superseded
    }

    /// Живой сегмент буфера, отданного писателю. `None` — в полёте ничего нет.
    pub fn inflight_live(&self) -> Option<std::sync::Arc<crate::index::Index>> {
        self.inflight_live.clone()
    }

    /// Его же список отложенных гашений: гасить в его пользу можно, как только
    /// он попал в состав, — версия там живая и видимая.
    pub fn inflight_superseded_now(&self) -> &[String] {
        &self.inflight_superseded
    }

    /// Документы именно в набираемом буфере, без уже отданного писателю.
    pub fn active_buffered(&self) -> u32 {
        self.buf.docs
    }

    /// Пишется ли сейчас ранее отданный сегмент.
    pub fn flush_inflight(&self) -> bool {
        self.flusher.as_ref().is_some_and(|f| f.inflight)
    }

    /// Забирает длительности завершённых публикаций ровно один раз.
    pub fn take_flush_ms(&mut self) -> Vec<f64> {
        std::mem::take(&mut self.flush_ms)
    }

    /// При скольких документах буфер сбрасывается сегментом.
    pub fn per_segment(&self) -> u32 {
        self.per_segment
    }

    /// Имена полей в том порядке, в каком [`Indexer::add`] ждёт значения.
    ///
    /// Нужно приёму по сети: тело запроса — объект с именами, а `add` берёт
    /// массив по позиции, и перевод между ними обязан идти по **этой** схеме, а
    /// не по чьему-либо представлению о ней.
    pub fn field_names(&self) -> &[String] {
        &self.fields
    }

    /// Хранится ли поле так, что его можно сравнить в conditional put.
    pub fn field_stored(&self, field: usize) -> bool {
        self.stored.get(field).copied().unwrap_or(false)
    }

    /// Объявляет, по каким полям искать. Короче объявления — остальные ищутся.
    ///
    /// Отдельным вызовом, а не ещё одним доводом конструктора: конструкторов
    /// пять, и шестой довод в каждом означал бы пять мест, где его можно
    /// перепутать местами с соседним `bool`.
    /// Какие поля идут в словарь. Нужно тому, кто разбирает слова заранее.
    pub fn searched_flags(&self) -> &[bool] {
        &self.searched
    }

    pub fn set_searched(&mut self, searched: Vec<bool>) {
        for (i, on) in searched.iter().enumerate().take(self.searched.len()) {
            self.searched[i] = *on;
            // Не ищется — значит и позиций не обещает: проверка целостности
            // сверяет обещание заголовка с содержимым и объявила бы здоровый
            // сегмент сломанным, не найдя блока позиций.
            if !*on {
                self.positioned[i] = false;
            }
        }
    }

    /// Виды полей в том же порядке, что и [`Indexer::field_names`].
    ///
    /// Нужно приёму, чтобы сказать в ответе, что именно не прочлось: без вида
    /// «не число в числовом поле» неотличимо от «поля не прислали».
    /// Номер группы каждого поля. Пусто — все поля корневые.
    pub fn field_groups(&self) -> &[u32] {
        &self.groups
    }

    /// Путь массива по номеру группы. Пусто — групп нет.
    pub fn group_paths(&self) -> &[String] {
        &self.group_paths
    }

    pub fn field_kinds(&self) -> &[Kind] {
        &self.kinds
    }

    /// Меняет потолок документов на сегмент.
    ///
    /// Применяется **со следующего сегмента**, а не к набранному: уже лежащее в
    /// буфере останется в нём до сброса. Иначе снижение потолка посреди набора
    /// пришлось бы либо выбрасывать, либо соврать про размер сегмента — а размер
    /// записан в заголовке и по нему считается нормировка.
    ///
    /// Ноль отвергается: буфер с нулевым потолком не сбросится никогда.
    pub fn set_per_segment(&mut self, n: u32) {
        if n > 0 {
            self.per_segment = n;
        }
    }
}

/// Пишет файл сегмента и **доводит его до диска**.
///
/// `write_all` возвращается, когда байты приняты ядром, а не когда легли на
/// носитель. Без `sync_all` при потере питания возможен сегмент, на который
/// заголовок уже ссылается, а содержимого нет — и это тем опаснее, что журнал к
/// тому моменту уже обрезан по отметке.
fn write(dir: &str, name: &str, bytes: &[u8]) -> std::io::Result<()> {
    // Отказ, а не паника. Диск кончается, права меняются, носитель отваливается —
    // всё это обычные события, а не невозможные. Сборка выпуска идёт с
    // `panic = "abort"`: паника здесь убила бы **весь узел** вместе со всеми
    // соединениями, хотя виноват один сегмент, и приём мог бы просто
    // остановиться, сказав почему. Слияние так и делает — см. `merge::write`.
    let name_of = |e: std::io::Error| std::io::Error::new(e.kind(), format!("{dir}/{name}: {e}"));
    let mut f = File::create(format!("{dir}/{name}")).map_err(name_of)?;
    f.write_all(bytes).map_err(name_of)?;
    f.sync_all()
        .map_err(|e| std::io::Error::new(e.kind(), format!("{dir}/{name}: сброс на диск: {e}")))
}

/// Доводит до диска сам каталог: без этого имя нового файла может не пережить
/// потерю питания, даже когда его содержимое пережило.
fn sync_dir(dir: &str) {
    if let Ok(d) = File::open(dir) {
        let _ = d.sync_all();
    }
}

#[cfg(test)]
mod replace_tests {
    use super::*;
    use crate::index;

    fn dir(name: &str) -> String {
        // Каталог с номером процесса: два прогона тестов разом не должны
        // растаптывать друг другу файлы.
        let d = std::env::temp_dir().join(format!("svindb-replace-{name}-{}", std::process::id()));
        std::fs::remove_dir_all(&d).ok();
        d.to_string_lossy().to_string()
    }

    fn indexer(path: &str) -> Indexer {
        Indexer::new(path, vec!["title".into(), "body".into()], vec![2.0, 1.0], 1000)
    }

    /// Сегмент, собранный в память, состоит из тех же кусков, что и легший на
    /// диск из **того же** буфера.
    ///
    /// Сверяется не «собралось», а побайтовое совпадение каждого куска. Ради
    /// этого развилка приёмника и стоит там, где стоит: разойдись сборка на два
    /// пути, второй начал бы укладывать словарь или постинги иначе, читатель
    /// разбирал бы их прежним кодом — и отвечал бы неправдой на те же данные.
    /// Одно «работает» такого не ловит: неправильно уложенный сегмент тоже
    /// открывается.
    #[test]
    fn a_segment_built_in_memory_matches_the_one_written_to_disk() {
        let path = dir("память-против-диска");
        let mut ix = indexer(&path);
        for n in 0..64 {
            ix.add(&format!("док-{n:03}"), &["пёс кот сосед", "тело документа про поиск"]);
        }
        // Одна погашенная версия: карта живых обязана совпасть тоже, а не
        // сойтись случайно на «живы все».
        ix.replace("док-007", &["пёс", "замена"]);
        assert!(ix.buf.docs > 0, "буфер пуст — сверять было бы нечего");
        let sc = ix.schema();

        std::fs::create_dir_all(&path).expect("каталог");
        let landed = write_segment(Target::Disk { root: &path, segment: 0 }, 7, &sc, &ix.buf)
            .expect("сегмент на диск");
        assert!(landed.pack.is_none(), "у легшего на диск не бывает кусков в памяти");

        let built = write_segment(Target::Memory, 7, &sc, &ix.buf).expect("сегмент в память");
        let pack = built.pack.expect("куски собраны");
        assert!(pack.bytes() > 0, "в памяти не оказалось ни байта");

        // Куски контейнера — один в один.
        let seg = format!("{path}/seg0000");
        let head = crate::index::read_head(&seg).expect("заголовок");
        let disk = crate::container::SegmentSource::of(&seg, head.container).expect("открытие");
        let mut checked = 0usize;
        for (name, want) in pack.parts() {
            // Заголовок и карта живых у легшего лежат файлами рядом с
            // контейнером, а не в нём: их сверяем отдельно, ниже.
            if name == "head.tsv" || name == crate::live::FILE {
                continue;
            }
            let there =
                disk.open(name).unwrap_or_else(|e| panic!("куска {name} нет на диске: {e}"));
            assert_eq!(
                there.slice(0, there.len_bytes()),
                &want[..],
                "кусок {name} собрался в память и на диск по-разному"
            );
            checked += 1;
        }
        // Порог близко к настоящему числу: он ловит не «сегмент пуст», а
        // «кусков стало меньше» — то есть молча переставшую собираться часть
        // сегмента. Сверено бывает девятнадцать при схеме из двух полей.
        assert!(checked >= 17, "сверено всего {checked} кусков — сегмент вышел не тот");

        // Карта живых совпадает: погашенная версия обязана быть погашенной и там.
        let from_disk = std::fs::read(format!("{seg}/{}", crate::live::FILE)).expect("карта");
        assert_eq!(
            pack.parts().get(crate::live::FILE).expect("карта в памяти"),
            &from_disk,
            "карта живых разошлась"
        );

        // Заголовок совпадает во всём, кроме обещания про контейнер: файла под
        // сегментом в памяти нет, и строки про него быть не должно.
        let head_disk = std::fs::read_to_string(format!("{seg}/head.tsv")).expect("заголовок");
        let head_mem =
            String::from_utf8(pack.parts().get("head.tsv").expect("заголовок в памяти").clone())
                .expect("текст");
        assert!(
            head_disk.starts_with("container\t"),
            "у легшего пропала строка контейнера:\n{head_disk}"
        );
        assert!(
            !head_mem.contains("container\t"),
            "заголовок в памяти обещает контейнер, которого нет:\n{head_mem}"
        );
        let tail: String = head_disk.lines().skip(1).map(|l| format!("{l}\n")).collect();
        assert_eq!(head_mem, tail, "заголовки разошлись не только контейнером");

        // Источник поверх собранного отвечает теми же кусками.
        let memory = pack.source("память/seg0000");
        let a = memory.open("postings.bin").expect("постинги из памяти");
        let b = disk.open("postings.bin").expect("постинги с диска");
        assert_eq!(a.slice(0, a.len_bytes()), b.slice(0, b.len_bytes()), "постинги разошлись");

        std::fs::remove_dir_all(&path).ok();
    }

    /// Сегмент, собранный в память, открывается как обычный и отвечает на поиск
    /// тем же, чем он же с диска.
    ///
    /// Сверяются не «нашлось что-то», а номера, идентификаторы и веса — веса
    /// побитово. Сегмент, уложенный чуть иначе, тоже открывается и тоже что-то
    /// находит; расходится он в порядке и весах, и заметить это можно только
    /// сравнив их с эталоном.
    #[test]
    fn a_segment_in_memory_searches_exactly_like_one_on_disk() {
        let path = dir("поиск-в-памяти");
        let mut ix = indexer(&path);
        for n in 0..80 {
            ix.add(
                &format!("док-{n:03}"),
                &["общее слово", &format!("тело номер {n} про поиск и индекс")],
            );
        }
        // Погашенная версия: карта живых обязана работать и в памяти, иначе
        // удалённое воскресло бы — молча и только у живого сегмента.
        ix.kill_buffered("док-005");
        let sc = ix.schema();

        std::fs::create_dir_all(&path).expect("каталог");
        write_segment(Target::Disk { root: &path, segment: 0 }, 3, &sc, &ix.buf)
            .expect("сегмент на диск");
        let built = write_segment(Target::Memory, 3, &sc, &ix.buf).expect("сегмент в память");
        let pack = built.pack.expect("куски собраны");

        let answers = |ix: &crate::index::Index| -> Vec<(u32, String, u64)> {
            let list = ix.dict.lookup(0, "общее").expect("слово есть");
            let req = crate::search::Request {
                mode: crate::search::MatchMode::AnyTerm,
                skipped: false,
                live: None,
                words: vec![crate::search::QueryWord::new(0, vec![list])],
                k: 100,
                filter: Vec::new(),
                must: Vec::new(),
                must_not: Vec::new(),
                tree: Default::default(),
                sort: Vec::new(),
                floor_key: crate::search::KeyFloor::None,
                doc_base: 0,
                budget: None,
                guard: None,
                score: Vec::new(),
                after: None,
            };
            let (hits, _) = crate::search::search(ix, &req, 0.0);
            let ids = crate::ids::Ids::open(&ix.src, ix.docs);
            hits.into_iter()
                .map(|h| (h.doc, ids.get(h.doc as usize).unwrap_or_default(), h.score.to_bits()))
                .collect()
        };

        let landed = crate::index::load(&format!("{path}/seg0000")).expect("сегмент с диска");
        let source = std::sync::Arc::new(pack.source("память/seg0000"));
        let memory = crate::index::open_memory(source).expect("сегмент из памяти");

        assert_eq!(memory.docs, landed.docs, "число документов разошлось");
        assert_eq!(memory.dead(), landed.dead(), "число погашенных разошлось");
        assert!(memory.dead() > 0, "гашение не доехало — карта живых не проверена");

        let want = answers(&landed);
        assert!(want.len() >= 70, "эталон нашёл {} — сверять почти нечего", want.len());
        assert_eq!(answers(&memory), want, "выдача из памяти разошлась с выдачей с диска");
        assert!(
            !want.iter().any(|(_, id, _)| id == "док-005"),
            "погашенный документ остался в выдаче"
        );

        // Гашение правит карту и у сегмента в памяти: право на правку у неё то
        // же, что у разделяемого отображения.
        let before = memory.dead();
        assert!(memory.live.as_ref().expect("карта").kill(9), "живой документ не погасился");
        assert_eq!(memory.dead(), before + 1, "гашение в памяти не удержалось");

        // Сегмент в памяти не претендует ни на место на диске, ни на опознание
        // заголовка: перечитывать его неоткуда.
        assert_eq!(memory.bytes.total, 0, "сегмент в памяти объявил занятое место");
        assert_eq!(memory.head_id, (0, 0), "у сегмента в памяти взялось опознание файла");

        std::fs::remove_dir_all(&path).ok();
    }

    /// Состав держит сегмент без каталога наравне с прочими и не теряет его на
    /// перечитывании.
    ///
    /// Перечитывание идёт по списку сегментов на диске, а живого в этом списке
    /// нет и быть не может. Забудь его там — и всё принятое после последнего
    /// сброса исчезло бы из выдачи молча и целиком.
    #[test]
    fn the_set_keeps_a_segment_that_has_no_directory() {
        let path = dir("состав-с-живым");
        let mut ix = indexer(&path);
        for n in 0..40 {
            ix.add(&format!("старый-{n:03}"), &["общее слово", "первая пачка"]);
        }
        ix.flush_now();
        assert!(crate::maintain::refresh_catalog(&path), "ID directory не собрался");
        let landed = crate::segments::Segments::load(&path).expect("состав");
        assert_eq!(landed.list.len(), 1, "первая пачка не легла сегментом");
        let point = |segs: &crate::segments::Segments, id: &str| {
            let places = segs.locate_ids(&[id.to_string()]).expect("ID directory открылся");
            assert_eq!(places.len(), 1);
            assert!(!places[0].is_empty(), "{id} не найден через ID directory");
        };
        let _ = crate::stats::take();
        point(&landed, "старый-007");

        // Вторая пачка собирается в память и в список сегментов не попадает.
        for n in 0..25 {
            ix.add(&format!("живой-{n:03}"), &["общее слово", "вторая пачка"]);
        }
        let sc = ix.schema();
        let built = write_segment(Target::Memory, 9, &sc, &ix.buf).expect("сегмент в память");
        let source = std::sync::Arc::new(built.pack.expect("куски").source("память/живой-0"));
        let live = std::sync::Arc::new(crate::index::open_memory(source).expect("открытие"));
        // Публикация забирает буфер себе — как это делает и сброс на диск.
        // Иначе те же документы уехали бы вторым путём и посчитались дважды.
        ix.buf.clear();

        let both = landed.with_live(std::sync::Arc::clone(&live)).expect("состав с живым");
        assert_eq!(both.list.len(), 2);
        assert_eq!(both.docs(), 65, "документы обоих сегментов не сложились");
        // Живой — последний: чтение по идентификатору обходит состав с конца.
        assert!(both.list[1].src.is_memory(), "живой сегмент встал не в хвост");
        assert_eq!(both.base, vec![0, 40], "начала номеров разъехались");
        point(&both, "живой-007");

        let found = |segs: &crate::segments::Segments| -> usize {
            segs.list
                .iter()
                .map(|s| {
                    let Some(list) = s.dict.lookup(0, "общее") else { return 0 };
                    let req = crate::search::Request {
                        mode: crate::search::MatchMode::AnyTerm,
                        skipped: false,
                        live: None,
                        words: vec![crate::search::QueryWord::new(0, vec![list])],
                        k: 1000,
                        filter: Vec::new(),
                        must: Vec::new(),
                        must_not: Vec::new(),
                        tree: Default::default(),
                        sort: Vec::new(),
                        floor_key: crate::search::KeyFloor::None,
                        doc_base: 0,
                        budget: None,
                        guard: None,
                        score: Vec::new(),
                        after: None,
                    };
                    crate::search::search(s, &req, 0.0).0.len()
                })
                .sum()
        };
        assert_eq!(found(&both), 65, "поиск не увидел обе пачки");

        // Третья пачка ложится на диск. Перечитывание обязано подобрать её и
        // сохранить живой сегмент.
        for n in 0..10 {
            ix.add(&format!("третий-{n:03}"), &["общее слово", "третья пачка"]);
        }
        ix.flush_now();
        let after = crate::segments::Segments::reopen(&path, &both).expect("перечитывание");
        assert_eq!(after.list.len(), 3, "перечитывание потеряло сегмент");
        assert!(after.list[2].src.is_memory(), "живой сегмент уехал из хвоста");
        assert!(!after.list[0].src.is_memory() && !after.list[1].src.is_memory());
        assert_eq!(after.docs(), 75, "документы после перечитывания не сошлись");
        assert_eq!(found(&after), 75, "поиск после перечитывания не увидел всех");
        assert_eq!(after.live_ones().count(), 1, "живых сегментов оказалось не один");
        point(&after, "третий-007");

        // Когда живой ляжет на диск, его надо убрать: иначе каждый его документ
        // показался бы дважды.
        let without = after.without_live("память/живой-0").expect("состав без живого");
        assert_eq!(without.list.len(), 2, "живой сегмент не убрался");
        assert_eq!(without.docs(), 50, "после снятия живого счёт не сошёлся");
        assert_eq!(without.live_ones().count(), 0);
        point(&without, "третий-007");

        if crate::stats::ENABLED {
            let counters = crate::stats::take();
            assert_eq!(counters.catalog_opened, 1, "live/append ReadView переоткрыл каталог");
            assert_eq!(counters.catalog_used, 4, "не все поколения использовали общий каталог");
        }

        std::fs::remove_dir_all(&path).ok();
    }

    /// Живой сегмент переживает перечитывание и тогда, когда на диске не
    /// осталось ни одного сегмента.
    ///
    /// Случай не выдуманный: уборка забирает сегмент целиком, если все его
    /// документы погашены заменами. На узле, где всё принятое лежит в буфере,
    /// это обычное состояние — и ранний возврат пустого состава выбрасывал бы
    /// живой сегмент ровно там, где терять его больнее всего.
    #[test]
    fn an_empty_manifest_does_not_throw_away_the_live_segment() {
        let path = dir("пустой-список");
        std::fs::create_dir_all(&path).expect("каталог");
        let empty = crate::segments::Segments::load(&path).expect("состав");
        assert!(empty.list.is_empty(), "стенд начался не с пустого состава");

        let mut ix = indexer(&path);
        for n in 0..12 {
            ix.add(&format!("живой-{n:03}"), &["общее слово", "только в памяти"]);
        }
        let sc = ix.schema();
        let built = write_segment(Target::Memory, 1, &sc, &ix.buf).expect("сегмент в память");
        let source = std::sync::Arc::new(built.pack.expect("куски").source("живой-сегмент"));
        let live = std::sync::Arc::new(crate::index::open_memory(source).expect("открытие"));

        let with = empty.with_live(live).expect("состав с живым");
        assert_eq!(with.docs(), 12);

        let after = crate::segments::Segments::reopen(&path, &with).expect("перечитывание");
        assert_eq!(after.list.len(), 1, "перечитывание выбросило живой сегмент");
        assert_eq!(after.docs(), 12, "документы живого сегмента потерялись");
        assert!(after.list[0].src.is_memory());

        std::fs::remove_dir_all(&path).ok();
    }

    /// Замена до сброса оставляет одну живую версию, а не две.
    #[test]
    fn replacing_before_the_flush_leaves_one_live_version() {
        let path = dir("one-live");
        let mut ix = indexer(&path);
        for v in ["один", "два", "три"] {
            ix.replace("a", &["пёс", v]);
        }
        ix.add("b", &["кот", "сосед"]);
        ix.flush();

        let seg = index::load(&format!("{path}/seg0000")).unwrap();
        assert_eq!(seg.docs, 4, "все версии лежат в сегменте");
        assert_eq!(seg.dead(), 2, "живой обязана остаться последняя");
        assert!(!seg.is_live(0) && !seg.is_live(1));
        assert!(seg.is_live(2) && seg.is_live(3));
        std::fs::remove_dir_all(&path).ok();
    }

    /// Гашение до сброса — то же самое: документ уходит в сегмент уже мёртвым.
    ///
    /// Открыть окно между «сегмент записан» и «бит погашен» нельзя: в этом окне
    /// поиск видит удалённое, а падение оставляет его живым навсегда.
    #[test]
    fn a_buffered_document_is_born_dead_when_deleted_first() {
        let path = dir("born-dead");
        let mut ix = indexer(&path);
        ix.add("a", &["пёс", "текст"]);
        ix.add("b", &["кот", "текст"]);
        assert_eq!(ix.kill_buffered("a"), 1);
        assert_eq!(ix.kill_buffered("a"), 0, "дважды не гасится");
        assert_eq!(ix.kill_buffered("нет-такого"), 0);
        assert_eq!(ix.buffered_dead(), 1);
        ix.flush();

        let seg = index::load(&format!("{path}/seg0000")).unwrap();
        assert!(!seg.is_live(0), "погашенный до сброса не оживает");
        assert!(seg.is_live(1));
        std::fs::remove_dir_all(&path).ok();
    }

    /// Таблица идентификаторов переживает пересборку при росте.
    ///
    /// Смысл проверки не в объёме, а в том, что при удвоении ячейки
    /// перекладываются по хешу, взятому заново из `ids`: ошибка там нашлась бы
    /// только на буфере, переросшем начальный размер.
    #[test]
    fn the_id_table_survives_growing() {
        let path = dir("grow");
        let mut ix = indexer(&path);
        for i in 0..500 {
            ix.add(&format!("ид-{i}"), &["слово", "текст"]);
        }
        // Гасим каждый десятый — уже после того, как таблица выросла много раз.
        for i in (0..500).step_by(10) {
            assert_eq!(ix.kill_buffered(&format!("ид-{i}")), 1, "не нашёлся ид-{i}");
        }
        assert_eq!(ix.buffered_dead(), 50);
        ix.flush();

        let seg = index::load(&format!("{path}/seg0000")).unwrap();
        assert_eq!(seg.dead(), 50);
        for d in 0..500u32 {
            assert_eq!(seg.is_live(d), d % 10 != 0, "документ {d}");
        }
        std::fs::remove_dir_all(&path).ok();
    }

    /// Столкновение хешей не гасит чужой документ: строка сверяется целиком.
    #[test]
    fn only_the_named_document_dies() {
        let path = dir("no-collateral");
        let mut ix = indexer(&path);
        ix.add("a", &["пёс", "текст"]);
        ix.add("aa", &["кот", "текст"]);
        ix.add("a", &["лис", "текст"]);
        assert_eq!(ix.kill_buffered("a"), 2, "обе копии одного ид");
        assert_eq!(ix.buffered_dead(), 2);
        ix.flush();

        let seg = index::load(&format!("{path}/seg0000")).unwrap();
        assert!(seg.is_live(1), "сосед по таблице обязан уцелеть");
        std::fs::remove_dir_all(&path).ok();
    }
}

#[cfg(test)]
mod pretokenize_tests {
    use super::*;

    /// Сегмент не зависит от того, где разобрали слова.
    ///
    /// Это условие всей затеи. Слова теперь разбираются в двух местах — под
    /// замком буфера и заранее, вне его, — и разойдись они хоть в одном
    /// правиле, два одинаковых корпуса дали бы разные сегменты: другой словарь,
    /// другие списки, другая выдача. Сверяются **байты**, а не поиск: поиск
    /// прошёл бы и на разошедшихся, если расхождение мелкое.
    #[test]
    fn the_segment_does_not_depend_on_where_the_words_were_split() {
        let root = std::env::temp_dir().join(format!("svindb-pretok-{}", std::process::id()));
        let root = root.to_string_lossy().to_string();
        std::fs::remove_dir_all(&root).ok();

        // Поля всех видов, которые ходят разными ветвями укладки.
        let names: Vec<String> =
            ["текст", "метка", "число", "двоичное"].iter().map(|s| s.to_string()).collect();
        let kinds = vec![Kind::Text, Kind::Keyword, Kind::Int64, Kind::Binary];
        let docs: Vec<(String, Vec<String>)> = (0..400u32)
            .map(|i| {
                (
                    format!("док{i:04}"),
                    vec![
                        format!("Слово{} ДРУГОЕ_{} ещё-раз {} ß Ä", i % 37, i % 11, i),
                        format!("  Метка{}  ", i % 5),
                        format!("{}", i * 7),
                        format!("AQAAAB8ABbBc{}", i % 3),
                    ],
                )
            })
            .collect();

        let build = |tag: &str, outside: bool| -> Vec<u8> {
            let dir = format!("{root}/{tag}");
            std::fs::remove_dir_all(&dir).ok();
            let mut ix = Indexer::typed(&dir, names.clone(), vec![1.0; 4], kinds.clone(), 100_000);
            for (id, vals) in docs.iter() {
                let refs: Vec<&str> = vals.iter().map(|s| s.as_str()).collect();
                if outside {
                    // Ровно то, что делает сервер: разбор снаружи, тем же кодом.
                    let a = crate::analyze::Simple;
                    let mut pre: Vec<crate::analyze::Tokens> =
                        vec![crate::analyze::Tokens::default(); 4];
                    for (f, text) in vals.iter().enumerate() {
                        if kinds[f].numeric() {
                            continue;
                        }
                        let mut w = crate::analyze::Tokens::default();
                        Indexer::<crate::analyze::Simple>::field_tokens(&a, kinds[f], text, &mut w);
                        pre[f] = w;
                    }
                    ix.add_pre(id, &refs, Some(pre.as_mut_slice()));
                } else {
                    ix.add(id, &refs);
                }
            }
            ix.flush_now();
            let bytes = std::fs::read(format!("{dir}/seg0000/{}", crate::container::FILE))
                .expect("контейнер сегмента");
            std::fs::remove_dir_all(&dir).ok();
            bytes
        };

        let inside = build("внутри", false);
        let outside = build("снаружи", true);
        assert!(!inside.is_empty(), "сегмент не собрался");
        assert_eq!(
            inside.len(),
            outside.len(),
            "сегменты разной длины: {} против {}",
            inside.len(),
            outside.len()
        );
        assert!(
            inside == outside,
            "сегменты разошлись побайтово — слова разобраны по разным правилам"
        );
        std::fs::remove_dir_all(&root).ok();
    }
}

#[cfg(test)]
mod tests {
    /// Отказ записи сегмента останавливает приём, а не убивает узел.
    ///
    /// Сборка выпуска идёт с `panic = "abort"`. Паника в потоке фоновой записи
    /// не разматывает стек и не закрывает канал — она убивает **процесс**:
    /// полный диск или снятые права на одном сегменте валили бы весь узел со
    /// всеми соединениями, хотя приём мог бы просто остановиться и сказать
    /// почему.
    ///
    /// Отказ делается настоящим, а не подделанным: каталог индекса
    /// подменяется файлом, и `create_dir_all` под сегмент отказывает так же,
    /// как отказал бы на полном диске.
    #[test]
    fn a_failed_write_stops_ingest_instead_of_killing_the_node() {
        let base = std::env::temp_dir()
            .join(format!("svindb-ingest-fail-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&base).ok();
        std::fs::create_dir_all(&base).expect("каталог");
        let dir = format!("{base}/ix");
        std::fs::create_dir_all(&dir).expect("каталог индекса");

        let mut ix = Indexer::new(&dir, vec!["title".into(), "body".into()], vec![2.0, 1.0], 50);
        for i in 0..10u32 {
            ix.add(&format!("d{i}"), &[&format!("док {i}"), "общее тело"]);
        }
        assert!(ix.poisoned().is_none(), "пока всё в порядке");

        // Каталог индекса становится файлом: под сегмент его не создать.
        std::fs::remove_dir_all(&dir).expect("убрали каталог");
        std::fs::write(&dir, "не каталог").expect("положили файл");

        ix.flush();
        ix.drain();

        let why = ix.poisoned().expect("отказ записи обязан быть замечен");
        assert!(why.contains(&dir), "отказ обязан называть место, а не только факт: {why}");

        // И приём после этого не делает вид, что работает: повторный сброс
        // молча ничего не пишет, а признак остаётся.
        ix.add("после", &["ещё", "документ"]);
        ix.flush();
        ix.drain();
        assert!(ix.poisoned().is_some(), "признак липкий и не снимается");

        std::fs::remove_dir_all(&base).ok();
        std::fs::remove_file(&base).ok();
    }

    /// Крупные документы сбрасываются по объёму, а не только по счёту.
    ///
    /// Порог по числу документов один и тот же для корпуса из твитов и для
    /// корпуса из статей, а память они занимают несравнимую. Без второго порога
    /// «миллион на сегмент» на тяжёлых документах означает буфер в терабайт, и
    /// узел умирает не от ошибки, а от размера.
    #[test]
    fn a_heavy_corpus_flushes_by_size_not_only_by_count() {
        let dir = std::env::temp_dir()
            .join(format!("svindb-flush-bytes-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&dir).ok();
        // Счёт заведомо недостижим: до него не дойдёт ни один из документов.
        let mut ix = Indexer::new(&dir, vec!["body".into()], vec![1.0], 1_000_000);
        ix.set_flush_bytes(1 << 20);
        let heavy = "слово ".repeat(20_000); // около 220 КБ
        for i in 0..40 {
            ix.add(&format!("d{i}"), &[&heavy]);
        }
        ix.drain();
        assert!(
            ix.segments() > 0,
            "буфер обязан был сброситься по объёму: сегментов {}, документов в буфере {}",
            ix.segments(),
            ix.buffered()
        );

        // И обратное: тот же счёт при выключенном пороге по объёму не сбрасывает.
        let dir2 = format!("{dir}-off");
        std::fs::remove_dir_all(&dir2).ok();
        let mut off = Indexer::new(&dir2, vec!["body".into()], vec![1.0], 1_000_000);
        off.set_flush_bytes(0);
        for i in 0..40 {
            off.add(&format!("d{i}"), &[&heavy]);
        }
        assert_eq!(off.segments(), 0, "без порога по объёму сброса быть не должно");
        std::fs::remove_dir_all(&dir).ok();
        std::fs::remove_dir_all(&dir2).ok();
    }

    use super::*;
    use crate::index;

    /// Двоичное значение не сводится в нижний регистр и переживает слияние.
    ///
    /// Оба утверждения несущие. Регистр: Base64 регистрозначим, и свести его
    /// значило бы склеить два разных значения молча. Слияние: опоры словаря
    /// строятся через `String::from_utf8_lossy`, и ради этого словом словаря
    /// сделан Base64, а не сами байты, — иначе значение испортилось бы при
    /// первом же укрупнении.
    #[test]
    fn a_binary_value_keeps_its_case_and_survives_the_merge() {
        let dir = std::env::temp_dir().join("svindb-indexer-binary");
        std::fs::remove_dir_all(&dir).ok();
        let path = dir.to_string_lossy().to_string();
        let build = |from: usize, n: usize| {
            let mut ix = Indexer::typed_stored(
                &path,
                vec!["t".into(), "payload".into()],
                vec![1.0, 1.0],
                vec![Kind::Text, Kind::Binary],
                vec![true, true],
                1_000_000,
            );
            for d in from..from + n {
                let up = "AQAAAB8ABbBc";
                let low = "aqaaab8abbbc";
                ix.add(&format!("d{d}"), &["документ", if d % 2 == 0 { up } else { low }]);
            }
            ix.flush();
        };
        build(0, 4);
        build(4, 4);

        let segs: Vec<String> = (0..2).map(|i| format!("{path}/seg{i:04}")).collect();
        let ixs: Vec<crate::index::Index> =
            segs.iter().map(|d| crate::index::load(d).expect("сегмент")).collect();
        // Два разных значения, а не одно: сведи регистр — и их стало бы одно.
        let words = |ix: &crate::index::Index| -> Vec<String> {
            (0..ix.nterms)
                .map(|t| ix.dict.term_at(t).1)
                .filter(|w| w.eq_ignore_ascii_case("aqaaab8abbbc"))
                .collect()
        };
        let mut seen = words(&ixs[0]);
        seen.sort();
        seen.dedup();
        assert_eq!(seen.len(), 2, "регистр сведён — значения слиплись: {seen:?}");
        assert!(seen.iter().any(|w| w == "AQAAAB8ABbBc"), "верхний регистр потерян: {seen:?}");

        let refs: Vec<&crate::index::Index> = ixs.iter().collect();
        let out = format!("{path}/mrg");
        crate::merge::merge(&refs, &out).expect("слияние");
        let m = crate::index::load(&out).expect("слитый открылся");
        let mut after: Vec<String> = (0..m.nterms)
            .map(|t| m.dict.term_at(t).1)
            .filter(|w| w.eq_ignore_ascii_case("aqaaab8abbbc"))
            .collect();
        after.sort();
        after.dedup();
        assert_eq!(after, seen, "слияние испортило двоичные значения: {after:?}");
        assert_eq!(crate::check::check(&out, crate::check::Depth::Full).broken(), 0);
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Поле с точкой в пути доходит до сегмента и открывается обратно.
    ///
    /// Прежде такого теста нельзя было даже написать: приём **паниковал** на
    /// точке в имени, а при `panic = "abort"` это смерть процесса. Причина
    /// была в том, что имя поля и основа имён файлов писались в заголовок одной
    /// переменной, и запрет на точку в имени файла становился запретом на точку
    /// в имени поля — то есть вложенный документ было нечем объявить.
    #[test]
    fn a_dotted_path_reaches_the_segment_under_its_own_file_stem() {
        let dir = std::env::temp_dir().join("svindb-indexer-dotted");
        std::fs::remove_dir_all(&dir).ok();
        let path = dir.to_string_lossy().to_string();
        let mut ix = Indexer::typed_stored(
            &path,
            vec!["title".into(), "reactions.emoji".into(), "@timestamp".into()],
            vec![2.0, 1.0, 1.0],
            vec![Kind::Text, Kind::Keyword, Kind::Keyword],
            vec![true, true, true],
            1_000_000,
        );
        assert!(ix.poisoned().is_none(), "точка в пути отравила приёмник: {:?}", ix.poisoned());
        for d in 0..5i64 {
            ix.add(&format!("d{d}"), &["документ", "up", "2026-11-13"]);
        }
        ix.flush();

        let seg = format!("{path}/seg0000");
        // В контейнере лежит `f1.sbin`, а не `reactions.emoji.sbin`: имя файла
        // выведено из пути, а не равно ему.
        let t = crate::container::Table::read(&format!("{seg}/{}", crate::container::FILE))
            .expect("оглавление контейнера");
        let names: Vec<String> = t.members().iter().map(|m| m.name.clone()).collect();
        assert!(names.iter().any(|n| n == "f1.sbin"), "нет куска f1.sbin: {names:?}");
        assert!(
            !names.iter().any(|n| n.starts_with("reactions.emoji")),
            "имя поля утекло в имя куска: {names:?}"
        );
        // А в заголовке — оба смысла порознь.
        let ix2 = crate::index::load(&seg).expect("сегмент открылся");
        assert_eq!(ix2.fields[1].name, "reactions.emoji", "имя поля потеряно");
        assert_eq!(ix2.fields[1].stem, "f1", "основа имён файлов не та");
        assert_eq!(ix2.fields[2].name, "@timestamp");
        assert_eq!(ix2.fields[2].stem, "@timestamp");
        assert!(names.iter().any(|n| n == "@timestamp.sbin"));
        // И по нему действительно ищется — иначе проверка выше говорила бы лишь
        // о раскладке файлов, а не о работе.
        assert_eq!(crate::check::check(&seg, crate::check::Depth::Full).broken(), 0);
        std::fs::remove_dir_all(&dir).ok();
    }

    fn build(name: &str, docs: &[(&str, &str, &str)], per_seg: u32) -> String {
        let dir = std::env::temp_dir().join(format!("svindb-indexer-{name}"));
        std::fs::remove_dir_all(&dir).ok();
        let path = dir.to_string_lossy().to_string();
        let mut ix =
            Indexer::new(&path, vec!["title".into(), "body".into()], vec![2.0, 1.0], per_seg);
        for (id, title, body) in docs {
            ix.add(id, &[title, body]);
        }
        ix.flush();
        path
    }

    fn sample() -> Vec<(&'static str, &'static str, &'static str)> {
        vec![
            ("a", "дом у дороги", "старый дом стоял у дороги много лет"),
            ("b", "домик", "маленький домик"),
            ("c", "дорога", "дорога уходила за горизонт"),
            ("d", "ель", "ель и сосна"),
        ]
    }

    #[test]
    fn writes_a_loadable_segment() {
        let dir = build("basic", &sample(), 100);
        let ix = index::load(&format!("{dir}/seg0000")).unwrap();
        assert_eq!(ix.docs, 4);
        assert_eq!(ix.fields.len(), 2);
        assert_eq!(ix.fields[0].name, "title");
        assert_eq!(ix.fields[0].boost, 2.0);
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Словарь и списки обязаны сойтись: df из `terms.bin` против числа
    /// документов, действительно содержащих слово.
    #[test]
    fn dictionary_matches_postings() {
        let dir = build("dict", &sample(), 100);
        let ix = index::load(&format!("{dir}/seg0000")).unwrap();

        // «дом» стоит в заголовке одного документа и в теле одного.
        let title = ix.dict.lookup(0, "дом").expect("дом в заголовке");
        assert_eq!(ix.t_df(title as usize), 1);
        let body = ix.dict.lookup(1, "дом").expect("дом в теле");
        assert_eq!(ix.t_df(body as usize), 1);

        // «дороги» и «дорога» — разные слова, пока нет морфологии. Это не
        // упущение теста: индекс хранит то, что дал разбор, и в фазе 1 разбор
        // словоформы не сводит.
        assert_eq!(ix.t_df(ix.dict.lookup(1, "дороги").unwrap() as usize), 1);
        assert_eq!(ix.t_df(ix.dict.lookup(1, "дорога").unwrap() as usize), 1);
        assert_eq!(ix.t_df(ix.dict.lookup(0, "дороги").unwrap() as usize), 1);

        // Повтор слова в одном документе не удваивает список.
        let old = ix.dict.lookup(1, "старый").expect("старый в теле");
        assert_eq!(ix.t_df(old as usize), 1);
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Мёртвого груза нет, а карта живых — не груз.
    ///
    /// Причина в том, что правка карты перестала быть подменой файла и стала
    /// правкой разделяемого отображения — а отобразить можно только то, что
    /// существует. Заводить файл при первом удалении значило бы либо городить
    /// изменяемость внутри неизменяемого сегмента, либо оставлять первую пачку
    /// удалений медленной. Цена — `docs/8` байт, три сотых процента сегмента.
    #[test]
    fn only_the_useless_is_left_unwritten() {
        let dir = build("lean", &sample(), 100);
        let seg = format!("{dir}/seg0000");
        assert!(!std::path::Path::new(&format!("{seg}/dict.tsv")).exists());

        let ix = index::load(&seg).unwrap();
        assert!(ix.live.is_some(), "карта обязана быть — по ней и гасят");
        assert!(ix.all_live(), "в свежем сегменте все документы живы");
        assert_eq!(ix.dead(), 0);
        for doc in 0..ix.docs as u32 {
            assert!(ix.is_live(doc));
        }
        // Ровно бит на документ, слово признака «есть погашенные» и печать.
        assert_eq!(ix.live_bytes(), (ix.docs.div_ceil(64) + 1 + crate::live::SEAL_WORDS) * 8);

        // И она сразу годна к правке, без всякой подготовки.
        assert!(ix.kill(0), "первое же гашение обязано пройти");
        assert!(!ix.is_live(0));
        assert_eq!(ix.dead(), 1);
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Метаданные прогрева лежат в контейнере сплошным прогоном и последними.
    ///
    /// ## Что ломалось бы без этого
    ///
    /// Ради этого порядка и заведён `meta_run`: [`crate::index::Index::warm`]
    /// греет ровно эти куски, и лежащие подряд они читаются одним упреждающим
    /// чтением вместо восьми поисков головки. Порядок держится одним `drain` в
    /// конце сборки — переставь его выше, и прогрев тихо станет вдвое дороже на
    /// каждом открытии сегмента, а выдача не изменится ни на документ. У слияния
    /// этот же порядок закреплён такой же сверкой (`the_merged_segment_is_one_container`),
    /// и расходиться двум писателям нельзя: сегменты от приёма и от слияния
    /// живут в одном индексе и открываются одним кодом.
    ///
    /// Сверяется смещением, а не порядком записей оглавления: оглавление
    /// отсортировано по имени и про порядок укладки не говорит ничего.
    #[test]
    fn ingest_lays_the_warmed_metadata_in_one_run_at_the_end() {
        let dir = std::env::temp_dir().join("svindb-indexer-meta-run");
        std::fs::remove_dir_all(&dir).ok();
        let path = dir.to_string_lossy().to_string();
        // Схема нарочно с обоими видами хвоста: у хранимого текста будут куски
        // содержимого, у числового поля — колонка. Колонка тоже ложится
        // прогоном, хотя собирается раньше содержимого, и без неё проверка
        // прошла бы мимо половины прогона.
        let mut ix = Indexer::typed(
            &path,
            vec!["body".into(), "num".into()],
            vec![1.0, 1.0],
            vec![Kind::Text, Kind::Int64],
            10_000,
        );
        for i in 0..64 {
            ix.add(&format!("d{i}"), &[&format!("дорога и дом номер {i}"), &format!("{i}")]);
        }
        ix.flush();

        let seg = format!("{path}/seg0000");
        let head = index::read_head(&seg).expect("заголовок");
        let container = head.container.expect("приём собрал сегмент россыпью");
        let file = format!("{seg}/{}", crate::container::FILE);
        assert_eq!(
            container,
            std::fs::metadata(&file).expect("контейнер на месте").len(),
            "заголовок обещает не ту длину контейнера"
        );
        let table = crate::container::Table::read(&file).expect("оглавление");

        // Что греет `Index::warm` — то и есть прогон. Список здесь свой, а не
        // взятый из `warm`: разойдись они, разойтись обязан и тест.
        let meta = |n: &str| {
            matches!(
                n,
                "blocks.bin"
                    | "terms.bin"
                    | "terms.idx"
                    | "dict.blob"
                    | "dict.idx"
                    | "terms.bloom"
                    | "norms.bin"
            ) || [".col", ".cmeta", ".has", ".bkt", ".bktidx", ".scol", ".smeta"]
                .iter()
                .any(|e| n.ends_with(e))
        };
        let names: Vec<&str> = table.members().iter().map(|m| m.name.as_str()).collect();
        // Проверка обязана иметь что проверять: без содержимого и без колонки
        // прогон нечем отделить от всего остального.
        assert!(names.contains(&"body.sbin"), "содержимого нет: {names:?}");
        assert!(names.contains(&"num.col"), "колонки нет: {names:?}");
        assert!(names.contains(&"postings.bin"), "списков нет: {names:?}");

        let run: Vec<&crate::container::Member> =
            table.members().iter().filter(|m| meta(&m.name)).collect();
        let rest: Vec<&crate::container::Member> =
            table.members().iter().filter(|m| !meta(&m.name)).collect();
        let run_from = run.iter().map(|m| m.off).min().expect("прогон пуст");
        let last = rest.iter().max_by_key(|m| m.off).expect("кроме прогона ничего нет");
        assert!(
            last.off < run_from,
            "кусок {:?} лёг внутрь прогона метаданных или после него: прогон начинается с {run_from}, \
             а он на {} — прогрев перестал быть одним чтением",
            last.name,
            last.off
        );
        // И начинается контейнер списками: они пишутся потоком и крупнее всего.
        let at = |n: &str| table.find(n).unwrap_or_else(|| panic!("{n}")).off;
        assert_eq!(
            at("postings.bin"),
            table.members().iter().map(|m| m.off).min().unwrap_or(0),
            "списки легли не первыми"
        );
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Смещение блока накапливается по длинам и обязано сойтись с записанным.
    #[test]
    fn block_lengths_add_up_to_offsets() {
        // Корпус нарочно с повторами: у слова из одного документа списка нет
        // вовсе — номер лежит в его собственной записи, — и проверка смещений
        // не исполнилась бы ни разу. Сверять надо там, где список настоящий.
        let mut corpus = sample();
        for (id, t, b) in [
            ("e", "дорога", "дорога уходила за горизонт"),
            ("f", "дорога", "старый дом стоял у дороги"),
            ("g", "дом", "дом у дороги"),
        ] {
            corpus.push((id, t, b));
        }
        let dir = build("offsets", &corpus, 100);
        let seg = format!("{dir}/seg0000");
        let ix = index::load(&seg).unwrap();
        let post = crate::sums::sizes(&seg).postings as usize;
        assert!(post > 0, "списки пусты — сверять смещения не с чем");
        let mut off = Vec::new();
        for list in 0..ix.nterms {
            let field = ix.dict.term_at(list).0 as usize;
            let t = ix.term(list, field);
            // У одиночного слова седьмой раскладки в файле списков нет ничего:
            // номер документа лежит в его собственной записи.
            if t.one.is_some() {
                continue;
            }
            ix.block_offsets(&t, &mut off);
            for (b, &at) in off.iter().enumerate() {
                assert!(at < post, "список {list}, блок {b}: смещение {at} за концом файла");
            }
        }
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Буфер полон — сегмент записан, нумерация продолжается.
    #[test]
    fn splits_into_segments() {
        let dir = build("segs", &sample(), 2);
        assert!(std::path::Path::new(&format!("{dir}/seg0000")).exists());
        assert!(std::path::Path::new(&format!("{dir}/seg0001")).exists());
        let a = index::load(&format!("{dir}/seg0000")).unwrap();
        let b = index::load(&format!("{dir}/seg0001")).unwrap();
        assert_eq!(a.docs, 2);
        assert_eq!(b.docs, 2);
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Идентификаторы лежат по порядку номеров — на этом стоит связь с выдачей.
    #[test]
    fn ids_follow_document_numbers() {
        let dir = build("ids", &sample(), 100);
        let seg = format!("{dir}/seg0000");
        let head = crate::index::read_head(&seg).expect("заголовок");
        let src = crate::container::SegmentSource::of(&seg, head.container).expect("источник");
        let ids = crate::ids::Ids::open(&src, 4);
        let got: Vec<String> = (0..4).map(|i| ids.get(i).unwrap()).collect();
        assert_eq!(got, vec!["a", "b", "c", "d"]);
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Длинный список переваливает за блок и остаётся читаемым.
    #[test]
    fn long_list_spans_blocks() {
        let dir = std::env::temp_dir().join("svindb-indexer-blocks");
        std::fs::remove_dir_all(&dir).ok();
        let path = dir.to_string_lossy().to_string();
        let mut ix = Indexer::new(&path, vec!["body".into()], vec![1.0], 100_000);
        let n = BLOCK * 3 + 7;
        for i in 0..n {
            ix.add(&format!("d{i}"), &["общий"]);
        }
        ix.flush();

        let loaded = index::load(&format!("{path}/seg0000")).unwrap();
        let list = loaded.dict.lookup(0, "общий").unwrap();
        assert_eq!(loaded.t_df(list as usize) as usize, n);
        assert_eq!(index::blocks_of(loaded.t_df(list as usize)) as usize, n.div_ceil(BLOCK));

        // Обход отдаёт ровно те номера, что записаны, и по возрастанию.
        let mut c = loaded.cursor(list, 0, 1.0);
        let mut seen = Vec::new();
        loop {
            let d = c.cur();
            if d == u32::MAX {
                break;
            }
            seen.push(d);
            c.next();
        }
        assert_eq!(seen, (0..n as u32).collect::<Vec<_>>());
        std::fs::remove_dir_all(&dir).ok();
    }
}

#[cfg(test)]
mod tf_tests {
    use super::*;
    use crate::index;
    use crate::search::{QueryWord, Request};

    fn build(name: &str, docs: &[(&str, &str)]) -> String {
        let dir = std::env::temp_dir().join(format!("svindb-tf-{name}"));
        std::fs::remove_dir_all(&dir).ok();
        std::fs::create_dir_all(&dir).unwrap();
        let d = dir.to_string_lossy().to_string();
        let mut ix = Indexer::new(&d, vec!["body".into()], vec![1.0], 1_000_000);
        for (id, text) in docs {
            ix.add(id, &[text]);
        }
        ix.flush();
        d
    }

    fn scores(seg: &str, word: &str) -> Vec<(u32, f64)> {
        let ix = index::load(seg).unwrap();
        let list = ix.dict.lookup(0, word).expect("слово есть");
        let req = Request {
            mode: crate::search::MatchMode::AnyTerm,
            skipped: false,
            live: None,
            words: vec![QueryWord::new(0, vec![list])],
            k: 10,
            filter: Vec::new(),
            must: Vec::new(),
            must_not: Vec::new(),
            tree: Default::default(),
            sort: Vec::new(),
            floor_key: crate::search::KeyFloor::None,
            doc_base: 0,
            budget: None,
            guard: None,
            score: Vec::new(),
            after: None,
        };
        let (hits, _) = crate::search::search(&ix, &req, 0.0);
        hits.into_iter().map(|h| (h.doc, h.score)).collect()
    }

    /// Ради этого всё и делалось: три вхождения весят больше одного.
    #[test]
    fn more_occurrences_outrank_fewer() {
        let dir = build(
            "rank",
            &[
                ("один", "цель прочее прочее прочее прочее прочее"),
                ("три", "цель цель цель прочее прочее прочее"),
                ("два", "цель цель прочее прочее прочее прочее"),
            ],
        );
        let got = scores(&format!("{dir}/seg0000"), "цель");
        let order: Vec<u32> = got.iter().map(|(d, _)| *d).collect();
        assert_eq!(order, vec![1, 2, 0], "порядок: три вхождения, два, одно");
        assert!(got[0].1 > got[1].1 && got[1].1 > got[2].1, "скоры {got:?}");
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Насыщение работает: десятое вхождение весит меньше второго.
    #[test]
    fn the_gain_from_each_next_occurrence_shrinks() {
        let mut docs = Vec::new();
        let texts: Vec<String> = (1..=10)
            .map(|n| {
                let mut t = vec!["цель"; n];
                t.extend(std::iter::repeat_n("прочее", 20 - n));
                t.join(" ")
            })
            .collect();
        for (i, t) in texts.iter().enumerate() {
            docs.push((["a", "b", "c", "d", "e", "f", "g", "h", "i", "j"][i], t.as_str()));
        }
        let dir = build("sat", &docs);
        let got = scores(&format!("{dir}/seg0000"), "цель");
        let mut by_doc = [0f64; 10];
        for (d, s) in got {
            by_doc[d as usize] = s;
        }
        let step_2 = by_doc[1] - by_doc[0];
        let step_10 = by_doc[9] - by_doc[8];
        assert!(step_2 > 0.0 && step_10 > 0.0, "каждое вхождение всё же добавляет");
        assert!(
            step_10 * 3.0 < step_2,
            "прибавка обязана убывать: со второго {step_2:.4}, с десятого {step_10:.4}"
        );
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Большая частота не ломает ни упаковку, ни порядок.
    #[test]
    fn large_frequencies_do_not_break_packing_or_order() {
        let many = vec!["цель"; 400].join(" ");
        let dir = build("cap", &[("мало", "цель прочее"), ("много", &many)]);
        let seg = format!("{dir}/seg0000");
        let got = scores(&seg, "цель");
        assert_eq!(got.len(), 2);
        let by: std::collections::HashMap<u32, f64> = got.into_iter().collect();
        assert!(by[&1] > by[&0], "четыреста вхождений весят больше одного");

        let ix = index::load(&seg).unwrap();
        let list = ix.dict.lookup(0, "цель").expect("слово в словаре");
        let mut c = ix.cursor(list, 0, 1.0);
        while c.cur() != 1 && c.cur() != u32::MAX {
            c.next();
        }
        assert_eq!(c.tf(), 400, "частота обрезана");
        let mut poss = Vec::new();
        assert_eq!(c.positions(&mut poss), 400, "позиций меньше, чем вхождений");
        assert_eq!(poss.last().copied(), Some(399), "последнее вхождение потеряно");
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Блок, где все частоты единичны, обязан занимать ноль байт.
    #[test]
    fn a_block_of_ones_costs_nothing() {
        let docs: Vec<(String, String)> =
            (0..300).map(|i| (format!("д{i}"), "цель одна штука".to_string())).collect();
        let refs: Vec<(&str, &str)> = docs.iter().map(|(a, b)| (a.as_str(), b.as_str())).collect();
        let dir = build("ones", &refs);
        let seg = format!("{dir}/seg0000");
        let ix = index::load(&seg).unwrap();
        let list = ix.dict.lookup(0, "цель").unwrap() as usize;
        let t = ix.term(list, 0);
        let mut off = Vec::new();
        ix.block_offsets(&t, &mut off);
        let n = crate::bits::BLOCK;
        let dw = crate::bits::width_of(ix.post.slice(off[0], 1));
        let fat = off[0] + crate::bits::packed_len(n, dw);
        if t.tf_all_one {
            // Седьмая раскладка полосу частот не пишет вовсе: следом за
            // номерами начинается уже следующий блок.
            assert_eq!(
                t.post_len as usize,
                crate::bits::packed_len(n, dw)
                    + crate::bits::packed_len(
                        300 - n,
                        crate::bits::width_of(ix.post.slice(fat, 1))
                    ),
                "кусок списка длиннее, чем сами номера — значит полоса частот всё же есть"
            );
        } else {
            assert_eq!(
                crate::bits::width_of(ix.post.slice(fat, 1)),
                0,
                "у блока из одних единиц ширина частот обязана быть нулевой"
            );
        }
        std::fs::remove_dir_all(&dir).ok();
    }
}

#[cfg(test)]
mod position_tests {
    use crate::index;

    fn dir(name: &str) -> String {
        let d = std::env::temp_dir().join(format!("svindb-pos-{name}"));
        let _ = std::fs::remove_dir_all(&d);
        std::fs::create_dir_all(&d).expect("каталог");
        d.to_string_lossy().to_string()
    }

    /// Фраза за двести пятьдесят пятым вхождением слова обязана находиться.
    #[test]
    fn a_phrase_past_the_old_frequency_cap_is_found() {
        use crate::segments::{QuerySpec, Segments, SpecPhrase};
        let d = dir("phrase-past-cap");
        let mut ix = super::Indexer::new(&d, vec!["body".into()], vec![1.0], 100_000);
        // Триста повторов «шум», и только потом «шум метка»: единственное
        // вхождение фразы стоит на позициях 299 и 300.
        let body = format!("{}метка", "шум ".repeat(300));
        ix.add("d0", &[&body]);
        ix.add("d1", &["шум и больше ничего"]);
        ix.flush();

        let segs = Segments::load(&d).expect("индекс");
        let q = QuerySpec {
            phrases: vec![SpecPhrase {
                fid: 0,
                terms: vec!["шум".into(), "метка".into()],
                slop: 0,
                boost: 1.0,
            }],
            k: 10,
            ..QuerySpec::default()
        };
        let out = segs.search(&q);
        assert_eq!(out.hits.len(), 1, "фраза за прежним потолком не нашлась");
        assert_eq!(out.hits[0].doc, 0);

        // И после укрупнения: слияние переносит позиции своим ходом, читая
        // частоту курсором, и потолок мог остаться там.
        let merged = format!("{d}/mrg0000");
        let refs: Vec<&index::Index> = segs.list.iter().map(|a| a.as_ref()).collect();
        crate::merge::merge(&refs, &merged).expect("слияние");
        let one = index::load(&merged).expect("слитый сегмент");
        let list = one.dict.lookup(0, "шум").expect("слово в словаре");
        let c = one.cursor(list, 0, 1.0);
        let mut poss = Vec::new();
        assert_eq!(c.tf(), 300, "частота потерялась при слиянии");
        assert_eq!(c.positions(&mut poss), 300);
        assert_eq!(poss.last().copied(), Some(299), "позиции потерялись при слиянии");

        let _ = std::fs::remove_dir_all(&d);
    }

    /// Позиции возвращаются те же, что были при приёме, — у **каждого** слова
    /// каждого документа, а не у выборки.
    ///
    /// Ошибка в смещении внутри блока вернула бы позиции соседнего документа, а
    /// они выглядят правдоподобно: те же величины, тот же порядок. Поймать
    /// подмену можно только полным перебором.
    #[test]
    fn every_position_comes_back_as_it_went_in() {
        let d = dir("exact");
        let mut ix = super::Indexer::new(&d, vec!["body".into()], vec![1.0], 100_000);
        // Документы разной длины и с разным числом повторов: блок обязан
        // пережить и документ с одним словом, и документ с сотней.
        let texts: Vec<String> = (0..900)
            .map(|i| {
                let n = 1 + (i % 40);
                let mut w = Vec::new();
                for k in 0..n {
                    w.push(format!("сл{}", (i + k) % 17));
                }
                w.join(" ")
            })
            .collect();
        for (i, t) in texts.iter().enumerate() {
            ix.add(&format!("d{i}"), &[t]);
        }
        ix.flush();

        let seg = format!("{d}/seg0000");
        let loaded = index::load(&seg).expect("сегмент");
        assert!(loaded.has_positions(), "позиции не записались");

        // Чего ждём: по каждому слову — документы и позиции его вхождений.
        let mut want: std::collections::HashMap<String, Vec<(u32, Vec<u32>)>> =
            std::collections::HashMap::new();
        for (i, t) in texts.iter().enumerate() {
            let mut by: std::collections::HashMap<&str, Vec<u32>> =
                std::collections::HashMap::new();
            for (p, w) in t.split_whitespace().enumerate() {
                by.entry(w).or_default().push(p as u32);
            }
            for (w, ps) in by {
                want.entry(w.to_string()).or_default().push((i as u32, ps));
            }
        }

        let mut checked = 0usize;
        let mut got = Vec::new();
        for (word, docs) in want.iter() {
            let list = loaded.dict.lookup(0, word).expect("слово в словаре");
            let mut c = loaded.cursor(list, 0, 1.0);
            for (doc, ps) in docs {
                assert_eq!(c.cur(), *doc, "слово {word}: список разошёлся по документам");
                assert_eq!(c.tf() as usize, ps.len(), "слово {word}, документ {doc}: частота");
                c.positions(&mut got);
                assert_eq!(&got, ps, "слово {word}, документ {doc}: позиции");
                checked += 1;
                c.next();
            }
            assert_eq!(c.cur(), u32::MAX, "слово {word}: список длиннее ожидаемого");
        }
        assert!(checked > 5000, "проверено всего {checked} пар — мало");
        let _ = std::fs::remove_dir_all(&d);
    }

    /// Поле с `nopos` позиций не занимает и честно отдаёт пусто.
    #[test]
    fn a_field_without_positions_costs_nothing() {
        let d = dir("nopos");
        let mut ix = super::Indexer::typed_positioned(
            &d,
            vec!["title".into(), "body".into()],
            vec![1.0, 1.0],
            vec![crate::index::Kind::Text; 2],
            vec![true, true],
            vec![true, false],
            100_000,
        );
        for i in 0..300 {
            ix.add(&format!("d{i}"), &[&format!("общее слово{i}"), "тайное слово тайное"]);
        }
        ix.flush();
        let loaded = index::load(&format!("{d}/seg0000")).expect("сегмент");
        let mut got = Vec::new();

        let l0 = loaded.dict.lookup(0, "общее").expect("слово поля с позициями");
        let c0 = loaded.cursor(l0, 0, 1.0);
        assert_eq!(c0.positions(&mut got), 1, "поле с позициями их не отдало");

        let l1 = loaded.dict.lookup(1, "тайное").expect("слово поля без позиций");
        let c1 = loaded.cursor(l1, 1, 1.0);
        assert_eq!(c1.tf(), 2, "частота обязана остаться и без позиций");
        assert_eq!(c1.positions(&mut got), 0, "поле без позиций их отдало");
        let _ = std::fs::remove_dir_all(&d);
    }
}

/// Числовое поле возвращает то же, что положили, — или хранит копию.
///
/// ## Что здесь на кону
///
/// Значение числового поля лежит в колонке, и вторая копия текстом стоила
/// 8.87 Б/док и 10.4 секунды приёма на двух миллионах. Отказ от неё держится
/// на одном: печать из колонки обязана дать **тот же байт**, что пришёл. Стоит
/// этому разойтись — и `007` вернётся семёркой, `1.50` полутора, а заметит это
/// не проверка целостности, а пользователь через полгода.
///
/// Поэтому проверяется не «числовое поле читается», а равенство исходному
/// тексту на каждом значении, включая те, где отказ от копии обязан **не**
/// сработать.
#[cfg(test)]
mod numeric_store_tests {
    use super::*;

    fn dir(name: &str) -> String {
        let d = std::env::temp_dir()
            .join(format!("svindb-numstore-{name}-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&d).ok();
        d
    }

    fn build(name: &str, kinds: Vec<Kind>, rows: &[Vec<&str>]) -> String {
        let d = dir(name);
        let n = kinds.len();
        let mut ix = Indexer::typed(
            &d,
            (0..n).map(|i| format!("f{i}")).collect(),
            vec![1.0; n],
            kinds,
            10_000,
        );
        for (i, row) in rows.iter().enumerate() {
            ix.add(&format!("d{i:04}"), row);
        }
        ix.flush();
        crate::manifest::write(
            &d,
            &crate::manifest::segments(&d)
                .iter()
                .map(|p| crate::manifest::name_of(p))
                .collect::<Vec<_>>(),
        )
        .unwrap();
        d
    }

    /// Сверяет **оба** пути отдачи содержимого.
    fn back(d: &str, rows: &[Vec<&str>]) {
        let segs = crate::segments::Segments::load(d).expect("индекс");
        let mut fetcher = segs.fetcher(1 << 20);
        for (i, row) in rows.iter().enumerate() {
            for (f, want) in row.iter().enumerate() {
                let got = segs.fetch(i as u64, f).unwrap_or_default();
                assert_eq!(
                    String::from_utf8_lossy(&got),
                    **want,
                    "документ {i}, поле {f}: `fetch` вернул не то, что положили"
                );
                let via = fetcher.get(i as u64, f).unwrap_or_default().to_vec();
                assert_eq!(
                    String::from_utf8_lossy(&via),
                    **want,
                    "документ {i}, поле {f}: `Fetcher` вернул не то, что положили"
                );
            }
        }
    }

    /// Обычные числа: копии нет, а значения возвращаются те же.
    #[test]
    fn plain_numbers_come_back_without_a_second_copy() {
        let kinds = vec![Kind::Text, Kind::Int32, Kind::Date, Kind::Bool, Kind::Double];
        let rows: Vec<Vec<&str>> = vec![
            vec!["первый текст", "42", "1700000000", "true", "1.5"],
            vec!["второй текст", "-7", "1600000000", "false", "-0.25"],
            vec!["третий", "0", "1", "true", "1000000"],
            // Документ без значений: пустая строка и есть то, что вернётся.
            vec!["четвёртый", "", "", "", ""],
        ];
        let d = build("plain", kinds, &rows);
        let seg = format!("{d}/seg0000");
        for f in 1..5 {
            assert!(
                !super::layout_tests::there(&seg, &format!("f{f}.sbin")),
                "копия поля {f} осталась"
            );
        }
        assert!(
            super::layout_tests::there(&seg, "f0.sbin"),
            "текстовое поле обязано храниться как прежде"
        );
        back(&d, &rows);
        std::fs::remove_dir_all(&d).ok();
    }

    /// Запись, которая обратно не печатается, оставляет копию — и она точна.
    #[test]
    fn a_value_that_would_not_print_back_keeps_its_copy() {
        // По одному полю на каждый способ разойтись с печатью.
        let cases: &[(&str, Kind, &str)] = &[
            ("нули впереди", Kind::Int32, "007"),
            ("плюс", Kind::Int32, "+5"),
            ("пробелы", Kind::Int32, " 5 "),
            ("хвостовой ноль", Kind::Double, "1.50"),
            ("не число вовсе", Kind::Int32, "n/a"),
            ("единица вместо true", Kind::Bool, "1"),
        ];
        for (what, kind, odd) in cases {
            let rows: Vec<Vec<&str>> =
                vec![vec!["текст", "42"], vec!["текст", odd], vec!["текст", "7"]];
            let d = build("odd", vec![Kind::Text, *kind], &rows);
            assert!(
                super::layout_tests::there(&format!("{d}/seg0000"), "f1.sbin"),
                "{what}: копия снята, а {odd:?} из колонки не восстановить"
            );
            back(&d, &rows);
            std::fs::remove_dir_all(&d).ok();
        }
    }

    /// Слияние сегмента с копией и сегмента без неё ничего не теряет.
    #[test]
    fn merging_a_segment_with_a_copy_and_one_without_keeps_both() {
        let d = dir("mixed");
        let mut ix = Indexer::typed(
            &d,
            vec!["body".into(), "n".into()],
            vec![1.0, 1.0],
            vec![Kind::Text, Kind::Int32],
            3,
        );
        // Первый сегмент — ровные числа, копии не будет. Второй — с `007`.
        let rows: Vec<Vec<&str>> = vec![
            vec!["раз", "1"],
            vec!["два", "2"],
            vec!["три", "3"],
            vec!["четыре", "007"],
            vec!["пять", "5"],
            vec!["шесть", "6"],
        ];
        for (i, row) in rows.iter().enumerate() {
            ix.add(&format!("d{i}"), row);
        }
        ix.flush();
        let names: Vec<String> =
            crate::manifest::segments(&d).iter().map(|p| crate::manifest::name_of(p)).collect();
        assert!(names.len() >= 2, "нужно два сегмента, вышло {}", names.len());
        crate::manifest::write(&d, &names).unwrap();

        let segs = crate::segments::Segments::load(&d).expect("индекс");
        let refs: Vec<&crate::index::Index> = segs.list.iter().map(|a| a.as_ref()).collect();
        let out = format!("{d}/mrg0000");
        crate::merge::merge(&refs, &out).expect("слияние");
        crate::manifest::write(&d, &["mrg0000".to_string()]).unwrap();
        back(&d, &rows);
        std::fs::remove_dir_all(&d).ok();
    }
}

/// Фоновая запись сегмента: то же на диске, и ничего не потеряно по дороге.
///
/// ## Что здесь на кону
#[cfg(test)]
mod background_tests {
    use super::*;

    fn dir(name: &str) -> String {
        let d = std::env::temp_dir()
            .join(format!("svindb-bg-{name}-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&d).ok();
        d
    }

    fn fill(ix: &mut Indexer, from: usize, n: usize) {
        for i in from..from + n {
            let body = format!("документ {i} слово{} общее хвост{}", i % 37, i % 11);
            ix.add(&format!("d{i:06}"), &[&body]);
        }
    }

    fn listing(d: &str) -> Vec<String> {
        crate::manifest::segments(d).iter().map(|p| crate::manifest::name_of(p)).collect()
    }

    /// Кусок, влитый в буфер, даёт побайтово тот же сегмент.
    ///
    /// ## Почему это единственное требование к куску
    ///
    /// Кусок нужен затем, чтобы разбор, токенизация и постинги шли вне замка
    /// приёма. Всё остальное про него — подробности, а вот это обязано
    /// выполняться буквально: сегмент, собранный через куски, не вправе
    /// отличаться от собранного последовательными `add` ни одним байтом.
    /// Отличие означало бы, что выдача зависит от того, как приём нарезал
    /// пачки, — то есть от случайности сети.
    ///
    /// Сверяется побайтово каждый файл контейнера, а не поиск по нему: поиск
    /// прошёл бы и на сегменте, где разошлись позиции или порядок списков.
    #[test]
    fn a_fragment_poured_in_gives_the_very_same_segment() {
        let root = std::env::temp_dir()
            .join(format!("svindb-frag-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&root).ok();
        std::fs::create_dir_all(&root).unwrap();

        let docs: Vec<(String, Vec<String>)> = (0..2600u32)
            .map(|i| {
                let id = format!("d{i:06}");
                let body = format!(
                    "слово{} общее хвост{} ещё{} {}",
                    i % 97,
                    i % 13,
                    i % 7,
                    "повтор ".repeat((i % 5) as usize)
                );
                let title = format!("док {i}");
                (id, vec![title, body])
            })
            .collect();

        let build = |tag: &str, chunk: usize| -> String {
            let dir = format!("{root}/{tag}");
            std::fs::remove_dir_all(&dir).ok();
            let mut ix =
                Indexer::new(&dir, vec!["title".into(), "body".into()], vec![2.0, 1.0], 10_000_000);
            if chunk == 0 {
                // Подряд, как было всегда.
                for (id, vals) in docs.iter() {
                    let refs: Vec<&str> = vals.iter().map(|s| s.as_str()).collect();
                    ix.add(id, &refs);
                }
            } else {
                // Кусками: каждый собирается отдельным приёмником и вливается.
                let mut frag = ix.detached();
                for part in docs.chunks(chunk) {
                    for (id, vals) in part.iter() {
                        let refs: Vec<&str> = vals.iter().map(|s| s.as_str()).collect();
                        frag.add(id, &refs);
                    }
                    ix.absorb(&mut frag);
                    assert_eq!(frag.staged(), 0, "кусок не опустел после слияния");
                }
            }
            ix.flush_now();
            dir
        };

        let one = build("подряд", 0);
        // Разные размеры куска: если бы слияние зависело от нарезки, они бы и
        // разошлись между собой.
        for chunk in [1usize, 7, 100, 2600] {
            let many = build(&format!("куски{chunk}"), chunk);
            let (a, b) = (format!("{one}/seg0000"), format!("{many}/seg0000"));
            // Сверяются файлы каталога целиком: это и есть «побайтово». Список
            // имён тоже сверяется — пропавший файл иначе прошёл бы незамеченным.
            let listing = |d: &str| -> Vec<String> {
                let mut v: Vec<String> = std::fs::read_dir(d)
                    .expect("каталог сегмента")
                    .filter_map(|e| e.ok())
                    .map(|e| e.file_name().to_string_lossy().to_string())
                    .collect();
                v.sort();
                v
            };
            let (la, lb) = (listing(&a), listing(&b));
            assert_eq!(la, lb, "кусок {chunk}: состав файлов сегмента разошёлся");
            assert!(la.len() >= 3, "файлов в сегменте всего {}", la.len());
            for name in la.iter() {
                let want = std::fs::read(format!("{a}/{name}")).expect("файл подряд");
                let got = std::fs::read(format!("{b}/{name}")).expect("файл кусками");
                assert_eq!(want.len(), got.len(), "кусок {chunk}: файл {name} другой длины");
                assert!(want == got, "кусок {chunk}: файл {name} разошёлся побайтово");
            }
            std::fs::remove_dir_all(&many).ok();
        }
        std::fs::remove_dir_all(&root).ok();
    }

    /// Parallel-ingest не вправе терять полосу арности nested-группы.
    ///
    /// До исправления `absorb` обходил число **полей**, а столбец переносил
    /// только при наличии его в обоих буферах. Общий буфер в начале пуст,
    /// поэтому куски отдавали ему документы, значения и постинги, но не
    /// арности. На стенде следующий одиночный документ оставил в `g1.aidx`
    /// одну запись при ста тысячах документов в заголовке: живой процесс не
    /// мог перечитать состав, после `kill -9` узел не поднимался.
    ///
    /// Здесь прямая укладка сравнивается побайтово с кусками разного размера,
    /// включая пустые массивы и несколько элементов. Одного «сегмент
    /// открылся» мало: потерянные нулевые хвосты могли открыть его с другой
    /// семантикой и выдать чужой элемент соседнему документу.
    #[test]
    fn nested_fragments_preserve_every_arity_entry() {
        let root = std::env::temp_dir()
            .join(format!("svindb-frag-nested-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&root).ok();
        std::fs::create_dir_all(&root).expect("корень проверки");

        fn indexer(dir: &str) -> Indexer {
            let mut ix = Indexer::typed(
                dir,
                vec!["text".into(), "reactions.emoji".into(), "reactions.count".into()],
                vec![2.0, 1.0, 1.0],
                vec![Kind::Text, Kind::Keyword, Kind::Int32],
                1_000_000,
            );
            ix.set_groups(vec![0, 1, 1], vec![String::new(), "reactions".into()]);
            ix
        }

        fn add(ix: &mut Indexer, i: usize) {
            let id = format!("nested-{i:06}");
            let text = format!("документ {i} общее слово{}", i % 29);
            let arity = (i % 5) as u32;
            let mut cells = vec![Cell { field: 0, slot: 0, text: &text }];
            for slot in 0..arity {
                cells.push(Cell {
                    field: 1,
                    slot,
                    text: if slot.is_multiple_of(2) { "up" } else { "fire" },
                });
                cells.push(Cell { field: 2, slot, text: "10" });
            }
            ix.add_cells(&id, &[1, arity], &cells);
        }

        let build = |tag: &str, chunk: usize| -> String {
            let dir = format!("{root}/{tag}");
            let mut ix = indexer(&dir);
            if chunk == 0 {
                for i in 0..1025 {
                    add(&mut ix, i);
                }
            } else {
                let mut frag = ix.detached();
                for from in (0..1025).step_by(chunk) {
                    for i in from..(from + chunk).min(1025) {
                        add(&mut frag, i);
                    }
                    ix.absorb(&mut frag);
                    assert_eq!(frag.staged(), 0, "кусок не опустел");
                }
            }
            ix.flush_now();
            assert_eq!(ix.poisoned(), None, "запись сегмента отказала");
            let seg = format!("{dir}/seg0000");
            let opened = crate::index::load(&seg).expect("nested-сегмент открылся");
            assert_eq!(opened.docs, 1025);
            assert_eq!(opened.slots[1].docs(), 1025);
            assert_eq!(opened.slots[1].units(), (0..1025).map(|i| i % 5).sum::<usize>());
            dir
        };

        let direct = build("подряд", 0);
        for chunk in [1usize, 17, 128, 1025] {
            let fragmented = build(&format!("куски-{chunk}"), chunk);
            for name in ["head.tsv", crate::live::FILE, crate::container::FILE] {
                let want =
                    std::fs::read(format!("{direct}/seg0000/{name}")).expect("эталонный файл");
                let got =
                    std::fs::read(format!("{fragmented}/seg0000/{name}")).expect("файл из кусков");
                assert_eq!(want, got, "кусок {chunk}: {name} разошёлся побайтово");
            }
        }
        std::fs::remove_dir_all(&root).ok();
    }

    /// Неполная полоса не доезжает до manifest даже при внутренней ошибке.
    #[test]
    fn a_segment_with_incomplete_arity_is_never_published() {
        let d = dir("неполная-арность");
        let mut ix = Indexer::typed(
            &d,
            vec!["text".into(), "reactions.emoji".into()],
            vec![1.0, 1.0],
            vec![Kind::Text, Kind::Keyword],
            10_000,
        );
        ix.set_groups(vec![0, 1], vec![String::new(), "reactions".into()]);
        for i in 0..20 {
            ix.add_cells(
                &format!("d{i}"),
                &[1, 1],
                &[
                    Cell { field: 0, slot: 0, text: "документ" },
                    Cell { field: 1, slot: 0, text: "up" },
                ],
            );
        }
        ix.buf.arity[1].pop();
        ix.flush_now();

        let why = ix.poisoned().expect("неполная полоса обязана отравить приём");
        assert!(why.contains("19 документов из 20"), "не тот отказ: {why}");
        assert!(crate::manifest::segments(&d).is_empty(), "битый сегмент попал в manifest");
        std::fs::remove_dir_all(&d).ok();
    }

    /// Фоновая запись обязана дать **тот же** индекс, что и обычная.
    ///
    /// Побайтово, а не «примерно»: писатель сегмента один и тот же код, и
    /// разойтись они могут только тем, что фоновый увидел не то состояние.
    #[test]
    fn the_background_writer_lays_down_the_very_same_bytes() {
        let a = dir("sync");
        let b = dir("bg");
        for (d, bg) in [(&a, false), (&b, true)] {
            let mut ix = Indexer::new(d, vec!["body".into()], vec![1.0], 500);
            if bg {
                ix.background(std::sync::Arc::new(std::sync::Mutex::new(())));
            }
            fill(&mut ix, 0, 2600);
            ix.flush_now();
        }
        let (la, lb) = (listing(&a), listing(&b));
        assert_eq!(la, lb, "состав разошёлся");
        assert!(la.len() >= 5, "сегментов мало, мерить нечего: {la:?}");
        for name in la.iter() {
            let mut files: Vec<String> = std::fs::read_dir(format!("{a}/{name}"))
                .expect("сегмент")
                .filter_map(|e| e.ok().map(|e| e.file_name().to_string_lossy().into_owned()))
                .collect();
            files.sort();
            assert!(!files.is_empty());
            for f in files {
                let x = std::fs::read(format!("{a}/{name}/{f}")).expect("файл");
                let y = std::fs::read(format!("{b}/{name}/{f}")).expect("файл");
                assert_eq!(x, y, "{name}/{f}: байты разошлись");
            }
        }
        std::fs::remove_dir_all(&a).ok();
        std::fs::remove_dir_all(&b).ok();
    }

    /// Порядок в списке сегментов — порядок наполнения буферов, а не диска.
    #[test]
    fn the_listing_follows_the_buffers_not_the_disk() {
        let d = dir("order");
        let mut ix = Indexer::new(&d, vec!["body".into()], vec![1.0], 300);
        ix.background(std::sync::Arc::new(std::sync::Mutex::new(())));
        fill(&mut ix, 0, 3000);
        ix.flush_now();
        let names = listing(&d);
        let mut want = names.clone();
        want.sort();
        assert_eq!(names, want, "список не по возрастанию номеров: {names:?}");
        assert_eq!(names[0], "seg0000");
        std::fs::remove_dir_all(&d).ok();
    }

    /// Явный сброс возвращается, когда сегмент **на диске**.
    #[test]
    fn an_explicit_flush_returns_only_when_the_segment_is_down() {
        let d = dir("visible");
        let mut ix = Indexer::new(&d, vec!["body".into()], vec![1.0], 100_000);
        ix.background(std::sync::Arc::new(std::sync::Mutex::new(())));
        fill(&mut ix, 0, 700);
        ix.flush_now();
        assert_eq!(ix.segments(), 1, "сегмент не досчитан");
        let names = listing(&d);
        assert_eq!(names, vec!["seg0000".to_string()]);
        assert!(
            std::path::Path::new(&format!("{d}/seg0000/head.tsv")).exists(),
            "заголовка нет, а сброс вернулся"
        );
        let segs = crate::segments::Segments::load(&d).expect("индекс");
        assert_eq!(segs.docs(), 700);
        std::fs::remove_dir_all(&d).ok();
    }

    /// Гашение находит документ, чей буфер уехал в фоновую запись.
    ///
    /// Та самая дыра, ради которой гашение дожидается записи. Без ожидания
    /// `kill_buffered` смотрит в свежий буфер, где документа уже нет, а гашение
    /// по сегментам — в состав, где сегмента ещё нет: удаление молча не
    /// срабатывает, а клиенту сказано «удалено».
    #[test]
    fn a_delete_finds_a_document_whose_buffer_is_still_being_written() {
        let d = dir("kill");
        let mut ix = Indexer::new(&d, vec!["body".into()], vec![1.0], 200);
        ix.background(std::sync::Arc::new(std::sync::Mutex::new(())));
        // Ровно на границе: последний документ переполнит буфер, и он уедет.
        fill(&mut ix, 0, 200);
        // Документ d000005 лежит в улетевшем буфере. Гасим сразу же.
        let killed = ix.kill_buffered("d000005");
        // В буфере его уже нет — он в сегменте, и это верный ответ. Важно
        // другое: сегмент к этому мигу обязан быть на диске и в составе, иначе
        // гашению по сегментам его тоже негде найти.
        assert_eq!(killed, 0, "документ ещё в буфере — ожидание не сработало");
        assert_eq!(ix.segments(), 1, "сегмент не дописан к моменту гашения");
        let segs = crate::segments::Segments::load(&d).expect("индекс");
        let refs: Vec<&crate::index::Index> = segs.list.iter().map(|a| a.as_ref()).collect();
        let out = crate::maintain::delete_in(&refs, &["d000005".to_string()]).expect("гашение");
        assert_eq!(out.killed, 1, "документ не нашёлся в сегменте");
        std::fs::remove_dir_all(&d).ok();
    }

    #[test]
    fn replacing_fragment_matches_sequential_replacement_and_reuses_cleanly() {
        let a = dir("replace-fragment-sequential");
        let b = dir("replace-fragment-absorbed");
        for (path, fragments) in [(&a, false), (&b, true)] {
            let mut ix = Indexer::new(path, vec!["body".into()], vec![1.0], 100_000);
            ix.add("disk", &["disk-old"]);
            ix.flush_now();
            ix.add("buffer", &["buffer-old"]);
            ix.begin_atomic_batch();
            let replacements = [
                ("disk", "disk-new"),
                ("buffer", "buffer-first"),
                ("buffer", "buffer-last"),
                ("fresh", "fresh-first"),
                ("fresh", "fresh-last"),
            ];
            let killed = if fragments {
                let mut fragment = ix.detached();
                for (id, body) in replacements {
                    fragment.replace(id, &[body]);
                }
                assert_eq!(fragment.buffered_dead(), 2);
                let killed = ix.absorb_replacing(&mut fragment);
                assert_eq!(fragment.staged(), 0);
                assert!(fragment.superseded_now().is_empty());
                assert_eq!(ix.absorb_replacing(&mut fragment), 0);
                fragment.replace("reuse", &["reused"]);
                assert_eq!(ix.absorb_replacing(&mut fragment), 0);
                assert!(fragment.superseded_now().is_empty());
                killed
            } else {
                let killed =
                    replacements.into_iter().map(|(id, body)| ix.replace(id, &[body])).sum();
                ix.replace("reuse", &["reused"]);
                killed
            };
            assert_eq!(killed, 3, "two fragment revisions and one existing buffer copy");
            ix.finish_atomic_batch();
            ix.flush_now();
            let segments = crate::Segments::load(path).unwrap();
            let refs: Vec<_> = segments.list.iter().map(|index| index.as_ref()).collect();
            for (keeper, ids) in ix.take_superseded() {
                crate::maintain::supersede_in(&refs, &keeper, &ids).unwrap();
            }
            let reloaded = crate::Segments::load(path).unwrap();
            let mut live: Vec<_> = reloaded
                .list
                .iter()
                .flat_map(|index| {
                    (0..index.docs as u32)
                        .filter(|&doc| index.is_live(doc))
                        .map(|doc| String::from_utf8(index.fetch(doc, 0).unwrap()).unwrap())
                })
                .collect();
            live.sort();
            assert_eq!(live, ["buffer-last", "disk-new", "fresh-last", "reused"]);
        }
        assert_eq!(listing(&a), listing(&b));
        for segment in listing(&a) {
            let first = format!("{a}/{segment}");
            for entry in std::fs::read_dir(&first).unwrap() {
                let name = entry.unwrap().file_name();
                assert_eq!(
                    std::fs::read(std::path::Path::new(&first).join(&name)).unwrap(),
                    std::fs::read(std::path::Path::new(&format!("{b}/{segment}")).join(&name))
                        .unwrap(),
                    "different segment bytes: {segment}/{name:?}"
                );
            }
        }
        std::fs::remove_dir_all(a).unwrap();
        std::fs::remove_dir_all(b).unwrap();
    }

    #[test]
    fn unrelated_replacement_does_not_wait_for_flying_manifest() {
        let d = dir("unrelated-replace");
        let layout = std::sync::Arc::new(std::sync::Mutex::new(()));
        let mut ix = Indexer::new(&d, vec!["body".into()], vec![1.0], 100_000);
        ix.background(layout.clone());
        ix.add("flying", &["first"]);
        let blocked = layout.lock().unwrap();
        ix.flush();
        assert!(ix.flush_inflight());
        let (done, received) = std::sync::mpsc::channel();
        let worker = std::thread::spawn(move || {
            let mut fragment = ix.detached();
            fragment.replace("different", &["second"]);
            assert_eq!(ix.absorb_replacing(&mut fragment), 0);
            done.send(ix).unwrap();
        });
        // Completion while publication is locked proves the replacement
        // does not wait on the disk job. Release before asserting on timeout.
        let result = received.recv_timeout(std::time::Duration::from_secs(5));
        drop(blocked);
        let mut ix = result.expect("unrelated replacement waited for flying flush");
        worker.join().unwrap();
        assert!(ix.flush_inflight());
        let doc = ix.buffered_doc("different").unwrap();
        assert_eq!(ix.buffered_at(doc, 0).as_deref(), Some("second"));
        ix.flush_now();
        let segments = crate::Segments::load(&d).unwrap();
        assert_eq!(segments.docs(), 2);
        drop(ix);
        std::fs::remove_dir_all(d).unwrap();
    }

    #[test]
    fn matching_replacement_waits_for_flying_manifest_and_keeps_only_new_version() {
        let d = dir("matching-replace");
        let layout = std::sync::Arc::new(std::sync::Mutex::new(()));
        let mut ix = Indexer::new(&d, vec!["body".into()], vec![1.0], 100_000);
        ix.background(layout.clone());
        ix.add("same", &["old"]);
        let blocked = layout.lock().unwrap();
        ix.flush();
        assert!(ix.flush_inflight());
        assert!(ix.inflight_id_hashes.binary_search(&crate::bloom::hash("same")).is_ok());
        let (started, ready) = std::sync::mpsc::channel();
        let (done, received) = std::sync::mpsc::channel();
        let worker = std::thread::spawn(move || {
            started.send(()).unwrap();
            let mut fragment = ix.detached();
            fragment.replace("same", &["new"]);
            assert_eq!(ix.absorb_replacing(&mut fragment), 0);
            done.send(ix).unwrap();
        });
        ready.recv().unwrap();
        let premature = received.recv_timeout(std::time::Duration::from_millis(100));
        drop(blocked);
        assert!(matches!(premature, Err(std::sync::mpsc::RecvTimeoutError::Timeout)));
        let mut ix = received.recv_timeout(std::time::Duration::from_secs(5)).unwrap();
        worker.join().unwrap();
        assert!(!ix.flush_inflight());
        let doc = ix.buffered_doc("same").unwrap();
        assert_eq!(ix.buffered_at(doc, 0).as_deref(), Some("new"));
        ix.flush_now();
        let mut segments = crate::Segments::load(&d).unwrap();
        for (keeper, ids) in ix.take_superseded() {
            let refs: Vec<_> = segments.list.iter().map(|index| index.as_ref()).collect();
            crate::maintain::supersede_in(&refs, &keeper, &ids).unwrap();
        }
        segments = crate::Segments::load(&d).unwrap();
        let live: Vec<_> = segments
            .list
            .iter()
            .flat_map(|index| {
                (0..index.docs as u32)
                    .filter(|&doc| index.is_live(doc))
                    .map(|doc| String::from_utf8(index.fetch(doc, 0).unwrap()).unwrap())
            })
            .collect();
        assert_eq!(live, ["new"]);
        drop(ix);
        std::fs::remove_dir_all(d).unwrap();
    }

    /// Живых буферов не больше двух: в полёте всегда одно задание.
    ///
    /// Проверяется не памятью, а признаком: перед передачей нового буфера
    /// прошлый обязан быть забран. Иначе очередь росла бы, и с ней память
    /// приёма — на боевом сегменте в миллион документов это гигабайты.
    #[test]
    fn only_one_flush_is_ever_in_flight() {
        let d = dir("inflight");
        let mut ix = Indexer::new(&d, vec!["body".into()], vec![1.0], 200);
        ix.background(std::sync::Arc::new(std::sync::Mutex::new(())));
        for round in 0..12 {
            fill(&mut ix, round * 200, 200);
            let f = ix.flusher.as_ref().expect("писатель");
            assert!(!f.inflight || ix.segments() >= round, "заданий в полёте больше одного");
        }
        ix.flush_now();
        assert_eq!(ix.segments(), 12);
        std::fs::remove_dir_all(&d).ok();
    }
}

/// Раскладка колонки выбирается по данным сегмента, а не по объявлению.
#[cfg(test)]
mod layout_tests {
    use super::*;
    use crate::column::{Layout, Presence};

    fn build(name: &str, rows: &[(&str, &str, &str)]) -> String {
        let dir = std::env::temp_dir().join(format!("svindb-layout-{name}"));
        let dir = dir.to_string_lossy().to_string();
        std::fs::remove_dir_all(&dir).ok();
        let mut ix = Indexer::typed(
            &dir,
            vec!["title".into(), "always".into(), "never".into()],
            vec![1.0, 1.0, 1.0],
            vec![Kind::Text, Kind::Int32, Kind::Int32],
            1_000_000,
        );
        for (i, (t, a, n)) in rows.iter().enumerate() {
            ix.add(&format!("d{i}"), &[t, a, n]);
        }
        ix.flush_now();
        dir
    }

    /// Есть ли у сегмента такой кусок.
    ///
    /// Спрашивается у источника, а не у файловой системы: у упакованного
    /// сегмента отдельного файла у куска нет вовсе, и `Path::exists` отвечал бы
    /// «нет» на каждый — то есть подтверждал бы «файла быть не должно» даром.
    pub(super) fn there(seg: &str, f: &str) -> bool {
        let head = crate::index::read_head(seg).expect("заголовок");
        crate::container::SegmentSource::of(seg, head.container).expect("источник").has(f)
    }

    /// Поле без единого значения не получает ни одного файла, а заполненное
    /// целиком — не платит за биты присутствия.
    #[test]
    fn an_empty_field_costs_nothing_and_a_full_one_costs_less() {
        let rows: Vec<(&str, &str, &str)> =
            (0..300).map(|_| ("текст документа", "42", "")).collect();
        let dir = build("mixed", &rows);
        let seg = format!("{dir}/seg0000");

        let head = crate::index::read_head(&seg).expect("заголовок читается");
        let by = |n: &str| head.fields.iter().find(|f| f.name == n).expect("поле объявлено");
        assert_eq!(by("always").layout, Layout::Dense);
        assert_eq!(by("always").presence, Presence::All, "значение у каждого документа");
        assert_eq!(by("never").layout, Layout::None, "ни одного значения");
        // У текстового поля колонки не бывает вовсе, и заголовок обязан
        // говорить это прямо, а не обещать раскладку, которой нет.
        assert_eq!(by("title").layout, Layout::None);

        assert!(there(&seg, "always.col") && there(&seg, "always.cmeta"));
        assert!(!there(&seg, "always.has"), "биты присутствия у полного поля");
        for ext in ["col", "cmeta", "has", "bkt", "bktidx"] {
            assert!(!there(&seg, &format!("never.{ext}")), "пустое поле оставило never.{ext}");
            assert!(!there(&seg, &format!("title.{ext}")), "текстовое оставило title.{ext}");
        }

        let ix = crate::index::load(&seg).expect("сегмент открылся");
        let col = ix.fields[1].column.as_ref().expect("колонка полного поля");
        assert!(col.has(0) && col.has(299), "полное поле потеряло присутствие");
        assert!(!col.has(300), "за границей сегмента значения быть не может");
        assert_eq!(col.get(7), Some(42));
        assert!(ix.fields[2].column.is_none(), "у пустого поля колонки нет");
        assert_eq!(crate::check::check(&dir, crate::check::Depth::Full).broken(), 0);
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn a_field_with_holes_returns_exactly_its_values() {
        let rows: Vec<(&str, &str, &str)> =
            (0..300).map(|i| ("текст", if i % 3 == 0 { "7" } else { "" }, "")).collect();
        let dir = build("holes", &rows);
        let seg = format!("{dir}/seg0000");
        let head = crate::index::read_head(&seg).expect("заголовок");
        let f = head.fields.iter().find(|f| f.name == "always").unwrap();
        assert_ne!(f.layout, Layout::None, "у поля со значениями раскладка есть");
        // Раскладка и файлы обязаны сходиться: разреженная не держит ни битов
        // присутствия, ни плотных данных.
        if f.layout == Layout::Sparse {
            assert!(there(&seg, "always.scol") && there(&seg, "always.smeta"));
            assert!(!there(&seg, "always.has") && !there(&seg, "always.col"));
        } else {
            assert!(there(&seg, "always.col") && there(&seg, "always.has"));
        }

        let ix = crate::index::load(&seg).expect("сегмент открылся");
        let col = ix.fields[1].column.as_ref().expect("колонка");
        for d in 0..300u32 {
            assert_eq!(col.get(d), if d % 3 == 0 { Some(7) } else { None }, "документ {d}");
            assert_eq!(col.has(d), d % 3 == 0, "присутствие документа {d}");
        }
        assert_eq!(crate::check::check(&dir, crate::check::Depth::Full).broken(), 0);
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Очень редкое поле ложится разреженно, плотное — плотно.
    ///
    /// Порог не назначен, а посчитан: `choose` меряет обе цены и берёт
    /// разреженную только там, где она вдвое дешевле. Проверяются оба края.
    #[test]
    fn the_layout_follows_the_measured_cost() {
        // Одно значение на тысячу: плотная платила бы за все девятьсот
        // девяносто девять пустых.
        let rows: Vec<(&str, &str, &str)> =
            (0..2000).map(|i| ("текст", if i % 1000 == 0 { "12345" } else { "" }, "")).collect();
        let dir = build("rare", &rows);
        let head = crate::index::read_head(&format!("{dir}/seg0000")).expect("заголовок");
        let f = head.fields.iter().find(|f| f.name == "always").unwrap();
        assert_eq!(f.layout, Layout::Sparse, "редкое поле осталось плотным");
        let ix = crate::index::load(&format!("{dir}/seg0000")).expect("сегмент");
        let col = ix.fields[1].column.as_ref().expect("колонка");
        for d in 0..2000u32 {
            assert_eq!(col.get(d), (d % 1000 == 0).then_some(12345), "документ {d}");
        }
        std::fs::remove_dir_all(&dir).ok();

        // Заполненное поле с широкими значениями: разреженной платить нечем.
        let vals: Vec<String> = (0..2000).map(|i| (i * 7919).to_string()).collect();
        let rows: Vec<(&str, &str, &str)> =
            vals.iter().map(|v| ("текст", v.as_str(), "")).collect();
        let dir = build("full", &rows);
        let head = crate::index::read_head(&format!("{dir}/seg0000")).expect("заголовок");
        let f = head.fields.iter().find(|f| f.name == "always").unwrap();
        assert_eq!(f.layout, Layout::Dense, "заполненное поле ушло в разреженную");
        assert_eq!(f.presence, Presence::All, "у заполненного поля битов быть не должно");
        std::fs::remove_dir_all(&dir).ok();
    }
}

/// Полей может быть больше двухсот пятидесяти шести.
#[cfg(test)]
mod wide_schema_tests {
    use super::*;

    /// Триста полей: каждое находит своё слово и **только** своё.
    ///
    /// Оценка занятого буфером сходится с настоящим ростом памяти.
    ///
    /// Прежде порог считал только длину текста, и это была не мелкая
    /// неточность: постинги у документа в полтораста токенов весят больше
    /// самого текста, а на широкой схеме заголовки `String` весят больше и
    /// того. Порог в 256 МБ срабатывал, когда буфер занимал два-три гигабайта.
    ///
    /// Мерится настоящий прирост от собственного счётчика выделений: сравнивать
    /// оценку с `RSS` нельзя — распределитель отдаёт страницы когда захочет, и
    /// проверка мигала бы.
    ///
    /// Допуск двукратный, и он честный: оценка **занижена** намеренно — не
    /// считает ни запаса ёмкости векторов, ни служебных ячеек хеш-карты.
    /// Завышать порог опаснее, чем занижать: занижение даёт лишний сегмент,
    /// завышение — своп.
    #[test]
    fn the_flush_estimate_tracks_real_growth() {
        let dir = std::env::temp_dir().join("svindb-flush-estimate");
        let dir = dir.to_string_lossy().to_string();
        std::fs::remove_dir_all(&dir).ok();

        let names: Vec<String> = ["текст", "метка"].iter().map(|s| s.to_string()).collect();
        let mut ix =
            Indexer::typed(&dir, names, vec![1.0, 1.0], vec![Kind::Text, Kind::Keyword], 1_000_000);
        ix.set_flush_bytes(0);

        // Слова разные у каждого документа: словарь растёт, как на настоящем
        // корпусе. Повторяй они друг друга — постинги стоили бы впятеро меньше,
        // и проверка ничего бы не проверяла.
        let text = |d: usize| (0..150).map(|w| format!("сл{d}_{w}")).collect::<Vec<_>>().join(" ");
        let took = crate::alloc::watch(|| {
            for d in 0..2000usize {
                ix.add(&format!("d{d}"), &[&text(d), "метка-один"]);
            }
        });
        let guess = ix.buffered_bytes();
        // Не просто «близко», а близко **сверху**: недооценка означает, что
        // буфер перерастёт отведённое и узел уйдёт в своп, а переоценка — лишь
        // лишний сегмент, который потом укрупнят.
        assert!(guess >= took, "оценка {guess} ниже настоящих {took} байт — это своп");
        assert!(guess <= took * 2, "оценка {guess} против {took} — завышена больше чем вдвое");
        // И она не должна быть смешной: сумма длин текста здесь около 2.4 МБ,
        // а буфер занимает кратно больше. Прежний счёт этого не видел.
        let plain: usize = (0..2000usize).map(|d| text(d).len() + 11 + 2).sum();
        assert!(
            guess > plain * 2,
            "оценка {guess} едва отличается от суммы длин {plain} — учтён только текст?"
        );
        println!(
            "буфер: занято {took} Б, оценка {guess} Б, запрошено {} Б; \
             прежний счёт по тексту дал бы {plain} Б — занижение в {:.1} раза",
            ix.buffered_bytes() * 100 / SLACK,
            took as f64 / plain as f64
        );
        std::fs::remove_dir_all(&dir).ok();
    }

    /// То же на широкой разрежённой схеме — там, где прежний счёт врал сильнее
    /// всего.
    ///
    /// Документ трогает три поля из ста, но заголовок `String` заводится на
    /// **каждое** объявленное. Именно это делает широкую схему дорогой в
    /// памяти, и именно этого счёт по длине текста не видел вовсе.
    #[test]
    fn the_estimate_holds_on_a_wide_sparse_schema() {
        const N: usize = 100;
        let dir = std::env::temp_dir().join("svindb-flush-estimate-wide");
        let dir = dir.to_string_lossy().to_string();
        std::fs::remove_dir_all(&dir).ok();

        let names: Vec<String> = (0..N).map(|f| format!("п{f}")).collect();
        let mut ix = Indexer::typed(&dir, names, vec![1.0; N], vec![Kind::Keyword; N], 1_000_000);
        ix.set_flush_bytes(0);

        let took = crate::alloc::watch(|| {
            let mut vals = vec![String::new(); N];
            for d in 0..3000usize {
                for v in vals.iter_mut() {
                    v.clear();
                }
                for k in 0..3 {
                    vals[(d * 7 + k * 31) % N] = format!("з{}", d % 50);
                }
                let refs: Vec<&str> = vals.iter().map(String::as_str).collect();
                ix.add(&format!("w{d}"), &refs);
            }
        });
        let guess = ix.buffered_bytes();
        assert!(guess >= took, "оценка {guess} ниже настоящих {took} байт — это своп");
        assert!(guess <= took * 2, "оценка {guess} против {took} — завышена больше чем вдвое");
        println!("широкая схема: занято {took} Б, оценка {guess} Б");
        std::fs::remove_dir_all(&dir).ok();
    }

    /// `noindex` не платит ни списком, ни колонкой, но содержимое отдаёт.
    ///
    /// Ради этого признак и заводится: у схем парсера девять полей — сырой
    /// HTML, LaTeX, vCard — которые возвращают целиком и не спрашивают никогда.
    /// Индексировать их значит платить словарём и позициями за то, чем никто не
    /// воспользуется; а `nostore` — обратное и не подходит: содержимое нужно.
    #[test]
    fn a_noindex_field_is_stored_but_costs_nothing_to_search() {
        let names: Vec<String> =
            ["текст", "сырое", "число"].iter().map(|s| s.to_string()).collect();
        let kinds = vec![Kind::Text, Kind::Text, Kind::Int64];

        let mut sizes = Vec::new();
        for (tag, searched) in [("all", vec![true, true, true]), ("off", vec![true, false, false])]
        {
            let dir = std::env::temp_dir().join(format!("svindb-noindex-{tag}"));
            let dir = dir.to_string_lossy().to_string();
            std::fs::remove_dir_all(&dir).ok();
            let mut ix =
                Indexer::typed(&dir, names.clone(), vec![1.0; 3], kinds.clone(), 1_000_000);
            ix.set_searched(searched);
            for d in 0..200usize {
                ix.add(&format!("d{d}"), &["общее слово", "редкое сырое слово", &d.to_string()]);
            }
            ix.flush_now();

            let seg = std::fs::read_dir(&dir)
                .expect("каталог")
                .filter_map(|e| e.ok())
                .map(|e| e.path())
                .find(|p| p.is_dir())
                .expect("сегмент");
            let total: u64 = std::fs::read_dir(&seg)
                .expect("сегмент")
                .filter_map(|e| e.ok())
                .filter_map(|e| e.metadata().ok())
                .map(|m| m.len())
                .sum();
            let head = crate::index::read_head(&seg.to_string_lossy()).expect("заголовок");
            sizes.push((seg.clone(), total, head.terms));
            let by = |n: &str| head.fields.iter().find(|f| f.name == n).expect("поле");
            assert!(by("текст").searched, "{tag}: обычное поле обязано искаться");
            let off = tag == "off";
            assert_eq!(by("сырое").searched, !off, "{tag}: признак не дошёл до заголовка");
            assert_eq!(by("число").searched, !off);
            // Содержимое обязано отдаваться в обоих случаях — иначе `noindex`
            // ничем не отличался бы от `nostore`, а он его противоположность.
            assert!(by("сырое").stored, "{tag}: содержимое обязано храниться");
            assert!(
                by("число").stored || !off,
                "{tag}: у точного числа без колонки печатать обратно нечего, кроме хранимого"
            );
        }

        let (_, with, terms_on) = sizes[0].clone();
        let (seg_off, without, terms_off) = sizes[1].clone();
        assert!(without < with, "noindex обязан быть дешевле: {without} против {with} байт");
        // Ни одного файла списков и колонок у выключенных полей.
        for name in ["сырое", "число"] {
            for ext in ["col", "cmeta", "has", "scol", "smeta", "bkt"] {
                let p = seg_off.join(format!("{name}.{ext}"));
                assert!(!p.exists(), "{name}.{ext} не должно существовать: {p:?}");
            }
        }
        // Списков у выключенных полей нет вовсе: словарь на сегмент один, и
        // разницу видно по числу списков в нём.
        assert!(
            terms_off < terms_on,
            "списков обязано стать меньше: {terms_off} против {terms_on}"
        );
    }

    /// Номер поля в словаре был байтом, и на 257-м поле он свернулся бы в ноль,
    /// склеив слова двух разных полей. Не отказом — просто чужой выдачей.
    /// Потолок в 256 полей для базы с вложенными документами не годится: у
    /// Elasticsearch умолчание — тысяча полей на индекс.
    #[test]
    fn three_hundred_fields_keep_their_words_apart() {
        const N: usize = 300;
        let dir = std::env::temp_dir().join("svindb-wide-schema");
        let dir = dir.to_string_lossy().to_string();
        std::fs::remove_dir_all(&dir).ok();

        let names: Vec<String> = (0..N).map(|f| format!("f{f}")).collect();
        let mut ix =
            Indexer::typed(&dir, names.clone(), vec![1.0; N], vec![Kind::Text; N], 1_000_000);
        // Сто пятьдесят документов, а не четыре: у списка короче блока
        // потолок не хранится вовсе, и проверка целостности прошла бы вхолостую.
        //
        // У каждого поля своё слово плюс общее у всех: так проверяется и
        // разделение полей, и то, что общее слово не потерялось ни в одном.
        for d in 0..150usize {
            let values: Vec<String> =
                (0..N).map(|f| format!("слово{f} общее документ{d}")).collect();
            let refs: Vec<&str> = values.iter().map(|s| s.as_str()).collect();
            ix.add(&format!("d{d}"), &refs);
        }
        ix.flush_now();
        let seg = format!("{dir}/seg0000");
        let index = crate::index::load(&seg).expect("сегмент открылся");
        assert_eq!(index.fields.len(), N);

        for f in 0..N {
            // Своё слово находится в своём поле.
            let own = index
                .dict
                .lookup(f as u32, &format!("слово{f}"))
                .unwrap_or_else(|| panic!("поле {f}: своё слово не найдено"));
            assert_eq!(index.t_df(own as usize), 150, "поле {f}: не все документы");
            // И не находится ни в каком другом — проверяются соседи по номеру и
            // те, что отличаются на кратное 256: именно они склеились бы.
            for other in [f + 1, f + 255, f + 256, f + 257] {
                if other >= N || other == f {
                    continue;
                }
                assert!(
                    index.dict.lookup(other as u32, &format!("слово{f}")).is_none(),
                    "слово поля {f} нашлось в поле {other}"
                );
            }
            // Общее слово есть в каждом поле, и это разные списки.
            assert!(index.dict.lookup(f as u32, "общее").is_some(), "поле {f}: нет общего слова");
        }

        // Списки разных полей не должны совпадать номерами.
        let a = index.dict.lookup(0, "общее").unwrap();
        let b = index.dict.lookup(299, "общее").unwrap();
        assert_ne!(a, b, "общее слово двух полей получило один список");

        assert_eq!(crate::check::check(&dir, crate::check::Depth::Full).broken(), 0);
        std::fs::remove_dir_all(&dir).ok();
    }
}

/// Приём массивов: слот-пространство от документа до сегмента.
#[cfg(test)]
mod cells_tests {
    use super::*;

    /// Предварительная токенизация ячейкового пути меняет только место работы,
    /// но не формат сегмента и не presence. Это обязательный инвариант нового
    /// lossless приёма плоских документов.
    #[test]
    fn pretokenized_cells_are_byte_identical_and_keep_presence() {
        let root = std::env::temp_dir().join(format!("svindb-cells-pre-{}", std::process::id()));
        std::fs::remove_dir_all(&root).ok();
        let kinds = vec![Kind::Text, Kind::Keyword];
        let make = |tag: &str| {
            let dir = root.join(tag).to_string_lossy().to_string();
            let mut ix = Indexer::typed(
                &dir,
                vec!["text".into(), "exact".into()],
                vec![1.0, 1.0],
                kinds.clone(),
                1_000_000,
            );
            ix.set_groups(vec![0, 0], vec![String::new()]);
            ix
        };
        let docs = [
            ("missing", "Первый текст", None),
            ("empty", "", Some("")),
            ("value", "Третий текст", Some("MiXeD")),
        ];

        let mut plain = make("plain");
        let mut prepared = make("prepared");
        let analyzer = crate::analyze::Simple;
        for (id, text, exact) in docs {
            let mut cells = vec![Cell { field: 0, slot: 0, text }];
            if let Some(exact) = exact {
                cells.push(Cell { field: 1, slot: 0, text: exact });
            }
            plain.add_cells(id, &[1], &cells);

            let mut words = vec![crate::analyze::Tokens::default(); 2];
            Indexer::<crate::analyze::Simple>::field_tokens(
                &analyzer,
                Kind::Text,
                text,
                &mut words[0],
            );
            if let Some(exact) = exact {
                Indexer::<crate::analyze::Simple>::field_tokens(
                    &analyzer,
                    Kind::Keyword,
                    exact,
                    &mut words[1],
                );
            }
            prepared.add_cells_pre(id, &[1], &cells, Some(words.as_mut_slice()));
        }
        plain.flush_now();
        prepared.flush_now();

        let left = std::fs::read(root.join("plain/seg0000").join(crate::container::FILE))
            .expect("обычный сегмент");
        let right = std::fs::read(root.join("prepared/seg0000").join(crate::container::FILE))
            .expect("готовый сегмент");
        assert_eq!(left, right, "предварительная токенизация изменила байты сегмента");
        let checked = root.join("prepared").to_string_lossy().to_string();
        assert_eq!(crate::check::check(&checked, crate::check::Depth::Full).broken(), 0);
        std::fs::remove_dir_all(root).ok();
    }

    /// Плоский документ через `add_cells` даёт **тот же сегмент**, что через
    /// `add`.
    #[test]
    fn a_flat_document_takes_the_same_path_both_ways() {
        let rows: Vec<(String, String)> =
            (0..300).map(|i| (format!("документ номер {i} общее"), (i * 3).to_string())).collect();

        let mk = |name: &str| {
            let d = std::env::temp_dir().join(format!("svindb-cells-{name}"));
            let d = d.to_string_lossy().to_string();
            std::fs::remove_dir_all(&d).ok();
            Indexer::typed(
                &d,
                vec!["text".into(), "num".into()],
                vec![1.0, 1.0],
                vec![Kind::Text, Kind::Int32],
                1_000_000,
            )
        };

        let mut a = mk("plain");
        for (i, (t, n)) in rows.iter().enumerate() {
            a.add(&format!("d{i}"), &[t, n]);
        }
        a.flush_now();

        let mut b = mk("cells");
        b.set_groups(vec![0, 0], vec![String::new()]);
        for (i, (t, n)) in rows.iter().enumerate() {
            b.add_cells(
                &format!("d{i}"),
                &[1],
                &[Cell { field: 0, slot: 0, text: t }, Cell { field: 1, slot: 0, text: n }],
            );
        }
        b.flush_now();

        assert_eq!(a.total_docs, rows.len() as u64);
        assert_eq!(
            b.total_docs,
            rows.len() as u64,
            "профиль вложенного приёма не считает документы"
        );

        let da = std::env::temp_dir().join("svindb-cells-plain").to_string_lossy().to_string();
        let db = std::env::temp_dir().join("svindb-cells-cells").to_string_lossy().to_string();
        for f in ["postings.bin", "terms.bin", "dict.blob", "norms.bin", "num.col", "pos.bin"] {
            let x = std::fs::read(format!("{da}/seg0000/{f}")).unwrap_or_default();
            let y = std::fs::read(format!("{db}/seg0000/{f}")).unwrap_or_default();
            assert_eq!(x, y, "файл {f} разошёлся между `add` и `add_cells`");
        }
        std::fs::remove_dir_all(&da).ok();
        std::fs::remove_dir_all(&db).ok();
    }

    /// Массив: слоты не съезжают от пропущенного поля, значения на своих местах.
    #[test]
    fn a_missing_field_inside_an_element_does_not_shift_the_slots() {
        let dir = std::env::temp_dir().join("svindb-cells-holes");
        let dir = dir.to_string_lossy().to_string();
        std::fs::remove_dir_all(&dir).ok();
        let mut ix = Indexer::typed(
            &dir,
            vec!["title".into(), "emoji".into(), "count".into()],
            vec![1.0, 1.0, 1.0],
            vec![Kind::Text, Kind::Keyword, Kind::Int32],
            1_000_000,
        );
        // Поля `emoji` и `count` — в группе 1, путь `reactions`.
        ix.set_groups(vec![0, 1, 1], vec![String::new(), "reactions".into()]);

        // У каждого документа три элемента; у среднего нет эмодзи.
        for d in 0..200usize {
            ix.add_cells(
                &format!("d{d}"),
                &[1, 3],
                &[
                    Cell { field: 0, slot: 0, text: "документ" },
                    Cell { field: 1, slot: 0, text: "up" },
                    Cell { field: 2, slot: 0, text: "10" },
                    // слот 1: только счётчик
                    Cell { field: 2, slot: 1, text: "20" },
                    Cell { field: 1, slot: 2, text: "fire" },
                    Cell { field: 2, slot: 2, text: "30" },
                ],
            );
        }
        ix.flush_now();

        let seg = format!("{dir}/seg0000");
        let index = crate::index::load(&seg).expect("сегмент открылся");
        assert_eq!(index.docs, 200);
        assert_eq!(index.slots.len(), 2, "две группы");
        assert_eq!(index.slots[1].units(), 600, "три слота на документ");

        // Колонка счётчика адресуется ординалами: у документа d слоты 3d..3d+3.
        let col = index.fields[2].column.as_ref().expect("колонка счётчика");
        for d in 0..200u32 {
            let (from, n) = index.slots[1].range(d);
            assert_eq!((from, n), (d * 3, 3), "отрезок документа {d}");
            assert_eq!(col.get(from), Some(10));
            assert_eq!(col.get(from + 1), Some(20), "слот без эмодзи потерял счётчик");
            assert_eq!(col.get(from + 2), Some(30));
        }

        // Позиции эмодзи — номера элементов, с пропуском среднего.
        let up = index.dict.lookup(1, &keyword_term("up", true)).expect("эмодзи в словаре");
        let fire = index.dict.lookup(1, &keyword_term("fire", true)).expect("эмодзи в словаре");
        let mut poss = Vec::new();
        let c = index.cursor(up, 1, 1.0);
        c.positions(&mut poss);
        assert_eq!(poss, vec![0], "первый элемент");
        let c = index.cursor(fire, 1, 1.0);
        c.positions(&mut poss);
        assert_eq!(poss, vec![2], "третий элемент, а не второй");

        assert_eq!(crate::check::check(&dir, crate::check::Depth::Full).broken(), 0);
        std::fs::remove_dir_all(&dir).ok();
    }
}

/// Буфер приёма отдаёт ядру ёмкость, набранную по худшему случаю.
#[cfg(test)]
mod slots_hash_tests {
    use super::*;

    #[test]
    fn prepared_replacements_match_flat_and_sparse_replacements() {
        let root = std::env::temp_dir().join(format!("svindb-replace-pre-{}", std::process::id()));
        std::fs::remove_dir_all(&root).ok();
        for sparse in [false, true] {
            let make = |name: &str| {
                Indexer::typed_stored(
                    &root.join(format!("{sparse}-{name}")).to_string_lossy(),
                    vec!["text".into()],
                    vec![1.0],
                    vec![Kind::Text],
                    vec![true],
                    1_000_000,
                )
            };
            let mut plain = make("plain");
            let mut prepared = make("prepared");
            plain.add("id", &["old"]);
            prepared.add("id", &["old"]);
            let mut words = vec![crate::analyze::Tokens::default()];
            Indexer::<Simple>::field_tokens(&Simple, Kind::Text, "Новый текст", &mut words[0]);
            if sparse {
                let cells = [Cell { field: 0, slot: 0, text: "Новый текст" }];
                assert_eq!(plain.replace_cells("id", &[1], &cells), 1);
                assert_eq!(prepared.replace_cells_pre("id", &[1], &cells, Some(&mut words)), 1);
            } else {
                assert_eq!(plain.replace("id", &["Новый текст"]), 1);
                assert_eq!(prepared.replace_pre("id", &["Новый текст"], Some(&mut words)), 1);
            }
            assert_eq!(prepared.buffered_value("id", 0).as_deref(), Some("Новый текст"));
            plain.flush_now();
            prepared.flush_now();
            let file = |name: &str| {
                root.join(format!("{sparse}-{name}/seg0000")).join(crate::container::FILE)
            };
            assert_eq!(
                std::fs::read(file("plain")).unwrap(),
                std::fs::read(file("prepared")).unwrap()
            );
        }
        std::fs::remove_dir_all(root).ok();
    }

    #[test]
    fn two_hundred_thousand_empty_ids_do_not_enter_the_probe_table() {
        for count in [50_000, 100_000, 200_000] {
            let ids = vec![String::new(); count];
            let mut slots = Slots::default();
            let started = std::time::Instant::now();
            for doc in 0..count {
                slots.insert(crate::bloom::hash(""), doc as u32, &ids);
            }
            eprintln!("empty IDs: {count}, insert: {:?}", started.elapsed());
            // A structural complexity regression: insertion does no hashing-table
            // probes or rehashes regardless of the number of empty IDs.
            assert!(slots.cells.is_empty());
            assert_eq!(slots.filled, 0);
            let mut found = Vec::new();
            slots.find(crate::bloom::hash(""), "", &ids, &mut found);
            assert_eq!(found, (0..count as u32).collect::<Vec<_>>());
        }
    }

    #[test]
    fn empty_ids_survive_growth_and_clear_without_hiding_named_ids() {
        let mut slots = Slots::default();
        let mut ids = Vec::new();
        for doc in 0..256u32 {
            let id = if doc % 2 == 0 { String::new() } else { format!("id-{doc}") };
            let h = crate::bloom::hash(&id);
            ids.push(id);
            slots.insert(h, doc, &ids);
        }
        let mut found = Vec::new();
        slots.find(crate::bloom::hash(""), "", &ids, &mut found);
        assert_eq!(found, (0..256).step_by(2).collect::<Vec<_>>());
        for doc in (1..256u32).step_by(2) {
            found.clear();
            slots.find(
                crate::bloom::hash(&ids[doc as usize]),
                &ids[doc as usize],
                &ids,
                &mut found,
            );
            assert_eq!(found, vec![doc]);
        }
        slots.clear();
        found.clear();
        slots.find(crate::bloom::hash(""), "", &ids, &mut found);
        assert!(found.is_empty());
        assert_eq!(slots.filled, 0);
    }

    #[test]
    fn empty_id_lookup_and_deletion_keep_the_existing_buffer_semantics() {
        let dir = std::env::temp_dir().join(format!("svindb-empty-id-{}", std::process::id()));
        std::fs::remove_dir_all(&dir).ok();
        let mut ix = Indexer::typed_stored(
            &dir.to_string_lossy(),
            vec!["text".into()],
            vec![1.0],
            vec![Kind::Text],
            vec![true],
            1_000_000,
        );
        ix.add("", &["first"]);
        ix.add("named", &["named"]);
        ix.add_cells("", &[1], &[Cell { field: 0, slot: 0, text: "second" }]);
        assert_eq!(ix.buffered_value("", 0).as_deref(), Some("second"));
        assert_eq!(ix.kill_buffered(""), 2);
        assert_eq!(ix.kill_buffered(""), 0);
        assert!(ix.buffered_doc("").is_none());
        assert_eq!(ix.buffered_value("named", 0).as_deref(), Some("named"));
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Документ ищется тем же хешем, каким был положен.
    ///
    /// ## Что было
    ///
    /// Таблица буфера заполнялась двумя разными функциями. Плоский путь
    /// (`add_inner`) клал по [`crate::bloom::hash`], путь со вложенностью
    /// (`add_cells_inner`) — по `word_hash`, а искали все — `kill_buffered`,
    /// `buffered_doc`, `buffered_value` — по первой. Проба начиналась не с той
    /// корзины и упиралась в первую пустую: документ, положенный со
    /// вложенностью, для замены и удаления не существовал.
    ///
    /// Последствие названо прямо над самой таблицей: «замена не видит того, что
    /// сама же положила секунду назад, и кладёт вторую живую версию рядом».
    /// Через `crates/svindb-server/src/nested.rs` этим путём идёт всякий
    /// документ с массивом или вложенным объектом.
    ///
    /// ## Почему это пряталось
    ///
    /// `Slots::grow` перекладывает **всё** по правильному хешу. Стоило таблице
    /// вырасти — и ранее положенное становилось находимым. Дефект то был, то
    /// исчезал, в зависимости от того, случился ли рост после вставки; поэтому
    /// проверка берёт один документ на пустой таблице, где роста заведомо нет.
    #[test]
    fn a_nested_document_is_found_by_the_hash_it_was_stored_with() {
        let dir = std::env::temp_dir()
            .join(format!("svindb-slots-hash-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&dir).ok();
        let mut ix = Indexer::typed(
            &dir,
            vec!["text".into(), "emoji".into()],
            vec![1.0, 1.0],
            vec![crate::index::Kind::Text, crate::index::Kind::Keyword],
            10_000,
        );
        ix.set_groups(vec![0, 1], vec![String::new(), "reactions".into()]);

        // Идентификаторов несколько: у одного могло бы случайно совпасть
        // начало пробы, и проверка прошла бы ни на чём.
        let ids: Vec<String> = (0..32).map(|i| format!("вложенный-{i}")).collect();
        for id in &ids {
            let cells = vec![
                Cell { field: 0, slot: 0, text: "тело документа" },
                Cell { field: 1, slot: 0, text: "up" },
            ];
            ix.add_cells(id, &[1, 1], &cells);
        }
        for id in &ids {
            assert!(
                ix.buffered_doc(id).is_some(),
                "точечное чтение не нашло в буфере {id}, только что туда положенный"
            );
        }
        for id in &ids {
            assert_eq!(
                ix.kill_buffered(id),
                1,
                "замена не нашла в буфере {id} — рядом легла бы вторая живая версия"
            );
        }
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Оба пути кладут в одну таблицу, и она обязана держать их вперемешку.
    #[test]
    fn the_flat_and_the_nested_paths_share_one_table() {
        let dir = std::env::temp_dir()
            .join(format!("svindb-slots-mixed-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&dir).ok();
        let mut ix = Indexer::typed(
            &dir,
            vec!["text".into(), "emoji".into()],
            vec![1.0, 1.0],
            vec![crate::index::Kind::Text, crate::index::Kind::Keyword],
            10_000,
        );
        ix.set_groups(vec![0, 1], vec![String::new(), "reactions".into()]);
        for i in 0..16 {
            ix.add(&format!("плоский-{i}"), &["тело", "up"]);
            let cells = vec![
                Cell { field: 0, slot: 0, text: "тело" },
                Cell { field: 1, slot: 0, text: "up" },
            ];
            ix.add_cells(&format!("вложенный-{i}"), &[1, 1], &cells);
        }
        for i in 0..16 {
            assert_eq!(ix.kill_buffered(&format!("плоский-{i}")), 1, "потерян плоский {i}");
            assert_eq!(ix.kill_buffered(&format!("вложенный-{i}")), 1, "потерян вложенный {i}");
        }
        std::fs::remove_dir_all(&dir).ok();
    }
}

#[cfg(test)]
mod delta_publication_tests {
    use super::*;

    #[test]
    fn successive_deltas_encode_only_new_rows_and_keep_numeric_arrays() {
        let root = std::env::temp_dir().join(format!("svindb-delta-rows-{}", std::process::id()));
        let mut writer = Indexer::typed_stored(
            &root.to_string_lossy(),
            vec!["body".into(), "nums".into()],
            vec![1.0, 1.0],
            vec![Kind::Text, Kind::Int64],
            vec![true, false],
            1000,
        );
        assert!(writer.build_live_delta("empty").unwrap().is_none());
        let first_values = encode_multi(&["1".into(), "1".into(), "2".into()]);
        writer.add("a", &[&format!("{} first", "common ".repeat(300)), &first_values]);
        let first = writer.build_live_delta("first-delta").unwrap().unwrap();
        assert_eq!(first.docs, 1);
        assert!(writer.buf.delta.keys.is_empty());
        let second_values = encode_multi(&["9".into(), "10".into()]);
        let mut batch = writer.detached();
        batch.add("b", &[&format!("{} second", "common ".repeat(300)), &second_values]);
        writer.absorb(&mut batch);
        assert!(!writer.buf.delta.keys.iter().any(|key| key.get(4..) == Some(b"first")));
        let second = writer.build_live_delta("second-delta").unwrap().unwrap();
        assert_eq!(second.docs, 1, "старый префикс повторно попал в delta");
        assert_eq!(
            first.fields[1].multi_column.as_ref().unwrap().get(0).unwrap().collect::<Vec<_>>(),
            [1, 1, 2]
        );
        assert_eq!(
            second.fields[1].multi_column.as_ref().unwrap().get(0).unwrap().collect::<Vec<_>>(),
            [9, 10]
        );
        assert_eq!(crate::ids::Ids::open(&second.src, second.docs).get(0).as_deref(), Some("b"));
        assert_eq!(writer.buf.delta.published_docs, 2);
        assert!(writer.build_live_delta("unchanged").unwrap().is_none());
        assert!(!root.join(crate::manifest::FILE).exists(), "refresh пишет manifest");
        assert!(!root.join("seg0000").exists(), "refresh создал physical segment");
        let pieces = crate::Segments::from_parts(vec![first, second], vec![0, 1]);
        let whole = crate::Segments::from_parts(
            vec![writer.build_live("whole").unwrap().unwrap()],
            vec![0],
        );
        let spec = crate::segments::QuerySpec {
            words: vec![crate::segments::SpecWord {
                fid: 0,
                terms: vec![crate::segments::Term::parse("common")],
                given: None,
            }],
            k: 10,
            ..Default::default()
        };
        let a = pieces.search(&spec);
        let b = whole.search(&spec);
        assert_eq!(a.hits.len(), 2);
        for (a, b) in a.hits.iter().zip(&b.hits) {
            assert_eq!(a.doc, b.doc);
            assert!(
                (a.score - b.score).abs() < 1e-12,
                "doc={} delta={} whole={} delta_avg={} whole_avg={}",
                a.doc,
                a.score,
                b.score,
                pieces.list[a.segment].fields[0].avgdl,
                whole.list[0].fields[0].avgdl
            );
        }
        drop((pieces, whole, writer));
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn failed_delta_does_not_consume_the_epoch_or_pending_keys() {
        let root = std::env::temp_dir().join(format!("svindb-delta-retry-{}", std::process::id()));
        let mut writer =
            Indexer::new(&root.to_string_lossy(), vec!["body".into()], vec![1.0], 1000);
        writer.add("a", &["first"]);
        let first = writer.build_live_delta("first").unwrap().unwrap();
        writer.add("b", &["second"]);
        let epoch = writer.buf.delta.epoch;
        let keys = writer.buf.delta.keys.len();
        let norm = writer.buf.norms[0].pop().unwrap();
        assert!(writer.build_live_delta("broken").is_err());
        assert_eq!(writer.buf.delta.epoch, epoch);
        assert_eq!(writer.buf.delta.keys.len(), keys);
        assert_eq!(writer.buf.delta.published_docs, 1);
        writer.buf.norms[0].push(norm);
        let second = writer.build_live_delta("retry").unwrap().unwrap();
        assert_eq!(second.docs, 1);
        assert_eq!(first.fetch(0, 0).as_deref(), Some(b"first".as_slice()));
        assert_eq!(second.fetch(0, 0).as_deref(), Some(b"second".as_slice()));
        drop((first, second, writer));
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn nested_delta_rebases_units_and_large_tf_without_copying_old_slots() {
        let root = std::env::temp_dir().join(format!("svindb-delta-slots-{}", std::process::id()));
        let mut writer = Indexer::typed_stored(
            &root.to_string_lossy(),
            vec!["tag".into(), "nums".into()],
            vec![1.0, 1.0],
            vec![Kind::KeywordExact, Kind::Int64],
            vec![false, false],
            1000,
        );
        writer.set_groups(vec![1, 1], vec![String::new(), "items".into()]);
        let tags = encode_multi(&["red".into(), "blue".into()]);
        let numbers = encode_multi(&["7".into(), "7".into(), "9".into()]);
        for part in 0..2 {
            let cells: Vec<_> = (0..300)
                .flat_map(|slot| {
                    [Cell { field: 0, slot, text: &tags }, Cell { field: 1, slot, text: &numbers }]
                })
                .collect();
            writer.add_cells(&part.to_string(), &[1, 300], &cells);
            let view = writer.build_live_delta(&format!("part-{part}")).unwrap().unwrap();
            assert_eq!(view.docs, 1);
            assert_eq!(view.slots[1].units(), 300);
            for unit in 0..300 {
                assert_eq!(
                    view.fields[0].multi_column.as_ref().unwrap().get(unit).unwrap().count(),
                    2
                );
                assert_eq!(
                    view.fields[1]
                        .multi_column
                        .as_ref()
                        .unwrap()
                        .get(unit)
                        .unwrap()
                        .collect::<Vec<_>>(),
                    [7, 7, 9]
                );
            }
        }
        assert_eq!(writer.buf.delta.published_units, [2, 600]);
        drop(writer);
        std::fs::remove_dir_all(root).unwrap();
    }
}

#[cfg(test)]
mod buffer_capacity_tests {
    use super::*;

    /// Буферы ходят по кругу, а не заводятся на каждый сегмент.
    ///
    /// ## Что было
    ///
    /// При передаче буфера писателю на его место вставал **свежий**
    /// `Buffer::new`, а возвращённый — с прижившимися ёмкостями, таблицей на
    /// десятки тысяч слов и векторами на сотни тысяч документов — брался себе
    /// только если текущий пуст. Под плотной заливкой он пуст почти никогда:
    /// результат первым забирает `poll` с пути свежести, когда в новый буфер
    /// уже набрали. Возвращённый выбрасывался, и цикл отращивал ёмкости заново
    /// лестницей удвоений. А когда усыновление всё же срабатывало,
    /// выбрасывался свежесозданный — то есть заводился он в любом случае.
    ///
    /// Цена измерена на стенде: пятнадцать миллионов документов, срок свежести
    /// в тридцать раз реже — расход падал на 27%, ровно потому что буфер
    /// успевал быть усыновлённым.
    ///
    /// ## Что проверяется
    ///
    /// Число заведённых буферов, а не занятая память: память меряется на
    /// стенде, а здесь важно, что оборот замкнут. Буферов в работе ровно два —
    /// набираемый и отданный, — поэтому сколько бы сегментов ни легло, завести
    /// их должны не больше двух. Проверка не зависит от того, кто успел
    /// первым: и при усыновлении, и через запас круг замыкается одинаково.
    #[test]
    fn buffers_go_round_instead_of_being_made_anew_for_every_segment() {
        let dir = std::env::temp_dir()
            .join(format!("svindb-spare-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&dir).ok();
        let mut ix = Indexer::typed(
            &dir,
            vec!["text".into()],
            vec![1.0],
            vec![crate::index::Kind::Text],
            64,
        );
        // Десять сегментов: если бы буфер заводился на каждый, их стало бы
        // одиннадцать.
        for i in 0..640 {
            ix.add(&format!("д{i}"), &["слово тело"]);
        }
        ix.drain();
        assert!(
            ix.buffers_made <= 2,
            "заведено буферов: {} при десяти сегментах — ёмкости отращиваются заново каждый цикл",
            ix.buffers_made
        );
        // Круг обязан быть замкнут: один буфер на руках, второй в запасе.
        assert!(ix.spare.is_some(), "второй буфер круга потерян");
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Крупная пачка не поднимает пол памяти навсегда.
    ///
    /// `Vec::clear` держит ёмкость, и для обычного хода это верно: следующий
    /// сегмент наберёт примерно столько же, а перевыделение на каждом сбросе —
    /// работа впустую. Но тогда ёмкость становится высокой водой, которая не
    /// спадает **никогда**: одна пачка вдесятеро крупнее обычной поднимает
    /// память процесса до конца его жизни, и вернуть её ядру нечем — это куча, а
    /// не кеш страниц.
    ///
    /// Отдаётся она не сразу, и так и задумано: сразу после крупного сегмента
    /// ёмкость ещё оправдана тем, что только что было набрано. Лишней она
    /// становится, когда следующий сегмент выходит много меньше, — и вот тогда
    /// отдаётся. Именно это и есть тот случай, ради которого всё нужно: одна
    /// крупная пачка среди обычных.
    ///
    /// Проверяются **обе** половины договора, потому что каждая по отдельности
    /// достигается тривиально и неверно: отдавать всегда — перевыделение на
    /// каждом сбросе, не отдавать никогда — прежнее поведение.
    #[test]
    fn a_huge_batch_does_not_raise_the_floor_forever() {
        let mut b = Buffer::new(2);
        let fill = |b: &mut Buffer, n: usize| {
            for i in 0..n {
                b.ids.push(format!("d{i}"));
                b.dead.push(false);
                b.norms[0].push(1);
                b.vals[0].push("x".repeat(8));
            }
        };

        // Одна крупная пачка среди обычных.
        fill(&mut b, 20_000);
        let big = b.ids.capacity();
        assert!(big >= 20_000, "ёмкость не набралась: {big}");
        b.clear();

        // Следующий сегмент — обычный. Здесь-то ёмкость и перестаёт быть
        // оправданной.
        fill(&mut b, 200);
        b.clear();
        assert!(
            b.ids.capacity() < big / 4,
            "ёмкость идентификаторов не отдана: было {big}, стало {}",
            b.ids.capacity()
        );
        assert!(b.norms[0].capacity() < big / 4, "ёмкость норм не отдана");
        assert!(b.vals[0].capacity() < big / 4, "ёмкость значений не отдана");

        // Обычный ход: сегменты похожего размера — ёмкость обязана остаться.
        fill(&mut b, 300);
        let warm = b.ids.capacity();
        b.clear();
        fill(&mut b, 300);
        assert_eq!(
            b.ids.capacity(),
            warm,
            "ёмкость отдана на похожих сегментах — перевыделение на каждом сбросе"
        );
        b.clear();
    }
}

#[cfg(test)]
mod ceiling_tests {
    use super::*;

    /// Потолок буфера — ровно два порога сброса, и он производный.
    ///
    /// Проверяется правило, а не число: порог выводится из доступной памяти, и
    /// на машине с шестнадцатью гигабайтами он окажется меньше сам. Прибей
    /// здесь величину — и проверка перестала бы отвечать за то, ради чего
    /// заведена.
    ///
    /// Двойка — не подобранный запас, а само устройство оборота: буферов в
    /// работе ровно два, набираемый и отданный писателю, больше взяться
    /// неоткуда (см. `spare`). Значит и памяти под них нужно ровно на два.
    ///
    /// Само осаживание здесь не проверить: перерасти потолок буфер может лишь
    /// при занятом писателе, а свободный забирает его по порогу. Поведение под
    /// отстающим писателем меряется на стенде с урезанной памятью.
    #[test]
    fn the_ceiling_is_two_thresholds_and_follows_them() {
        let dir = std::env::temp_dir()
            .join(format!("svindb-ceiling-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&dir).ok();
        let mut ix = Indexer::typed(
            &dir,
            vec!["text".into()],
            vec![1.0],
            vec![crate::index::Kind::Text],
            1_000_000,
        );
        ix.set_flush_bytes(0);
        assert_eq!(ix.memory_ceiling(), 0, "без порога потолка быть не может");
        assert!(!ix.over_memory_ceiling(), "нулевой потолок никого не осаживает");

        for threshold in [64 * 1024usize, 3 * 1024 * 1024, 512 * 1024 * 1024] {
            ix.set_flush_bytes(threshold);
            assert_eq!(
                ix.memory_ceiling(),
                threshold * 2,
                "потолок обязан идти за порогом, а не жить своей жизнью"
            );
        }
        // Пустой буфер не может быть переросшим ни при каком пороге.
        assert!(!ix.over_memory_ceiling(), "пустой буфер перерос потолок");
        std::fs::remove_dir_all(&dir).ok();
    }
}

#[cfg(test)]
mod buffer_share_tests {
    use super::*;

    /// Порог сброса никогда не обещает больше, чем доля от доступного.
    ///
    /// Прежде пол `BUFFER_MIN` перебивал долю, и на малой машине буфер получал
    /// больше, чем машина могла дать: два живых буфера по двести пятьдесят
    /// шесть мегабайт из гигабайта, плюс доля слияния, плюс кеш страниц — и
    /// ядро снимало процесс. Проверка идёт по правилу, а не по прогону:
    /// прогон под настоящим пределом стоит минут, а ошибка здесь
    /// арифметическая.
    #[test]
    fn the_flush_threshold_never_promises_more_than_its_share() {
        // Доля приёма теперь берётся из общего реестра и делится надвое: в
        // обороте два буфера. Правило то же, что и в `default_flush_bytes`, и
        // считается тем же выражением — разойдись они, проверка отвечала бы не
        // про то, что делает узел.
        let ingest_share = |ram: u64| -> u64 {
            let control = crate::govern::CONTROL_BYTES.min(ram / 2);
            let rest = ram.saturating_sub(control);
            let pct = crate::govern::shares_pct()
                .iter()
                .find(|(c, _)| *c == crate::govern::Class::Ingest)
                .map_or(0, |(_, p)| *p);
            rest / 100 * pct / 2
        };
        let want = |ram: u64| -> u64 {
            let share = ingest_share(ram);
            share.min(BUFFER_MAX).max(BUFFER_FLOOR.min(share.max(BUFFER_FLOOR)))
        };
        for ram_mb in [64u64, 128, 256, 512, 1024, 2048, 4096, 16384, 65536] {
            let ram = ram_mb << 20;
            let got = want(ram);
            let share = ingest_share(ram);
            assert!(
                got <= share.max(BUFFER_FLOOR),
                "на {ram_mb} МБ порог {got} превысил долю {share}"
            );
            // Двух живых буферов должно хватать место при доле в десять
            // процентов: иначе один приём съедает больше пятой части машины.
            assert!(
                got * 2 <= ram / 4 || got == BUFFER_FLOOR,
                "на {ram_mb} МБ два буфера по {got} — это больше четверти машины"
            );
        }
        // Крупная машина по-прежнему получает свои четыре гигабайта потолка.
        assert_eq!(want(128 << 30), BUFFER_MAX, "потолок на большой машине не тронут");
        // Совсем малая машина не уходит в вырожденно мелкий буфер.
        assert_eq!(want(16 << 20), BUFFER_FLOOR, "ниже пола опускаться нельзя");
    }
}

#[cfg(test)]
mod live_twin_tests {
    use super::*;

    /// Двойник не собирается у буфера, который политика не обещает поиску.
    ///
    /// Живой двойник отданного буфера закрывает окно невидимости на время
    /// записи сегмента. Но состав решает про буфер по пределу `live_max_docs`
    /// и на крупном отвечает «не показывать»: видимость такого буфера
    /// возвращается к сбросу на диск. Двойник же собирался **безусловно** —
    /// закрывал окно, которое уже объявлено открытым, и стоил при этом полного
    /// повторного разбора всех документов буфера под замком приёма.
    ///
    /// Проверяется по обе стороны предела: под ним двойник обязан быть, над ним
    /// обязан отсутствовать. Проверка только одной стороны прошла бы и на
    /// коде, который не собирает двойника никогда, — а это потеря свежести.
    #[test]
    fn the_live_twin_is_built_only_while_the_buffer_is_promised_to_search() {
        let make = |name: &str, limit: u32, docs: u32| -> bool {
            let dir = std::env::temp_dir()
                .join(format!("svindb-twin-{name}-{}", std::process::id()))
                .to_string_lossy()
                .to_string();
            std::fs::remove_dir_all(&dir).ok();
            let mut ix = Indexer::typed(
                &dir,
                vec!["text".into()],
                vec![1.0],
                vec![crate::index::Kind::Text],
                docs,
            );
            ix.set_live_max_docs(limit);
            for i in 0..docs {
                ix.add(&format!("д{i}"), &["слово тело"]);
            }
            // `add` сбросил сам на пороге `per_segment` — двойник уже решён.
            let built = ix.twins_built > 0 && ix.twins_skipped == 0;
            ix.drain();
            std::fs::remove_dir_all(&dir).ok();
            built
        };
        assert!(
            make("под", 64, 64),
            "буфер в пределах обещанного — двойник обязан быть, иначе теряется свежесть"
        );
        assert!(
            !make("над", 8, 64),
            "буфер сверх предела — двойника быть не должно: состав его всё равно не покажет"
        );
    }
}

#[cfg(test)]
mod frozen_lifecycle_tests {
    use super::*;
    use std::sync::{Arc, Mutex};

    fn writer(name: &str, limit: usize) -> (Indexer, String) {
        let root =
            std::env::temp_dir().join(format!("svindb-frozen-{name}-{}", std::process::id()));
        let root = root.to_string_lossy().to_string();
        let mut writer = Indexer::new(&root, vec!["body".into()], vec![1.0], 1000);
        writer.enable_frozen_memtables(limit).unwrap();
        (writer, root)
    }

    fn view(writer: &mut Indexer, root: &str) -> crate::Segments {
        let layout = writer.layout.clone();
        let _locked = layout.lock().unwrap();
        writer.poll();
        let mut view = crate::Segments::load(root).unwrap();
        let generations = writer.frozen_generations();
        for generation in &generations {
            view = view.with_live(generation.index.clone()).unwrap();
        }
        let refs: Vec<_> = view.list.iter().map(Arc::as_ref).collect();
        for (keeper, ids) in writer.take_superseded() {
            crate::maintain::supersede_in(&refs, &keeper, &ids).unwrap();
        }
        // Последний хранитель каждого ID побеждает даже при двух публикациях
        // одной замены подряд; старший keeper не должен погасить младший.
        let mut seen = std::collections::HashSet::new();
        for generation in generations.iter().rev() {
            let ids: Vec<_> = generation
                .superseded
                .iter()
                .filter(|id| seen.insert((*id).clone()))
                .cloned()
                .collect();
            crate::maintain::supersede_in(&refs, &generation.index.dir, &ids).unwrap();
        }
        view
    }

    fn bodies(view: &crate::Segments) -> Vec<String> {
        let mut values: Vec<_> = view
            .list
            .iter()
            .flat_map(|index| {
                (0..index.docs as u32)
                    .filter(|doc| index.is_live(*doc))
                    .map(|doc| String::from_utf8(index.fetch(doc, 0).unwrap()).unwrap())
            })
            .collect();
        values.sort();
        values
    }

    #[test]
    fn successive_updates_keep_the_newest_generation_then_coalesce_in_memory() {
        let (mut writer, root) = writer("updates", 2);
        writer.replace("id", &["first"]);
        writer.freeze_live().unwrap();
        let first = view(&mut writer, &root);
        assert_eq!(bodies(&first), ["first"]);
        writer.replace("id", &["second"]);
        writer.freeze_live().unwrap();
        assert_eq!(writer.frozen_generations().len(), 2);
        assert_eq!(bodies(&view(&mut writer, &root)), ["second"]);
        writer.replace("id", &["third"]);
        writer.freeze_live().unwrap();
        assert_eq!(writer.frozen_generations().len(), 1);
        assert_eq!(bodies(&view(&mut writer, &root)), ["third"]);
        assert!(crate::manifest::segments(&root).is_empty(), "refresh записал диск");
        writer.add("other", &["fourth"]);
        writer.freeze_live().unwrap();
        assert_eq!(bodies(&view(&mut writer, &root)), ["fourth", "third"]);
        writer.flush_now();
        assert!(writer.frozen_generations().is_empty());
        assert_eq!(bodies(&view(&mut writer, &root)), ["fourth", "third"]);
        drop((writer, first));
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn frozen_source_bytes_are_admitted_with_the_raw_buffer_not_as_disk_zero() {
        let (mut writer, root) = writer("memory-admission", 32);
        writer.add("a", &["alpha beta gamma"]);
        writer.freeze_live().unwrap();
        let frozen = writer.frozen_memory_bytes();
        assert!(frozen > 0, "encoded frozen source не имеет полезных bytes");
        assert!(writer.buffered_bytes() >= frozen, "frozen bytes не вошли в admission");
        assert_eq!(writer.frozen_generation_count(), 1);
        drop(writer);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn collecting_inflight_does_not_drop_new_active_generations() {
        let (mut writer, root) = writer("inflight", 32);
        let layout = Arc::new(Mutex::new(()));
        writer.background(layout.clone());
        writer.add("a", &["alpha"]);
        writer.freeze_live().unwrap();
        writer.add("b", &["beta"]);
        // Manifest publication гарантированно заблокирована; проверяем
        // настоящий inflight, а не удачный timing быстрого диска.
        let blocked = layout.lock().unwrap();
        writer.flush();
        assert!(writer.flush_inflight());
        assert_eq!(writer.frozen_generations().len(), 2, "не заморожен последний суффикс");
        writer.add("c", &["gamma"]);
        writer.freeze_live().unwrap();
        assert_eq!(writer.frozen_generations().len(), 3);
        let mut inflight_view = crate::Segments::load(&root).unwrap();
        for generation in writer.frozen_generations() {
            inflight_view = inflight_view.with_live(generation.index).unwrap();
        }
        assert_eq!(bodies(&inflight_view), ["alpha", "beta", "gamma"]);
        drop(blocked);
        writer.drain();
        assert_eq!(writer.frozen_generations().len(), 1, "забор стёр active generation");
        assert_eq!(bodies(&view(&mut writer, &root)), ["alpha", "beta", "gamma"]);
        writer.flush_now();
        assert_eq!(bodies(&view(&mut writer, &root)), ["alpha", "beta", "gamma"]);
        drop(writer);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn failed_coalescing_keeps_old_generations_and_retries_same_suffix() {
        let (mut writer, root) = writer("retry", 1);
        writer.add("a", &["alpha"]);
        writer.freeze_live().unwrap();
        let old = writer.frozen_generations()[0].index.clone();
        // Более одной dictionary anchor: маленький lowered ceiling должен
        // дать штатный fallible отказ encoder, а не ломать raw invariant.
        let body = (0..128).map(|n| format!("word{n:03}")).collect::<Vec<_>>().join(" ");
        writer.add("b", &[&body]);
        let ceiling = crate::dict::lower_offset_ceiling(1);
        assert!(writer.freeze_live().is_err());
        assert!(Arc::ptr_eq(&old, &writer.frozen_generations()[0].index));
        assert_eq!(writer.buf.delta.published_docs, 1);
        drop(ceiling);
        writer.freeze_live().unwrap();
        assert_eq!(bodies(&view(&mut writer, &root)), ["alpha".to_string(), body]);
        drop((old, writer));
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn a_second_flush_restores_its_generations_after_collecting_the_first() {
        let (mut writer, root) = writer("double-flush", 32);
        writer.background(Arc::new(Mutex::new(())));
        writer.add("a", &["alpha"]);
        writer.flush();
        assert!(writer.flush_inflight());
        writer.add("b", &["beta"]);
        writer.freeze_live().unwrap();
        writer.add("c", &["gamma"]);
        // Только collect/poll снимает inflight, не завершение worker само по
        // себе. Второй flush гарантированно входит в ветку collect первого.
        assert!(writer.flush_inflight());
        writer.flush();
        assert!(writer.flush_inflight());
        let generations = writer.frozen_generations();
        assert_eq!(generations.len(), 2, "collect первого снял frozen views второго");
        assert!(generations.iter().all(|generation| generation.index.docs == 1));
        assert_eq!(bodies(&view(&mut writer, &root)), ["alpha", "beta", "gamma"]);
        writer.drain();
        assert!(writer.frozen_generations().is_empty());
        assert_eq!(bodies(&view(&mut writer, &root)), ["alpha", "beta", "gamma"]);
        drop(writer);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn a_failed_final_freeze_never_moves_the_buffer_or_checkpoint() {
        let (mut writer, root) = writer("flush-refusal", 32);
        writer.add("a", &["alpha"]);
        writer.freeze_live().unwrap();
        let body = (0..128).map(|n| format!("word{n:03}")).collect::<Vec<_>>().join(" ");
        writer.add("b", &[&body]);
        writer.seq = 7;
        {
            let _ceiling = crate::dict::lower_offset_ceiling(1);
            writer.flush();
        }
        assert!(writer.poisoned().is_some_and(|why| why.contains("frozen publication")));
        assert_eq!(writer.active_buffered(), 2, "ошибка отдала неподготовленный буфер");
        assert_eq!(writer.flushed_seq, 0);
        assert_eq!(writer.frozen_generations().len(), 1);
        assert!(crate::manifest::segments(&root).is_empty());
        drop(writer);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn an_unpublished_first_segment_is_not_discovered_by_directory_fallback() {
        let (mut writer, root) = writer("initial-manifest", 32);
        let layout = Arc::new(Mutex::new(()));
        writer.background(layout.clone());
        assert_eq!(crate::manifest::listing(&root), Some(Vec::new()));
        writer.add("a", &["alpha"]);
        let blocked = layout.lock().unwrap();
        writer.flush();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while !std::path::Path::new(&format!("{root}/seg0000/head.tsv")).exists() {
            assert!(std::time::Instant::now() < deadline, "не появился завершённый head");
            std::thread::yield_now();
        }
        assert!(writer.flush_inflight());
        assert!(
            crate::Segments::load(&root).unwrap().list.is_empty(),
            "head.tsv подменил обязательную публикацию manifest"
        );
        drop(blocked);
        writer.drain();
        assert_eq!(bodies(&view(&mut writer, &root)), ["alpha"]);
        drop(writer);
        std::fs::remove_dir_all(root).unwrap();
    }
}

#[cfg(test)]
mod segment_number_tests {
    use super::*;

    fn tmp(name: &str) -> String {
        let dir = std::env::temp_dir()
            .join(format!("svindb-segment-number-{name}-{}", std::process::id()))
            .to_string_lossy()
            .to_string();
        std::fs::remove_dir_all(&dir).ok();
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    /// Разреженная нумерация не должна превращаться в число «дописанных».
    ///
    /// Счётчик используется как датчик смены состава. Его значение вправе
    /// начинаться с числа существующих сегментов, но не с наибольшего номера:
    /// после слияний между ними обычны дыры.
    #[test]
    fn sparse_existing_numbers_do_not_inflate_the_landed_counter() {
        let dir = tmp("sparse");
        for name in ["seg0001", "seg9999"] {
            std::fs::create_dir_all(format!("{dir}/{name}")).unwrap();
        }
        let ix = Indexer::new(&dir, vec!["body".into()], vec![1.0], 100);
        assert_eq!(ix.next_segment, 10_000);
        assert_eq!(ix.segments(), 2, "дыры в именах посчитались как сегменты");
        std::fs::remove_dir_all(&dir).ok();
    }

    /// Предельное имя не заворачивает следующий номер к нулю.
    #[test]
    fn an_exhausted_segment_number_poisoned_ingest_before_moving_the_buffer() {
        let dir = tmp("exhausted");
        std::fs::create_dir_all(format!("{dir}/seg{}", u64::MAX)).unwrap();
        let mut ix = Indexer::new(&dir, vec!["body".into()], vec![1.0], 100);
        assert!(
            ix.poisoned().is_some_and(|why| why.contains("исчерпана")),
            "предельное имя не остановило приём: {:?}",
            ix.poisoned()
        );
        // Даже прямой вызов сброса ничего не создаёт и не переиспользует
        // seg0000: липкий отказ обязан сработать до работы с буфером.
        ix.add("док", &["тело"]);
        ix.flush();
        assert!(!std::path::Path::new(&format!("{dir}/seg0000")).exists());
        std::fs::remove_dir_all(&dir).ok();
    }
}
